window.POEM_DB=window.POEM_DB||{};POEM_DB["qing_011"]={"n":"许传霈","dyn":"清","poems":[{"t":"斋中偶占","f":"五言绝句","c":["桃花复桂花，寒斋不冷落。","二月雨红雨，八月雨金粟。"]},{"t":"九日登岘山","f":"五言绝句","c":["重九登高日，同人到岘山。","堂堂怀逸老，红树白云閒。"]},{"t":"登飞英塔","f":"七言律诗","c":["丹梯缭绕绝尘埃，苕霅风光面面来。","画里峰峦天外落，地中钟磬寺前回。","飞檐铃语当头答，负郭人家入望该。","寻到塔心还有塔，此身恍若住蓬莱。"]},{"t":"夏夜口占","f":"七言绝句","c":["重桂堂前桂荫浓，同侪夜话豁襟胸。","二三女弟閒无事，细数天宁寺撞钟。"]},{"t":"咏庭中白蘋花","f":"七言绝句","c":["朝开夜合出芳姿，小草居然也准时。","吾爱斜阳风动处，閒情多半催新诗。"]},{"t":"侍母归家 其一","f":"七言绝句","c":["布帆无恙挂天涯，未惯行程问日斜。","船上老人频指点，曹江西去阿侬家。"]},{"t":"侍母归家 其二","f":"七言绝句","c":["一峰盘绕势崔巍，老屋三间傍水隈。","堂上白头人几个，杖藜言笑出门来。"]},{"t":"渡钱江","f":"五言绝句","c":["浪高船板低，风紧布帆重。","四望浑无涯，水天离一缝。"]},{"t":"落花","f":"七言绝句","c":["一庭芳草堕残红，消尽春光满眼中。","大半东皇妒艳色，莫教零落怨东风。"]},{"t":"夏夜雨坐","f":"七言律诗","c":["黑云四盖暗山城，未冒峰头雨已行。","电逐长空天地昼，雷鸣岩谷树林兵。","檐前直泻无穷水，巷里时沈击柝声。","夜静高楼风色定，依然星斗一江清。"]},{"t":"雨中舟行 其一","f":"七言绝句","c":["几扇柴扉临水开，稻田湾里橹声来。","波纹细皱江如练，雨不催诗诗自催。"]},{"t":"雨中舟行 其二","f":"七言绝句","c":["天空岸远认模糊，江树濛濛山有无。","一幅丹青浓水墨，教人重绘辋川图。"]},{"t":"秋夜泛舟","f":"七言律诗","c":["秋迎客路十分凉，烟水扁舟引兴长。","两岸芦花翻雪白，一江木叶入秋黄。","天街空际霜初落，银汉无声月自行。","归橹音清闻欸乃，逍遥疑在梦魂乡。"]},{"t":"家大人集千字文贺胡秀才吉席敬用原韵纪事","f":"七言律诗","c":["流离八载及虞城，举目无亲孰达情。","乃字终能贞素志，相攸合使结良盟。","家庭静对陈诗酒，母弟欣谈解甲兵。","从此唱随歌永好，百年夫妻凤凰鸣。"]},{"t":"侍家大人宴金罍观","f":"五言律诗","c":["梓里欣情话，荷风残夏凉。","山低云树绿，城近稻田黄。","煮石仙人井，清心曲水觞。","晚来不归去，策杖喜高堂。"]},{"t":"秋夜半湖棹归","f":"七言律诗","c":["暮云秋树郁苍茫，一叶扁舟出野塘。","水接天光天似水，霜霏月下月如霜。","几家灯火前村近，满地虫声客梦凉。","浩浩御风忘所止，不知漏尽几分长。"]},{"t":"秋夜独坐","f":"五言律诗","c":["木落宵深候，无言独上楼。","天空孤月小，窗冷一灯幽。","蟋蟀声中老，蜘蛛网里浮。","不知今夜望，几处别离愁。"]},{"t":"同褚子方、刘小墅、范桐轩、高龚甫游卧龙山，登望海亭","f":"五言古诗","c":["刘褚与高范，邀我游卧龙。","卧龙山色秀，盘郁越城雄。","绝顶望海亭，拾级兴何浓。","半壁闻松吼，高树罩烟濛。","下览城市小，鉴湖豁双瞳。","冻云千里平，落叶万山冬。","夕阳射西岩，人影堕长空。","飘飘欲飞去，去访海若宫。","海若出招我，蜃楼架彩虹。","迷离极幻境，凛冽御朔风。","风鸣老龙吟，四望不可从。","长啸一声去，天黑归路匆。","忽闻山下寺，暮鼓打鼕鼕。","回首登临处，寒烟苍霭中。"]},{"t":"转至蓬莱阁","f":"七言律诗","c":["此身已得到瀛洲，镜水稽山面面收。","八百鉴湖归眼底，万家烟火起楼头。","钟闻山寺天催暮，风吼庭松客报秋。","壁上题诗苔迹扫，不愁归远独勾留。"]},{"t":"消寒夜集馀杭褚子耘子方，世交兄弟也。庚申避地来虞，结邻黄氏宇，每夕联消寒诗集，其子侄敦伯叔寅、予叔兄子承兄子乐斋与焉。一名小竹林以集，共七人云咏冬景五律分得酿雪","f":"五言律诗","c":["弥望云铺白，高楼雪景催。","香浮金谷酒，冷逗玉堂梅。","冻雀停檐噪，寒鸦结阵来。","须臾飞六出，驴背灞桥回。"]},{"t":"分得糟蟹","f":"七言绝句","c":["新酿开时晚稻红，霜螯买向五湖东。","醉乡风味知何似，一笑烦君入瓮中。"]},{"t":"咏越中名胜分得樵风泾","f":"七言律诗","c":["半肩樵采若耶中，暮向朝南一棹通。","拾箭有缘酬尔愿，行舟无碍仗神功。","挂帆应喜随波稳，归橹何虞扑面冲。","堪笑村人同往者，淹留难趁郑公风。"]},{"t":"分咏五代史 其一 梁敬翔","f":"七言律诗","c":["不辱新君洗涤诏，要知劲节本难污。","用兵卅载忠先帝，恸哭一朝见老奴。","笺刺偶传多俚语，春秋熟读识兵符。","直教愧死李崇政，枉自当年号丈夫。"]},{"t":"分咏五代史 其二 唐李存孝","f":"七言律诗","c":["上下飞来入阵中，一人两骑势如风。","铁檛手舞前无敌，重铠身披气自雄。","死愿见王伸宿愤，生还无罪建奇功。","太原慷慨悲车裂，异日相思泣乃公。"]},{"t":"分咏五代史 其三 汉杨邠","f":"七言律诗","c":["陛下禁声自有臣，不知大体汉杨邠。","直教礼乐为虚器，悉罢朝廷荫出身。","晚节广延门下客，敢言谏立耿夫人。","也知史传真堪用，课吏多抄亦雅驯。"]},{"t":"咏十国春秋分得蜀王建","f":"七言律诗","c":["从行负玺护銮舆，枕膝君王泣下嘘。","强据两川图僭窃，恩忘阿父肆诛锄。","军儿惯养名多赐，符瑞侈陈史屡书。","三十七年前蜀主，少时曾亦盗牛驴。"]},{"t":"分咏四花 其一 笔花","f":"五言绝句","c":["江郎本妙笔，绮语散云霞。","天心亦爱才，一梦灿生花。"]},{"t":"分咏四花 其二 剑花","f":"五言绝句","c":["古艳出芙蓉，手挥锋铦利。","秋水照人心，胡霜新淬试。"]},{"t":"分咏四花 其三 灯花","f":"五言绝句","c":["今夕独何夕，金粟灿银台。","红袖不忍剔，喜卜远人来。"]},{"t":"分咏四花 其四 冰花","f":"五言绝句","c":["前日浪花翻，今宵冰花簇。","著处皆白描，不待渴鸟啄。"]},{"t":"分咏老渔","f":"七言律诗","c":["寒江蓑笠老渔翁，浪迹生涯有小篷。","把酒酣眠忘岁月，持竿随意教儿童。","偶惊两鬓风霜里，长对一篙烟雨中。","为语桑榆须爱护，磻溪知已兆飞熊。"]},{"t":"咏伯牙琴","f":"五言律诗","c":["太息钟期去，哀哉祗破琴。","五弦千古感，一曲两人心。","流水空留调，高山孰赏音。","何如炊爨下，知己尚可寻。"]},{"t":"咏雪限麻牙瓜叉拿韵","f":"五言律诗","c":["满天六出拿，喜瑞手频叉。","忽种千亩玉，疑生万树牙。","尘无光比月，花散色如麻。","戏把琼瑶赠，应不报木瓜。"]},{"t":"咏梅限纤添尖黏帘韵","f":"五言律诗","c":["美人月点纤，数点傍轻帘。","陆凯江南寄，寿阳额上添。","影疏寻雪里，意冷锁花尖。","细摘和香嚼，芬芳满口黏。"]},{"t":"咏剑限巢郊胶坳抛韵","f":"七言律诗","c":["本同冠佩宝书巢，利试昆吾莫易抛。","一剑勋名留汉楚，三贤宠赐重庠胶。","干将神物藏山谷，河曲金人出水坳。","何日销为农父器，田功有事向东郊。"]},{"t":"咏镜限冬钟龙浓邛韵","f":"七言律诗","c":["未闻宫里景阳钟，已启妆台写翠浓。","自爱红颜非白发，还看带马复萦龙。","望蟾静对空悬相，化鹊偕谋莫致邛。","閒贴花黄添素额，寒梅数点报开冬。"]},{"t":"咏水车限南三酣韵","f":"七言绝句","c":["田家无雨苦耘三，斜架橘槔齐踏酣。","知是天工人可代，禾苗兴起亩东南。"]},{"t":"咏竹夫人","f":"七言律诗","c":["不怕蛾眉宠擅房，夫人却好卧牙床。","瘦怜一握围腰细，汗渍千行竟体香。","高节甘教居下陈，冰心果肯借清凉。","祗愁纨扇西风捐，别爱温和煮热汤。"]},{"t":"咏疆场金鼓声","f":"五言律诗","c":["刁斗声寒里，烽烟鼙鼓鸣。","阵开边月黑，战劲压风横。","将令衔枚肃，胡笳动地惊。","忽闻驰露布，饶唱入边城。"]},{"t":"咏校人烹鱼","f":"七言律诗","c":["漫道生还绿水浔，临渊有客羡鱼深。","畜池空忆波流逝，得所偏教釜爨寻。","出死那知仍入死，仁心终不敌机心。","相忘近习知多少，谁勒欺方作座箴。"]},{"t":"咏脚划船五排限江韵","f":"五言古诗","c":["一叶飘然去，生涯老越江。","歌来听踏踏，划去响跫跫。","篷小惟容膝，舟轻漫立艭。","凿开云影碎，踢破浪声淙。","赶驿如驰马，奔波异走尨。","前程弧箭疾，踞坐语言哤。","随水无劳纤，临风不挂䉶。","船头新设板，柁尾小开窗。","港窄行犹阔，桥低过亦降。","幻凫盘鸟道，画鹢集鱼矼。","略试推移力，还成欸乃腔。","青蚨囊换足，晚泊傍寒桩。"]},{"t":"咏糕老虎七排限先韵","f":"七言古诗","c":["万户千门仍旧俗，声声捣米度残年。","粘糕入谱时翻样，幻虎新抟貌自全。","竟体白描非仅额，两趺蹲坐俨深拳。","品分枣栗诸羞外，形出熊罴百兽先。","信手拈来真活泼，随心戏弄异雕镌。","点胭一样斑斓色，嵌豆双眸闪烁圆。","出柙直疑轻启罩，负嵎堪笑满登筵。","蓬蓬气上初蒸透，逐逐装成亦宛然。","绰有须眉能镇恶，虽无骨格也清坚。","承盘共乐乡风古，得句偏疑僻字传。","静对悬门同色相，惊看画壁證因缘。","优游卒岁添佳制，荐祖祀神礼告虔。"]},{"t":"咏竹林七贤分得王戎","f":"七言律诗","c":["阿戎清赏比浑优，鉴识人伦本隽流。","树在道边知苦李，利收水碓执牙筹。","论谈元妙留侯契，舒卷随时伯玉俦。","太息黄垆稽阮去，山河邈矣竹林游。"]},{"t":"家居集兴 其一","f":"七言律诗","c":["一椽聊寄寂寞中，环堵萧然地数弓。","扫径到门惟夜月，开窗惠我有清风。","占晴课雨庞眉叟，问字抄书总角童。","仰见高堂无恙候，贫家虽苦乐融融。"]},{"t":"家居集兴 其二","f":"七言律诗","c":["芸窗十载我何堪，漫道何堪亦自甘。","壁立未空书满架，儒餐不薄菜盈篮。","读馀时益趋庭训，客到犹欣剪烛谈。","闭户浑忘尘世事，青春閒过月将三。"]},{"t":"家居集兴 其三","f":"七言律诗","c":["满庭芳草绿阴繁，养得生机道自存。","鸟解看书常入室，犬知谢客日临门。","莫嗟来食泥炉冷，犹喜多年布被温。","最好晚来无个事，擘笺记事到黄昏。"]},{"t":"庭中牡丹","f":"七言绝句","c":["第一香开国色誇，壶觞排日赏家家。","祗因误入濂溪宅，未识君为富贵花。"]},{"t":"龙山道中","f":"七言绝句","c":["贪看山色步迟迟，瀑布松涛一路随。","最好曹娥江落日，暖风十里晚春时。"]},{"t":"晓发东山指石峰","f":"楚辞体","c":["晓风射篷冷，残月含江碧。","欸乃听声声，引入云水窟。","船头老人兴，遥遥语指石。","突兀蛟龙腾，氤氲风雨积。","夜长烟瘴迷，横矗晓天白。","山高路崎岖，断崖悬千尺。","低压打头来，崔嵬势欲掷。","一湾琵琶洲，天然形绣陌。","弹自不成声，长指日出没。","推篷證所闻，果尔挹秀色。","苍茫千百年，独立谁为客。","风流谢太傅，高隐适裙屐。","东眺复西眺，白云自今昔。","石兮不能言，云影望中隔。"]},{"t":"侍家大人至汤浦","f":"七言律诗","c":["曲尽江流路有无，故乡风景自清腴。","趁潮数艇挂帆席，傍岸千家隐荻芦。","樵斧声稀闻赤壁，渔歌唱晚起珠湖。","百年桑梓知依旧，珍重汤川忆钓图。"]},{"t":"烟火戏","f":"七言古诗","c":["迎神社赛话当前，今年风景胜前年。","喧填箫鼓竞龙船，如花小女堕鞦韆。","昨来烟火戏倍鲜，家家约伴乐流连。","初红一火细欲然，袅绕而上似炉烟。","忽化世界几大千，星流电闪逐风颠。","明珠万点缀镜圆，人物鸟兽绝妙传。","欲断复续相蝉联，才明复暗几变迁。","裙钗到处斗婵娟，鬓影衣香映后先。","笑语来朝费万钱，欲与此戏争新妍。","斯须人散月高悬，有童街巷始遗钿。"]},{"t":"春郊","f":"五言律诗","c":["日暖风和里，閒情立小溪。","山开平野阔，麦长远村低。","鸟语琼花院，人行绿柳堤。","几多春色醉，归去晚烟迷。"]},{"t":"春夜独步","f":"七言律诗","c":["游心浅淡了无思，夜静人归信步迟。","流水小桥明月夜，疏林野渡晚风时。","影随足去无痕著，绿向田生有鸟知。","自喜此中有佳趣，世间行乐孰如斯。"]},{"t":"落叶吟","f":"五言古诗","c":["既落可无生，既生可无落。","曷为初生时，欣欣绕城郭。","终至摇落秋，飘飘填沟壑。","生时何向荣，落时何彫弱。","空使有情人，对之心寂寞。","明月一林空，云气千山薄。","始知春风好，信道秋风恶。","秋风使人愁，春风使人乐。","嗟哉气运然，何自相乖错。","荣极自欲枯，枯极自能作。","于春有何恩，于秋有何虐。","消长须待时，得失本难度。","大哉造化功，循环无穷朔。"]},{"t":"月夜","f":"五言律诗","c":["郁郁庭松影，楼头明月悬。","渐离东壁角，已到北堂前。","冷逼虫声急，寒惊雁阵连。","疏星垂露里，一片有情天。"]},{"t":"中秋","f":"五言律诗","c":["去岁中秋节，高堂依老亲。","团栾明月夜，来照白头新。","此日孤成子，良宵望里身。","安能同逝也，不失过庭人。"]},{"t":"遗书","f":"五言绝句","c":["孤子身边籍，先人地下心。","不闻前夜教，流泪满衣襟。"]},{"t":"秋日","f":"五言律诗","c":["秋本无愁处，人愁秋亦愁。","举头征雁疾，到耳语蛩幽。","风木摇难定，江河去不休。","凭阑无限意，情月又横楼。"]},{"t":"秋夜","f":"五言律诗","c":["凉夜悬明月，嗟哉何处看。","独怜孤子苦，未识老亲寒。","零露霏林湿，长松照墓单。","欲思温寝被，回首泪难乾。"]},{"t":"述梦","f":"五言古诗","c":["独宿苦夜凉，有思苦夜长。","转辗不成寐，秋声满我房。","我父怜孤儿，入梦来相望。","梦魂侍父旁，形影推渺茫。","父念儿心伤，儿喜父颜康。","相对一无言，恋恋若难忘。","那知警觉后，依然在枕床。","起床寻我父，我父寂无睹。","父书陈东壁，父幕空廊庑。","风吹破纸窗，灯灭暗庭柱。","嗟乎父何来，嗟乎父何去。"]},{"t":"居小越旧庐","f":"五言律诗","c":["当门山色秀，犹幸此居贫。","堂构三间旧，箕裘五世亲。","常怀庐墓近，忘与市廛邻。","日暮閒无事，窗前羡钓纶。"]},{"t":"秋怀","f":"七言律诗","c":["天高木落气萧森，极目郊原秋已深。","归雁情添离客梦，闻猿泣下壮年心。","敝裘苏秀无生色，弹铗冯谖孰赏音。","唧唧吟虫听未了，城头又起夜来砧。"]},{"t":"九月二十九日感事","f":"五言古诗","c":["乌鸣天欲霜，东南飞欃枪。","红巾来何处，片帆渡富阳。","杀人铁岭关，流血河水殷。","官弁未接厉，荼毒偏稽山。","我闻太守贤，苕霅靖烽烟。","下车无半月，濠水凿城坚。","米粟非不多，况乃乘天险。","一朝变部兵，粒火腾高焰。","古来名将士，和衷石投水。","李广岂不伟，竟至朔北死。"]},{"t":"观姚江常胜军齐发","f":"五言古诗","c":["昨夜失东隅，所守在桑榆。","况复江海防，往来历通衢。","卓哉谢氏子，曹江咸弃繻。","今日运糇食，明日出车徒。","村近不捉船，含枚疾驰驱。","同是梓里人，甘苦尝饴荼。","昨闻红旗报，奏凯贺鉴湖。","安得常胜去，东浙复须臾。","一郡八县令，东望相招呼。","呼兵寓于农，引领全我躯。"]},{"t":"月夜有怀","f":"七言律诗","c":["银河洗出月华鲜，蟾入冬来依样圆。","不信风云俱改旧，惊看草木忽非前。","霜霏有脚空难觅，虫语无声候已捐。","翘首素娥犹普照，半临兵甲半烽烟。"]},{"t":"十月二十日夜见城南火，翌晨即事","f":"楚辞体","c":["官默默，民忙忙。","南门不守守江塘，黑夜红烧贼入疆。","贼入疆，心仓皇。","山无色，日寒霜。","一步一嗟可奈何，但闻悽悽切切野哭泪汪汪。","是时我心抑郁若王郎，直欲身入九霄问彼苍，彼苍冥冥而茫茫。","又欲手拔腰下三尺之剑断愁肠，彼剑靳靳力抽不可长。","兵不出兮将不生，才薄那此当道之豺狼。","吁嗟乎，穷达固有命，生死系纲常。","庸庸耀爵禄，几辈误君王。","生灵悲涂炭，义士气激昂。","何处乌鸦来，声声向夕阳。","出门将安归，北风萧萧凉。"]},{"t":"冬夜山居","f":"五言律诗","c":["万籁齐归寂，寒灯烬草庐。","冰霜深夜柝，风雨一床书。","事去真无那，人生岂必虚。","漫漫天不晓，空过日之馀。"]},{"t":"除夕大雪步归","f":"五言古诗","c":["今夕是除夕，归家作荐席。","天寒鸟不飞，木落草亭辟。","连夜雪弥漫，千山铺琼液。","出门路茫茫，何处辨郊陌。","津涯一望平，樵径数条窄。","狐兔乍留踪，寻踪步竭蹶。","隐约见吾家，茅屋三间白。","老母已依闾，念儿苦行役。","今夜好归来，羹汤费筹划。","忽忆前年时，高堂满宾客。","兄弟列坐旁，儿童嬉阶石。","父曰尔饮酒，一年今宵易。","团栾竟夕欢，杯盘恕狼藉。","不谓同此辰，人天叹暌隔。","长跪启遗书，屋梁尘灰积。","窗破北风严，户外无行屐。","吾父似见儿，烛泪流盈尺。","谓儿形影单，画像顾恍惚。","欲言不能言，低头思畴昔。","谁家爆竹声，到耳响千百。"]},{"t":"春怀 其一","f":"七言律诗","c":["高楼极目惨烽烟，此日登临气黯然。","战血色斑芳草地，悲歌声缭杏花天。","奇才姑负弓刀利，词客谁销兵甲坚。","隐隐春光依旧到，澄清揽辔问何年。"]},{"t":"春怀 其二","f":"七言律诗","c":["我生漫道不逢辰，有志愿从屈处伸。","半壁山河留义士，十年征战祸庸臣。","烟消村市楼台静，雨霁郊原草木新。","怕听湖边双燕子，呢喃偏向故园亲。"]},{"t":"偶成","f":"五言律诗","c":["自信何为者，乾坤一庶民。","默参閒里味，睡友梦中人。","俯仰难逃俗，文章莫济贫。","桃源津得问，何处不藏身。"]},{"t":"春日送叔兄之上海","f":"古风","c":["小鸟不住鸣，芳草萦青青。","可怜一抹垂杨柳，条条江上送行人。","行人不见奈依依，青眼望断絮分飞。","絮飞渡江逐水去，去水不比来水迟。","我来春暮送行船，飞花飞絮乱云烟。","花不能言絮不语，含情斜绕落君前。","送人不送相思泪，满地干戈非族类。","兄慎车马我归来，无使老母系梦寐。"]},{"t":"题钟馗图","f":"楚辞体","c":["芙蓉缥缈擎天峙，终南山中我故里。","于鬼为伯仙为友，传作人间伏魔使。","天宝遗事说当年，臣志无他魂梦里。","生不及第死不磨，烈士壮心难已已。","我今启图肃威仪，腰间宝剑横秋水。","目光电闪须县戟，虎掌之手编贝齿。","正当五月五日时，仿佛精神烟云起。","阴风飒飒闻鬼语，白日凄凄暮山紫。","驱鬼缚鬼鬼无声，鬼无声兮鬼应死。","是时群鬼惊股栗，烹鬼作食为公祀。","菖蒲叶绿艾叶肥，雄黄醉酒城乡市。","钟进士，钟进士，人生不得衣冠图麟阁，何妨破帽青衫面目本来画尺纸。"]},{"t":"再为田道士作","f":"七言律诗","c":["名著终南进士科，钟馗字已俗传讹。","荒唐事迹谈天宝，奇伟遗容肃鬼魔。","小妹新婚遣嫁去，故山捷径阅人多。","道家一样能驱疫，瞻仰神威日几摩。"]},{"t":"山斋题壁","f":"五言律诗","c":["逃名犹有地，终日住危楼。","惯下无端泪，频来不尽愁。","作诗惟道性，见月祗低头。","漫向行人说，轻云野外浮。"]},{"t":"续梦中语","f":"五言绝句","c":["水浅天亦浅，山深路亦深。","醒来欲续句，梦景渺难寻。"]},{"t":"勇虫叹","f":"五言古诗","c":["豪客车尘走，勇虫断其后。","客岂无慧知，毅然避臂肘。","遇合要有因，刚柔异禀受。","苟不逢其人，蕞尔无何有。","从古多战场，壮往辄自负。","大石厌累卵，鲜不碎八九。","嗟此乡小民，义勇呼徒首。","一夜血江河，哀哀哭父母。"]},{"t":"出门 其一","f":"五言律诗","c":["前日出门去，云树遽杳渺。","何以今日行，依依情难了。","缓语不成声，含泪别兄嫂。","兄言慎车马，嫂言愿归早。"]},{"t":"出门 其二","f":"五言律诗","c":["父在依父身，父没依父坟。","嗟哉失怙人，何为今日行。","瑟瑟西风起，唧唧寒虫鸣。","欲去不能去，秋光亦酸辛。"]},{"t":"出门 其三","f":"五言律诗","c":["侍母登扁舟，无端涕泗流。","孩提忙解意，牵衣愿少留。","患难分骨肉，两地思悠悠。","相忆聚会欢，莫作别离愁。"]},{"t":"出门 其四","f":"五言律诗","c":["半篙急风雨，家乡逐鼙鼓。","回首不能忘，城西一抔土。","寄语同里人，漫道关山阻。","别时未尽言，可待便鸿补。"]},{"t":"七月九日渡澉浦纪事","f":"五言古诗","c":["甬东巢海盗，负固僭名号。","天子莫能诛，有司治不到。","辛壬越二年，粤寇肆悖暴。","同鼓楫浙流，龛赭间攻剽。","我家苦烽烟，澉浦乘孤棹。","何物扎红巾，片帆来海峤。","风急口乾呼，追奔闻轰炮。","两舟一索连，拔刀齐声啸。","但闻勿杀人，玉帛投所好。","伤哉馀手泽，无多存火燎。","兄子结同心，前向哀哀告。","盗酋似识我，破箧倾颠倒。","珠玉碎行行，半赴海若召。","海若渺无情，白浪长风扫。","片羽视吉光，零星拾泥淖。","冀彼所亡书，一一粥乡校。","句馀溪水通，合浦还珠妙。","舟子恸哭声，腥雨鼍龙吊。","暮色望家山，隐隐海神庙。"]},{"t":"晓发澉浦走至角里堰","f":"五言古诗","c":["潮落泥滑澾，赤足步跋蹩。","年少不惯行，疾首齐蹙额。","空囊笑金尽，数家一被褐。","迤逦登彼岸，乍觉虎口脱。","半束残卷书，惟我宝衣钵。","遍地是干戈，畏彼道路夺。","息足村成市，盆鱼环泼泼。","秋阳烈如火，饮水疗焦渴。","流民本无家，撮米炊粗粝。","道旁相问讯，中心为恻怛。","石畔许徘徊，顿觉胸襟阔。","晚宿田夫家，炊烟起一抹。","桑绿处处蝉，养得天机活。"]},{"t":"嘉兴道中","f":"五言律诗","c":["一路烽烟惨，我来秋已初。","田原衰草地，人屋野禽居。","江冷随潮落，桑低认旧锄。","可怜鸣蟋蟀，犹自傍荒墟。"]},{"t":"夜泊洙泾见官兵","f":"五言古诗","c":["秋风晚来急，去国如敝屣。","孤帆数百里，未见人踪至。","忽闻鼓角声，江流齐赤帜。","灯火列万家，月色照车骑。","深夜不闻声，安问谁将帅。","浸晓独眺望，潮落东林寺。"]},{"t":"至沪偶病 其一","f":"七言绝句","c":["未卸征帆病染躯，沉吟旅枕竟模糊。","强将诗意从头觅，诗到申江一句无。"]},{"t":"至沪偶病 其二","f":"七言绝句","c":["可怜老母倍乡愁，日日问儿小愈不。","勉劝儿尝今日药，床头犹有药钱留。"]},{"t":"至沪偶病 其三","f":"七言绝句","c":["传说烽烟近浦东，哀鸿嘹唳梦魂中。","流民贫病无生计，谁仗扁舟万里风。"]},{"t":"八月十日海中沙阻，病中述","f":"楚辞体","c":["夜半舟子呼，海岛惊龙鱼。","风帆利不驰，篙柁尽牵拘。","下临不测渊，蜒户莫敢渔。","沙阻可奈何，环哭对妻孥。","老母怜病儿，骨肉互持扶。","曰儿勿惓卧，馀语听模糊。","明月何皓皓，照我白纱幮。","哀哉生死关，此心未能无。","何处来瓜艇，争渡人尽趋。","一人钱十千，无者空欷歔。","熟闻扬子江，水怪集江猪。","又闻鳖子舋，大石沉沙淤。","岂有他巧妙，瀚涨我其苏。","夜潮来不来，命兮在须臾。"]},{"t":"通州任家港车行 其一","f":"七言绝句","c":["奄奄海上七辰周，病到通州竟卧游。","明日坐车知早起，忠孝已可数更筹。"]},{"t":"通州任家港车行 其二","f":"七言绝句","c":["杨柳扶疏夹道舒，舟人扶我上轻车。","流民入画无长物，一个残人一束书。"]},{"t":"中秋舟泊泰兴怀胡丈","f":"五言律诗","c":["小港绕垂杨，秋风一枕凉。","病魔牢不去，客思渺难忘。","淮水蘋花远，荒城夜杵长。","此翁归去也，明月两相望。"]},{"t":"舟行里下河 其一","f":"五言古诗","c":["未曙梦频醒，村鸡闻断续。","晓风拂帐清，零露霏帆足。","寒不启篷窗，兀坐拥絮褥。","臭声绕脚喧，人稠一灯绿。","朝朝养疴方，波心射红旭。"]},{"t":"舟行里下河 其二","f":"五言律诗","c":["淮南多小菽，味美如香粳。","舟子深知我，瓶瓮炊粥成。","谢食日兼旬，饮此胜瑶琼。","客路无药饵，得此亦怡情。"]},{"t":"舟行里下河 其三","f":"五言律诗","c":["蒹葭飞白鹭，汤汤流淮水。","蓼岸有农家，诛茅成小市。","田车挂帆席，无人自奔驶。","长歌彼乐郊，渔唱晚烟里。"]},{"t":"病抵淮阴 其一","f":"五言律诗","c":["秋老江溜紧，弱纤迟孤艇。","村舍无酒沽，城门暮已迥。","饥寒莫可疗，汲泉煮清茗。","终夜风雨声，凄凄闻梦醒。"]},{"t":"病抵淮阴 其二","f":"五言律诗","c":["鸿鹄已高飞，天空去冥冥。","非不历寥廓，无乃劳影形。","晓起坐船头，犹畏秋露零。","徒倚倦足力，视彼浮藻萍。"]},{"t":"哭胡丈","f":"七言律诗","c":["全家幸得达淮滨，何事天星陨老人。","千里程登违此日，卅年父执痛前尘。","故乡烽火能知我，满地干戈竟失亲。","回首菰城寒夜雨，山河已渺泪沾巾。"]},{"t":"谒高丈伯平","f":"七言律诗","c":["未许孤儿尽冥顽，天留父执启尘寰。","读书岂为饥寒迫，讲学从知岁月閒。","风雨廿年谈太末，烽烟千里怅家山。","追随深愧鲰生晚，才见先生发已斑。"]},{"t":"落发","f":"五言古诗","c":["首为一身尊，精萃尤在发。","少壮所以黟，衰老成鬓雪。","曷为方刚年，不尽种种脱。","客从远方来，赠我长生诀。","岂知多病躯，不得补心血。","养我十年气，精神期蓬勃。","虽落可不落，何庸计毫末。","蔚哉松柏姿，森森励晚节。"]},{"t":"高丈赠砚","f":"楚辞体","c":["东林有孤雏，落日啼清啭。","道旁少行人，归鸟齐飞倦。","我来淮水清，相依灵光殿。","秋露深蒹葭，无以飘零念。","田园辟荒芜，野草愁行蔓。","碧溪疏春流，和风动纨扇。","群卉已歇芳，柚橘实庭院。","老枝非不辉，弱小偏眷恋。","朝朝饫德音，饥渴平生愿。","内直与外方，相持一片砚。","少有金石癖，遗编思网罗。","何期走豺狼，乡里挥兵戈。","父书不能读，相去天一涯。","荡然焚笔砚，岁月其蹉跎。","中流有砥柱，特立何巍峨。","游子爽然归，中夜闻谴呵。","温润光可鉴，坚确志不磨。","砚兮其蕴结，之子待如何。"]},{"t":"重阳","f":"五言律诗","c":["西风吹日暮，天气又重阳。","旅馆心难白，疏篱菊已黄。","病无医俗手，诗可涤愁肠。","欲遍茱萸插，凄然江海长。"]},{"t":"同郭芝韵登三仙楼","f":"七言律诗","c":["城西闻说有仙楼，拾级登来晚景幽。","同志聊为泉石主，明窗不觉水天收。","茶煎老衲香连屋，壁有新诗句琢秋。","仙蝶于今何处去，停云迟月几勾留。"]},{"t":"过漂母祠 其一","f":"七言绝句","c":["多情一饭见途穷，巾帼须眉驾沛公。","多少乞人求不得，不知湮没几英雄。"]},{"t":"过漂母祠 其二","f":"七言绝句","c":["奇士常逢潦倒秋，汤汤淮水溯韩侯。","时当失意受恩易，不必千金亦愿酬。"]},{"t":"寄怀褚子耘子方 其一","f":"五言律诗","c":["风雪漫天地，严寒偪客庐。","怅怀江上水，远寄故人书。","昔日比邻住，深宵吟兴摅。","谁知一岁后，我亦异乡居。"]},{"t":"寄怀褚子耘子方 其二","f":"五言律诗","c":["自从黄浦别，时又越秋冬。","诗笔君应健，閒居我尚佣。","乱离度岁暮，贫病值年凶。","何日重联袂，消寒续旧踪。"]},{"t":"寄伯兄上海","f":"七言律诗","c":["流离骨肉泪难乾，况是他乡度岁残。","淮水曲欣慈母健，春申江忆阿兄寒。","到家有梦神常聚，尺土未抔语不安。","前日一阳虔旅荐，虞西回首路漫漫。"]},{"t":"偕郭芝韵沈铭斋雪中至袁浦","f":"七言律诗","c":["不辞雨雪棹清江，豪气诗情未肯降。","风急船头迟走纤，溜平波面稳流艭。","近堤灯火侵城暗，远寺钟声替我撞。","明日吾侪试白战，伊谁健笔鼎能扛。"]},{"t":"春郊遣兴","f":"七言律诗","c":["两三词客不须邀，徐步郊原入望遥。","一院昼长莺语滑，长堤花暖马蹄骄。","绕城杨柳新霏絮，护水田家未插苗。","何处酒帘悬落日，相期醉后听吹箫。"]},{"t":"登龙光阁在淮城南","f":"七言律诗","c":["龙光高阁峭摩天，日暮登临思渺然。","万树朔风排雁阵，几村夕照返渔船。","城头画角催人急，檐外铃声答语圆。","多少轮蹄盘鸟道，可曾南望息风烟。"]},{"t":"喜闻官军平定浙东","f":"七言律诗","c":["一片红旗下定阳，中丞重见李文襄。","曲江潮汛归沧海，万里春风奏绿章。","谢却西戎閒壁垒，已完东浙旧金汤。","最难两度风烟惨，留得扁舟返故乡。"]},{"t":"由淮之泰州留别诸友 其一","f":"五言古诗","c":["忆昔趋庭日，读书恐或失。","闭门斗室居，岁时步不出。","父念儿业疏，此心求专壹。","勿罔作聪明，免讥学无术。","尤戒好为师，循名先质实。","失怙才踰年，此理何难必。"]},{"t":"由淮之泰州留别诸友 其二","f":"五言古诗","c":["驱人饥渴来，淮阴有钓台。","一母两游子，避兵风雨哀。","兄有家室事，离别亦艰哉。","弟为腼颜请，闻者言笑开。","秋树寒蝉报，海陵乱云堆。","我去学苦浅，我去年尚孩。"]},{"t":"平桥口占","f":"七言绝句","c":["葵花迎后葵花送，两度葵花两度秋。","底是离怀无著处，迎葵不比送葵愁。"]},{"t":"风行高宝湖","f":"五言律诗","c":["白日浑风雨，扁舟发海门。","水流双橹挺，人静一帆喧。","飞鸟舒长翮，炊烟乱远村。","波心惊落影，夜色又黄昏。"]},{"t":"旅窗闻桂","f":"五言绝句","c":["何处木犀植，风吹断续香。","香无今夕异，重桂坐高堂。"]},{"t":"旅窗闻雁","f":"七言律诗","c":["忽闻征雁落江城，孤枕无眠物候惊。","一舍青灯游子读，半窗明月乱蛩鸣。","轧咿未罢邻家织，萧瑟空翻阶叶声。","传语旅人须爱护，阑干莫倚到三更。"]},{"t":"冬夜敬录重桂堂集","f":"七言律诗","c":["一编到手浑如梦，三载伤心谢斩衰。","开卷依然亲阿父，沈吟能勿痛孤儿。","流离应许观摩益，风木空滋魂梦疑。","历劫不磨知有在，残书珍重岁寒时。"]},{"t":"残腊途中冰阻","f":"五言古诗","c":["岁时催游子，风雪滞关河。","舟行五里遥，时经十日多。","焦思莫疗渴，汲泉煮行窝。","百击不开杵，手指僵欲呵。","泾绝采樵迹，渔无蓑笠过。","黄棉出当户，日暴不融和。","纵使开凌阴，江流奈澌何。"]},{"t":"春日书怀寄叔兄徐州 其一","f":"七言律诗","c":["书香旧业慎维持，南北无端借一枝。","偏到扬州三月候，那堪淮水两分时。","雁飞云外常成阵，乌哺林端尚有儿。","料得斋前春草绿，囊中同有感怀诗。"]},{"t":"春日书怀寄叔兄徐州 其二","f":"七言律诗","c":["作客天涯两度春，离怀争比岁华新。","时因啼鸟醒归梦，每对残花忆故人。","千里相思惟觅句，频年心事欲沾巾。","閒亭放鹤知无恙，水远山遥寄此身。"]},{"t":"春郊闻笛","f":"五言律诗","c":["青青杨柳色，渺渺余深怀。","浓淡三春画，凄迷一曲谐。","美人怜短梦，游子怅天涯。","何处青山好，盘桓与我偕。"]},{"t":"童女叹 其一","f":"七言绝句","c":["娉婷小女亦含羞，几度管弦几度讴。","祗为归家笞挞苦，当筵学作贯珠喉。"]},{"t":"童女叹 其二","f":"七言绝句","c":["囊中探得几青钱，太息双鬟坠俗缘。","多少游人忘住足，笙歌一样误青年。"]},{"t":"暮春有感","f":"七言绝句","c":["杨柳依依飞尽絮，黄梅冉冉欲流酸。","堪怜树大春归去，图报春晖果是难。"]},{"t":"忌日","f":"五言律诗","c":["千里有孤子，三年无老亲。","问心时号泣，触目事悲辛。","故国浮抔土，天涯客几人。","记曾前夜梦，犹是过庭身。"]},{"t":"海陵四咏 其一 岳王墩","f":"七言律诗","c":["精忠亘古仰功勋，残垒登临吊夕曛。","半壁已无南宋土，一墩犹说岳家军。","金焦对峙雄天障，江海平分靖寇氛。","回首南都遗恨在，森森古柏鄂王坟。"]},{"t":"海陵四咏 其二 尤氏园","f":"七言律诗","c":["小筑亭台辟草堂，排成十景谱群芳。","秋深菊圃迎人淡，春送梅花透屋香。","何处箫声閒粉黛，有时诗卷话壶觞。","青青植遍当风竹，醉步蹒跚刻数行。"]},{"t":"海陵四咏 其三 古柏林","f":"七言律诗","c":["虎踞龙盘回绝尘，何年古柏接东邻。","寺僧作友枝皆杖，地脉钟灵树亦神。","阅世已多甘老牖，本心未昧独长春。","莫言涧底松常郁，一样洪钧就屈伸。"]},{"t":"海陵四咏 其四 小香岩","f":"七言律诗","c":["盐宗祠石小香岩，迢递朱阑映碧杉。","春去犹开花烂漫，楼深惯听燕呢喃。","曲池傍榭鱼清数，洞石当门柳未芟。","语罢钟声起邻寺，半林落日已西衔。"]},{"t":"喜子方过访同游小有天园在泰城西 其一","f":"五言律诗","c":["孤馆栖游子，佣书夏日长。","故人何郑重，放棹自他乡。","饥渴斯民赖，穷通吾道常。","莫言别离意，南北路难忘。"]},{"t":"喜子方过访同游小有天园在泰城西 其二","f":"五言律诗","c":["偶有花间约，閒从绿荫来。","旅怀无著处，俗吏且低回。","白鹤山林去，红莲水榭开。","明朝骊首唱，折柳漫疑猜。"]},{"t":"得家书将去泰州","f":"五言律诗","c":["偏照扬州月，由来十二圆。","鱼书迟驿使，乌鸟落江天。","明日扁舟客，长淮一路蝉。","忘忧树北堂，也说是归年。"]},{"t":"夜半泊邵伯驿访龚甫","f":"五言律诗","c":["落月天河朗，危樯独夜开。","故人忘寂寞，游子几徘徊。","灯火前堤灭，钟声野寺来。","高楼言不尽，画角漫相催。"]},{"t":"中秋坐月 其一","f":"五言古诗","c":["汤汤淮水长，片片秋云洁。","客来自何方，三度良宵月。","今夜月独明，清光白虚堂。","中庭起徘徊，疏星淡欲灭。","虫语四壁围，人影卧阶石。","何处生清风，飘飘乱我发。","身已到蓬莱，广寒近咫尺。"]},{"t":"中秋坐月 其二","f":"五言古诗","c":["万籁齐寂寞，霏露湿阑干。","当空悬皓魄，俯仰心自宽。","老母怜小儿，为倚门闾看。","相看复相思，天涯游子寒。","前年度江北，长歌行路难。","去年分淮水，来照白头单。","安能离别者，如此月团栾。"]},{"t":"得乐斋补弟子员信诗以复之","f":"七言律诗","c":["差慰书香不断传，归来先咏采芹篇。","狼烟以后千馀里，鸡曙从前二十年。","漫道青衿同拾芥，敢将晚岁废良田。","淹留独笑小痴叔，犹住江南黄叶天。"]},{"t":"人生","f":"七言律诗","c":["满地冰霜斗室居，虽然困顿亦舒徐。","懒思尘世无穷事，补读吾生有用书。","饭罢聊将閒步数，睡馀常觉客心虚。","忘言自得静中趣，过尽门来显者车。"]},{"t":"将之松江藉以南旋","f":"七言律诗","c":["昔日偶然来江北，今朝无计到江南。","渡头开落花千万，海上望归人两三。","怕听画梁新燕语，相期春雨故园谈。","此心已惹乡关梦，贺鉴湖清澄碧岚。"]},{"t":"去淮阴留别诸友 其一","f":"五言律诗","c":["未满相知愿，天涯共客时。","三年非小聚，千里饯新诗。","柳色阳关曲，桃花潭水思。","西湖山色好，相会不须期。"]},{"t":"去淮阴留别诸友 其二","f":"五言律诗","c":["来去清淮水，葭莩接旧欢。","不期因患难，重作旧团栾。","萱草高堂树，车黄行路难。","斯时无限语，尺素道加餐。"]},{"t":"三月四日侍母登舟谢淮阴诸友送至宝应","f":"五言律诗","c":["冠盖动淮阴，河梁携手吟。","此乡多蕴结，永夜慰胸襟。","百里联床梦，扁舟故友心。","相逢终欲别，不尽玉杯斟。"]},{"t":"去淮时有旧婢夜哭岸上，诗以纪之","f":"七言绝句","c":["生成乡里作夫妻，懊恼今朝不我携。","留得十年相忆泪，随波送去自淮西。"]},{"t":"登金山绝顶","f":"五言律诗","c":["长峙大江东，登临感慨中。","塔孤飞鸟疾，潮落夕阳红。","烽火千山垒，回樯万里风。","残碑寻不得，绝顶起烟濛。"]},{"t":"渡扬子江","f":"五言律诗","c":["风送潮头急，扁舟雪浪抛。","两峰巍伏虎，一水气腾蛟。","洞辟渔翁宿，樯高飞鸟巢。","中流诗思阔，无处著推敲。"]},{"t":"进越河口入江南界矣，随书所见 其一","f":"五言古诗","c":["计渡扬子江，哀鸿来满目。","老弱或提携，终朝断复续。","百里无炊烟，残垒争露宿。","滩头罗拜迎，哀向我舟哭。","舟人未成言，风送片帆速。","仰天顿地呼，口乾呼不复。"]},{"t":"进越河口入江南界矣，随书所见 其二","f":"五言古诗","c":["遥指南兰陵，血战降强虏。","生聚悲十年，宫室尽禾黍。","白骨何累累，隐约随篙橹。","当春长荻芦，白日泣风雨。","世无滴血儿，何时安抔土。"]},{"t":"进越河口入江南界矣，随书所见 其三","f":"五言古诗","c":["郊原有人耕，茅屋数椽治。","姑苏城不遥，渐有可人意。","冠盖喧金阊，笙歌集廛肆。","共欣物华鲜，已忘沧桑异。","舟送遗孑归，衢读劝农示。","大吏正招徕，流民何异地。"]},{"t":"丹阳道中","f":"五言律诗","c":["一塔指朝暾，巍然雉堞存。","断碑留胜迹，残垒吊忠魂。","草长凄风帚，桥连旧日村。","伤心遗士卒，犹说向军门。"]},{"t":"暮泊无锡乡间","f":"五言律诗","c":["苍茫增暮色，何处住行踪。","芳草人烟冷，桃花夜雨浓。","结邻双小艇，偶语半吴侬。","赢得终宵梦，时知靖远峰。"]},{"t":"苏城寻伯兄不值","f":"七言律诗","c":["我闻此地好吹埙，把酒船头已待温。","谁道北归鸿有序，偏逢南去雁销魂。","万家烟火重城锁，千里相思雪浪奔。","孤棹不堪连夜雨，更迷云树到阊门。"]},{"t":"泊青浦得伯兄馆奉贤之信","f":"五言律诗","c":["荒城如斗大，兵火话频年。","垂柳萦孤棹，斜阳搁晚烟。","无聊游子意，难得故人贤。","传语平安字，之邦别有缘。"]},{"t":"舟抵云间","f":"七言律诗","c":["青山白水赴茸城，晓岸鸣鸡夹橹迎。","短堞云开孤塔影，一湖风送夜潮声。","浮家到处成新眷，好友逢时證夙盟。","又是昏黄团话旧，洒窗微雨亦关情。"]},{"t":"子方招游上海","f":"七言律诗","c":["约我乘潮买钓舟，分明补作昔年游。","壶觞此夜亲朋酒，粉黛谁家歌舞楼。","日落江边胡马嘶，月明海上锦囊收。","一隅差喜东南守，应许连朝忘客愁。"]},{"t":"伯兄由奉贤来松江连床三日 其一","f":"五言古诗","c":["患难思骨肉，终夜不能忘。","梦去似相见，约略话连床。","嗟哉我兄弟，寥落参与商。","秦晋非谓远，道路阻何长。","昨朝系便鸿，裂帛寄衷肠。","晓闻啼好鸟，何期来远方。"]},{"t":"伯兄由奉贤来松江连床三日 其二","f":"五言古诗","c":["谁不苦离别，反喜新把袂。","入门各自言，悲欢集斯际。","鬓发未全颁，重裘尽凋敝。","沦落本无家，沧桑经此世。","当头风木悲，抔土逾五载。","中庭悬画图，潜然欲流涕。"]},{"t":"伯兄由奉贤来松江连床三日 其三","f":"五言古诗","c":["人生若朝露，溘忽不可留。","矧以弱鲁质，际此多难秋。","客地雅难乐，亲朋结良俦。","移我新浊酿，涤此无尽愁。","酡颜不久热，相对复何求。","富贵岂不愿，何以善贻谋。"]},{"t":"伯兄由奉贤来松江连床三日 其四","f":"楚辞体","c":["偶得箧中书，昔日所雠校。","纸色殊苍黄，字迹忆年少。","物兮且容易，人能不抚吊。","清白永家传，酸辛闻母教。","无乃饥渴驱，来朝催孤棹。","不住夜潮流，东门凝远眺。"]},{"t":"旅居杂兴 其一","f":"七言绝句","c":["垂柳平桥人屋小，碧桃对岸雨时浓。","潮来滚滚潆城水，风度声声近寺钟。"]},{"t":"旅居杂兴 其二","f":"七言绝句","c":["画梁学语初巢燕，少妇缫丝已熟蚕。","一枕病馀临米帖，三竿日暖诵周南。"]},{"t":"旅居杂兴 其三","f":"七言绝句","c":["满院开残红白桃，盈樽人倒浊清醪。","相逢重午还相醉，小会神仙吊楚骚。"]},{"t":"旅居杂兴 其四","f":"七言绝句","c":["漫道关河睽隔苦，犹欣羁旅笑言真。","淮徐风月苏松酒，许与劳人作主人。"]},{"t":"方正学祠","f":"七言绝句","c":["天教正学振遗风，瞻拜荒祠泪我公。","不是昵儿赖魏尉，茸城何处广求忠。"]},{"t":"将去松江用子耘赠行诗韵留别诸友","f":"七言律诗","c":["小住茸城雅意投，行踪聚散等萍浮。","九峰三泖留游迹，浅唱低斟涤客愁。","阅世人多羞看剑，趁潮门近系归舟。","黯然一样清淮别，乱擘蛮笺漫挽留。"]},{"t":"抵家大水","f":"五言古诗","c":["一棹计归程，半月熟梅雨。","河梁碍舟车，羁旅愁閒阻。","家门拓地开，流水浸环堵。","解缆服窗棂，傍阶搁篙橹。","闻说撼海塘，昨决丈尺土。","翻潮入内河，浩瀚不得禦。","朝倾东家墙，夕淹西邻宇。","奥堂鱼鳖乡，城市蛟蜃户。","有客住高楼，招我我心许。","极目慨汪洋，郊原而江渚。","高田无豆麦，遑云插禾黍。","流民才赋归，又嗟空轴杼。","日暮遇相知，蹙頞从头语。","钱塘浪接天，靡烂尤荼苦。","松楸破鲸流，苍黔无鸠聚。","海若知未知，使我痛肺腑。"]},{"t":"催妆曲 其一","f":"七言绝句","c":["诵到周南第一篇，离乱仍得假良缘。","本来牛女是相识，小别人间十二年。"]},{"t":"催妆曲 其二","f":"七言绝句","c":["寻常嫁娶了初衷，地下应知笑语同。","新妇未谙慈母意，姑烧红烛话公公。"]},{"t":"催妆曲 其三","f":"七言绝句","c":["初试烹调入灶厨，荆钗裙布雅相须。","同侪操作同生母，妯娌还将姊妹呼。"]},{"t":"催妆曲 其四","f":"七言绝句","c":["牛衣终夜说王章，佐我机声刻漏长。","惭愧画眉一支笔，寒窗祗合写催妆。"]},{"t":"上元日留赠伯兄 其一","f":"五言律诗","c":["每因省墓殡，买棹至城西。","剩有黄家宇，难忘昔日栖。","里邻悲离散，风雨感凄迷。","赢得元宵饮，相逢醉若泥。"]},{"t":"上元日留赠伯兄 其二","f":"五言律诗","c":["大智从愚起，而今觉太愚。","兄怀诚似拙，弟号合称迂。","对客愁何底，忘情语转无。","莫能筹极计，且自课儿雏。"]},{"t":"上元日留赠伯兄 其三","f":"五言律诗","c":["雁序才连昨，分飞别犹匆。","不图归故里，依旧感飘蓬。","三月烟花艳，长江尺素通。","临岐言约略，不尽寸心中。"]},{"t":"二月二十六日展先大人墓","f":"五言律诗","c":["触景悲风木，茫茫五度春。","伤心一抔土，犹未安先人。","墓草年年绿，堤杨冉冉新。","初成寒食奠，无限泪沾巾。"]},{"t":"同日展长嫂钱孺人墓，见幼妹附殡倾圮，复成一律","f":"五言律诗","c":["爱妹反欺妹，荒凉一破棺。","那堪三岁小，耐受十年寒。","浩劫经时变，崇封愧我难。","尚依阿嫂氏，长夜慰漫漫。"]},{"t":"兵燹后五年不墓祭矣，成一律寄伯兄","f":"五言律诗","c":["祭扫原循故，凄凉奈此情。","纸灰一抔土，烟柳五清明。","宿草留前泪，斜阳趁晚晴。","遥知孤棹客，涕泗倍盈盈。"]},{"t":"吊陈鲁斋兄丈","f":"五言律诗","c":["携杖萝岩下，高风羡岸然。","青蓝联旧契，葭莩托良缘。","孰意今把袂，为时未届年。","大风一曲后，遽尔渺云烟。"]},{"t":"题袁柘林小影用其兄香溪韵","f":"五言律诗","c":["潇洒画中人，风怀回出尘。","山林聊写韵，泉石迭为宾。","廿载光阴迅，三生面目真。","披图一想像，应是卧云身。"]},{"t":"二月八日兄子乐斋之扬 其一","f":"五言律诗","c":["才归沪渎棹，复泛广陵舟。","客地一挥手，青天几处愁。","饥寒身共叹，时业泪交流。","珍重书香旧，秋风再唱酬。"]},{"t":"二月八日兄子乐斋之扬 其二","f":"五言律诗","c":["犹得修定省，灵椿此去安。","频年添发白，千里慰形单。","客惯身忘旅，家贫眷耐寒。","维扬江上见，为我道加餐。"]},{"t":"春日寄伯兄 其一","f":"七言律诗","c":["又是清明杨柳天，旅窗事事感从前。","六桥烟雨春成画，半榻琴书砚作田。","盛世无如才命薄，清贫全赖子孙贤。","閒来屈指韶光数，惭愧周郎经略年。"]},{"t":"春日寄伯兄 其二","f":"七言律诗","c":["烟花自古艳扬州，远道相思思不休。","灯火两三凄客舍，潮头千万涌乡愁。","雄心兀兀金焦峙，壮志茫茫江海流。","惟有一编堪寿世，遥知风雨护扁舟。"]},{"t":"送龚甫之泰州入赘 其一","f":"七言律诗","c":["底是雍雍旭雁鸣，好逑喜听故人赓。","六年风景怀鸳梦，千里烟花达凤城。","麝墨蛮笺诗作饯，莺啼燕语鸟争迎。","来朝车牵间关道，春雨江南最有情。"]},{"t":"送龚甫之泰州入赘 其二","f":"七言律诗","c":["银鞍卸罢凤吹箫，料得帷房桃李夭。","纨扇新裁红袖巧，琼花初上翠鬟娇。","移将西子三分色，煖到玉人廿四桥。","却好嫦娥京兆裔，浅深眉样替郎描。"]},{"t":"四月十五夜述梦","f":"五言古诗","c":["伯兄维扬来，面目生尘土。","陡说父病危，要我省吾父。","情景复疑猜，游移不自主。","俯顾有家人，家人愁万缕。","忽道吾父来，隔窗若有睹。","父来自何方，悲欢欲蹈舞。","壶酒设庭前，举杯话情绪。","同侪五六人，依然亲侍坐。","一酌情畅怡，再酌神吞吐。","三酌环视儿，凄然有所语。","语曰儿善谋，我谋亦安抚。","为看儿曹来，儿曹其善处。","闻之恻然悲，长跪期团聚。","未言鸡唱声，一枕泪如雨。"]},{"t":"馆杭城凤凰山麓，每夜潮声澈耳，因颜曰梦潮","f":"古风","c":["西湖之水清且平，西湖之山瘦且灵。","凤凰山麓背其执，日绕滔滔滚滚之潮声。","潮声起自海门东，龛赭憋亹齐争迎。","龙吟鼍吼势浩荡，铁马强弩气奔腾。","道我江塘筑茅舍，夜夜鸣潮倾耳听。","风声雨声满堂室，鏦鏦铮铮集甲兵。","恍若风樯曲盘快泛宅，不须宫阙楼台住水晶。","又若波流直灌一方枕，不须洗耳傲其清。","天籁自存天地间，呼吸万物走雷霆。","何必筝琶扰俗调，纤细学作秋虫鸣。","嗟哉祖逖闻鸡且起舞，成连到海自移情。","我既不得乘风长破浪，三千里外击鲲鹏。","何能年年悠忽常寂寞，使如深宵寒幄之短檠。","祗恐冥顽时睡足，赖有潮声惊梦醒。","呜呼，赖有潮声惊梦醒。"]},{"t":"夏泛西湖至冷泉亭、飞来峰，暮由孤山步归 其一","f":"五言古诗","c":["旅窗镇日坐，尝若长夏热。","忽闻云林游，使我心夷悦。","晨泛明圣湖，几辈同心结。","湖水镜平揩，湖光烟明灭。","荷芰十里香，鸳鸯时出没。","遥指韬光阿，晓云尽铺白。","随意系渔舟，著我谢公屐。"]},{"t":"夏泛西湖至冷泉亭、飞来峰，暮由孤山步归 其二","f":"楚辞体","c":["塔势忽涌出，迎我我心喜。","绿树翠幄张，清涧双流驶。","涓涓漱玉鸣，飞泉百道起。","庭畔独徘徊，吊古情难已。","忠孝自热肠，韩岳今不死。","水兮抑何冷，虽冷要仅此。","彼哉流俗人，趋炎附势耳。","且不识清浊，遑知冷暖理。"]},{"t":"夏泛西湖至冷泉亭、飞来峰，暮由孤山步归 其三","f":"五言古诗","c":["洞天更奇阔，仙乎飞来峰。","峥磷低打头，崔巍峭摩空。","树荫千障黑，僧咒一灯红。","线天通幻界，玉乳滴玲珑。","非秋垂白露，当暑生凉风。","何必摩崖篆，斑剥蚀苔封。","何必佞释老，镂石害天工。","我游亦飞来，雪泥著爪鸿。","枕石不须归，梦入华虚中。"]},{"t":"夏泛西湖至冷泉亭、飞来峰，暮由孤山步归 其四","f":"五言古诗","c":["陡觉丛岩暗，猿呼山谷应。","山灵不许留，恍惚惊梦醒。","徘徊影零乱，长啸林木震。","入山难出山，迤逦寻仄径。","斜照射西岚，溪流送清听。","袖携鹫岭云，身惹凤林磬。","返棹放鹤亭，晚风吹阵阵。","回顾两高峰，遥锁晚烟暝。"]},{"t":"偕顾篆云晚步江塘观老渔结网","f":"五言古诗","c":["炎夏坐华屋，此身常缚束。","落日眺江塘，同人话心曲。","塘行不数武，几艇江头宿。","中有一渔翁，破网手补独。","小儿沽酒归，炉火炊脱粟。","道是换鱼来，今日青钱足。","明朝还打鱼，网破愁难续。","所以閒暇时，缝纫期敏速。","我闻老渔言，忘言步往复。","越山隔岸青，无心云相逐。"]},{"t":"秋初偕伯兄泛西湖值雨 其一","f":"五言绝句","c":["新秋同雁至，幸得不离群。","湖水清清抱，山南山北云。"]},{"t":"秋初偕伯兄泛西湖值雨 其二","f":"五言绝句","c":["看云四时起，一棹冲波去。","堤柳尽萧萧，蝉声无觅处。"]},{"t":"秋初偕伯兄泛西湖值雨 其三","f":"五言绝句","c":["把酒问轻鸥，游人似旧不。","采菱莫刺手，许我此勾留。"]},{"t":"秋初偕伯兄泛西湖值雨 其四","f":"五言绝句","c":["荷报连番雨，烟濛失尽山。","白衣人几个，呼渡不知还。"]},{"t":"九月偕兄子乐斋之毗陵 其一","f":"七言绝句","c":["不将游处废诗书，一卷商量作客初。","历尽江南黄叶地，推篷胜比晚停车。"]},{"t":"九月偕兄子乐斋之毗陵 其二","f":"七言绝句","c":["萍踪聚散却无凭，阅历深时觉岸登。","旧日南辕今北辙，分明迎送在兰陵。"]},{"t":"登苏城北寺塔","f":"古风","c":["昔年买棹过阊阖，未见苏城先见塔。","今年寄迹北寺旁，日向斯塔对下榻。","偶时塔影卧榻中，掩映斜阳西射红。","旅人梦醒惊窗黑，不道寺塔道长虹。","邻居老僧致前请，邀吾登塔上绝顶。","风云生足乱烟霞，珠玉当檐垂欬謦。","斗大苏城一点烟，却好晚炊欲暮天。","娄江震泽东南指，欲泛太湖思渺然。","许子本非尘俗子，长恨年华逐流水。","何幸胜地结良缘，大千世界日俯视。","日俯视，去迟迟，陋彼眼光如豆时。"]},{"t":"晨起即事 其一","f":"五言古诗","c":["结庐在城中，车马寂喧迎。","旅人独僵卧，寒恋布被轻。","庭前有高树，时来好鸟鸣。","转辗不成寐，顿使归梦惊。","晓起摘名花，袖湿露华清。","徘徊还入室，小窗喜多明。"]},{"t":"晨起即事 其二","f":"五言古诗","c":["有客来故乡，河梁欣携手。","相逢不尽欢，城头沽美酒。","帘影压檐低，糟香透屋厚。","怀袖出家书，殷勤诉前后。","未买故侯瓜，欲种先生柳。","言为我辈陈，尘俗扑百年。"]},{"t":"清明","f":"七言律诗","c":["离离花影压栏干，客里春光愁里看。","燕若知归飞上下，月如无浪到团栾。","关山尺素离人梦，风木纸钱丘墓餐。","明日一鞭循祭扫，可怜红泪又难乾。"]},{"t":"二月奉母居杭即返棹苏州 其一","f":"七言绝句","c":["古杭名胜擅东城，况傍皋园水木清。","记取春晖无限在，莺花三月自关情。"]},{"t":"二月奉母居杭即返棹苏州 其二","f":"七言绝句","c":["时从客地赋归来，此日偏教客地回。","差幸武林山水接，片帆无碍到苏台。"]},{"t":"王兹园丈过访偕登北寺塔旋至元都观 其一","f":"五言古诗","c":["鸟啼客梦醒，侵晨不安席。","手持金错刀，起为瓶花摘。","忽闻乡语声，知有故乡客。","出门获晤言，入室亲颜色。","道自维扬来，阿兄数晨夕。","远归才半涂，同梦嗟永隔。","无计尽君欢，登塔想奇特。","君亦欣然从，惜此足无力。","拾级未及巅，雨云头上黑。"]},{"t":"王兹园丈过访偕登北寺塔旋至元都观 其二","f":"五言古诗","c":["雨霁新草色，对坐兴怡然。","为问元都观，游迹乱云烟。","邀客复心许，齐步夕照天。","平林花枝闹，深院莺语圆。","香车和宝马，相望时流连。","我来傍小阁，煮茗汲清泉。","洗得诗肠净，何愁俗虑牵。","四筵皆颔首，即此妙谛传。"]},{"t":"立夏日偶游狮子林","f":"七言古诗","c":["四月斋前生众绿，旅人寂处步往复。","闻说此地有仙园，五松于今名最熟。","迭相宾主属谁家，城市嚣尘资徵逐。","当门大石卧清池，引入幽胜锦花簇。","始登缭绕之亭台，照眼清华水与木。","崔嵬陡起数石峰，峰峰高插云烟矗。","临流崅荦势欲倾，绕屋峥嵘面惊扑。","欲去复回蓄意奇，似明还暗写情独。","几辈裙屐迷岩行，仿佛蚁穿珠九曲。","任尔良时无意逢，鬓影衣香迎断续。","偶倚水槛品新茶，美味色香齐清卓。","不见当年倪云林，妙手丹青比顾陆。","飘鸾泊凤竞超腾，踞虎盘龙逞屈伏。","不独狮子似狮林，堆作云山在尺幅。"]},{"t":"伯兄自瓜步来苏，连床四日","f":"七言律诗","c":["谁怜征雁怅离群，棹下江南快所云。","难却此时情款款，懒思别后语纷纷。","加餐客地常期健，起我家声祗诵芬。","四夜连床千里梦，相逢底事不欢欣。"]},{"t":"伯兄偕游狮林茗饮终日","f":"五言古诗","c":["坐谈口苦渴，斋居志苦郁。","茗饮五松园，二者思兼括。","园丁结知心，汲泉火烹活。","香浮雪一瓯，畅言促双膝。","即此是家居，襟怀恕坦率。","犹忆前朝游，车马齐稠密。","今日天假缘，座无集宾列。","微雨洒亭台，我情更怡悦。","花鸟见精神，岩岫竞辽阔。","劳劳行役人，园林为蕴结。","壶茗乐团栾，不许说离别。","倪迂画岂迂，解事烟云抹。","相对暮忘归，归途迎素月。"]},{"t":"吴门三劝 其一","f":"七言绝句","c":["可怜襁褓又何如，忍使堂堂路入歧。","同是心肠推幼幼，惟分养马养孩儿。"]},{"t":"吴门三劝 其二","f":"七言绝句","c":["须知可字可终身，大地茫茫孰是亲。","能不使他嗟不淑，恩同父母属冰人。"]},{"t":"吴门三劝 其三","f":"七言绝句","c":["伤心中道失所天，弱息罂罂那得全。","玉碎珠沈能保护，人间从此重姻缘。"]},{"t":"送胡馨甫北上用原韵","f":"七言律诗","c":["关山直北到幽燕，此地挂帆一路秋。","雨露应深天子诏，干戈正值故人求。","雄心千古知君壮，书剑双抛亦我羞。","约计小春归棹日，孤山梅放梦罗浮。"]},{"t":"秋夜偶病","f":"七言律诗","c":["薄病旅窗心事稠，中宵不觉思悠悠。","半床残月催虫语，一枕凉风唤客愁。","望切高堂时入梦，情忘少妇独登楼。","几回移步当门坐，露湿栏干天气秋。"]},{"t":"九月二十五日去苏州","f":"七言律诗","c":["乌篷送我出姑苏，自笑年来性太迂。","世事变迁云意态，客怀突兀路崎岖。","最难著笔狮林画，尚未留题寒碧庐。","为语裙钗须爱护，莫将檀板误当炉。"]},{"t":"重过昆山","f":"七言绝句","c":["曾记当年载酒过，好山迎我似青螺。","今朝未许劳人见，秋雨潇潇听棹歌。"]},{"t":"舟泊黄浦口","f":"七言绝句","c":["几椽茅屋自成村，鸦噪平林带夕曛。","最是寒潮流不尽，声声偏向枕边闻。"]},{"t":"至沪居城南赵氏","f":"七言律诗","c":["未了人间物色因，谪居犹得近芳邻。","石泉冷处交能久，鱼鸟閒时趣自真。","癖不能除挥翰墨，世无可恋走风尘。","雪窗霁后棋枰对，黑白初知亦雅人。"]},{"t":"次韵复陆小敏","f":"五言律诗","c":["风雪催征道，匆匆岁序更。","有怀看宝剑，无语对寒檠。","诗酒骚人事，关河旅客情。","何如三百亩，同作砚田耕。"]},{"t":"同小敏消寒餐花室分得二律 其一 剪烛","f":"五言律诗","c":["绛蜡添莲炬，开来笑语亲。","西窗风雨夕，东壁画图人。","分韵三条尽，修书半榻陈。","夜游还秉烛，烟景召阳春。"]},{"t":"同小敏消寒餐花室分得二律 其二 焦桐","f":"五言律诗","c":["本不耐凡响，甘心爨下过。","何期知己遇，奈此缺残何。","流水犹堪谱，无弦已觉多。","生春弹指下，解阜自能歌。"]},{"t":"将返杭州次小敏赠行诗韵即题其读月楼稿","f":"五言律诗","c":["偶然来海上，相聚话飘蓬。","莫漫愁知己，吾怀陆放翁。","明朝须别去，此际怅离衷。","珍重一诗卷，天寒伴雪风。"]},{"t":"十二月奉母上衢州","f":"五言古诗","c":["海上游子归，江上片帆挂。","此行异寻常，侍母得情话。","骨肉五六人，贫困不知惫。","浙水三折波，溯洄波明快。","风雨万山号，芦荻两岸拜。","舟无离别人，目之皆图画。"]},{"t":"七里泷看云","f":"五言古诗","c":["桐庐江之上，山势诡莫状。","万笏列朝班，千鬟俟远望。","我舟发侵晨，白云压青嶂。","活泼走蛟龙，喷薄助波涨。","想见空洞天，才撤云母帐。","一座玉屏风，历乱总无恙。","绝顶形变更，当头或排宕。","忽忽过山头，前山又相向。","络绎不断云，心神为之王。","衣袖如铁寒，久伫讶健忘。","风劲鸟不鸣，峭壁高无傍。","有此山水奇，看云奇穷相。","深恐入富阳，胜景更莫让。","急为笔诸书，好见云山样。"]},{"t":"过严濑大雪","f":"五言古诗","c":["二十九年前，老母到严濑。","此日重来游，随行皆儿辈。","儿长苕霅间，未审江流派。","自入富春江，风景先睹快。","昨宵息狂飙，吹雪如掌大。","倏忽遍山头，重重压篷背。","上天散飞琼，大河明玉带。","某水某山林，母为道梗概。","一角隐城楼，洼然处险隘。","想见当日情，长与冰霜耐。","欸乃舟橹遥，回首万山内。","惟有南北峰，高插云之外。"]},{"t":"三十自述 其一","f":"七言律诗","c":["重桂堂前桂荫连，孰经趋对溯髫年。","此身赖得之无识，累世犹赢清白传。","讵料箕裘湮手泽，况经乡里扰烽烟。","频年骨肉流离际，怅望家山泪潜然。"]},{"t":"三十自述 其二","f":"七言律诗","c":["庭萱犹喜驻春晖，寸草相思得所依。","惯住湖山聊自适，重游苕霅浑忘机。","家贫常恕旨甘奉，岁晚难堪故旧稀。","凄绝黄泥冈下路，未崇马鬣倍歔欷。"]},{"t":"三十自述 其三","f":"七言律诗","c":["萑苻何物肆蚩尤，兵火馀生浪迹浮。","淮海涛声驱客病，金焦山势压乡愁。","王恭长物空馀簟，庾信悲秋独赋楼。","差幸故园完聚日，龙宫何事阻归舟。"]},{"t":"三十自述 其四","f":"七言律诗","c":["生离死别每神伤，寥落年来不自遑。","未起严敦惭马诫，欲联轼辙怅苏床。","高情无复披求借，破砚长教懔直方。","坐对妻孥空寂寞，复看春草碧池塘。"]},{"t":"三十自述 其五","f":"七言律诗","c":["梅放孤山兴不孤，同人买棹有西湖。","已惭南阁谈经席，莫问高阳旧酒徒。","别有嗜痂挥翰墨，谁能品味到莼鲈。","归来还把图书列，一笑先生合号迂。"]},{"t":"三十自述 其六","f":"七言律诗","c":["立身诚意两操持，甘苦从教心自知。","切磋他山资好友，追随鲁殿得吾师。","半生书剑嗟无用，卅载功名愧已迟。","壮不如人将老大，返躬何以策良时。"]},{"t":"由诸暨至东阳肩舆偶成 其一","f":"七言律诗","c":["为补前游到浙东，春风料峭路匆匆。","暮云百怪空中幻，仄径千重绝处通。","鸟语山原芳草绿，雨馀涧曲杏花红。","苧罗一朵倾城色，尽付苍茫烟雾中。"]},{"t":"由诸暨至东阳肩舆偶成 其二","f":"七言律诗","c":["茅店鸡声侵晓催，林隈历尽到山隈。","岩县飞瀑疑残雪，堤落鸣泉送远雷。","人语家家随耳换，旅怀处处逐心来。","有事白板桥头住，沽酒前村醉一回。"]},{"t":"二月二十八日偕龚梓材邑宰游白云洞在东阳城西十里","f":"七言古诗","c":["平生雅有看山癖，为访名山遍纵迹。","此邦山势倍巍峨，双岘八华翠环积。","甑峰之阴深复深，有洞瓮然云滃白。","我来春雨初霁时，溪水潺潺乱郊陌。","山隈曲径画图开，正奋足力忘休息。","忽惊两岫排碧空，擘破玉龙五千尺。","喷雪霏雾逞奇诡，倒海奔涛自雄特。","白日浑讶风雨来，当头幻作金铁掷。","清盈贮成琼玉盆，玲珑长挂珠玑壁。","观水须穷水之源，彳亍峰峦奋杖策。","绝顶山势复嶙峋，脚底鸣涛走霹雳。","飞瀑竟接石乳泉，一窍晶瑩通地脉。","偶然松火试石铫，虎跑惠泉不能敌。","我闻有宋多隐逸，手把渔竿谢徵辟。","又闻明季张太傅，凿半月池藉游适。","遂初洗得此心清，尚志奚为万乘易。","况是先儒读书处，佳话堪镌一片石。","君子所重去故乡，理学文章炳今昔。","何幸先达竟萃此，景行高山两树得。","客言胜地不虚来，供奉瓣香藉亲炙。","否则雅事续东园，终古名区开讲席。","桃花半坞蒸霞红，松老千株映岚碧。","年年佳气满山林，涵碧翠微见颜色。","我是金华后世人，已惭名氏食旧德。","襆被来此或夙缘，愿诛衡茅处山侧。"]},{"t":"题俞五如有酒学仙图为姚师竹广文作","f":"楚辞体","c":["人生不过数十年，倏忽韶华指一弹。","富贵贫贱于其际，复晞朝露过云烟。","俞子胸中思烂熟，隐居吴兴山水间。","吴兴山水独清远，佐以壶觞尽合欢。","幕庐天地势寥廓，黄垆何妨醉倒眠。","红尘扰扰愁独醒，常恨不封到酒泉。","古来奇士奇面目，靳以形骸许瓦全。","手拄一杖跛一足，图画神仙妙并传。","开元道士李元中，四十年居终南山。","魂返七日失其魄，得饿殍尸附无端。","岂是君身有仙骨，果然谷辟得霞餐。","君谓修真太艰苦，举杯一笑乐陶然。","笑我本来非真相，形随影兮坠区寰。","梦化栩栩来春蝶，壳脱蠕蠕出秋蝉。","推之飞潜与动植，莫非大造理盘旋。","安能长拼此血气，饮酒食肉费万钱。","顿耗精力腐草木，渐使荼毒穿肠肝。","身不我有心有我，何以策乎心所安。","为臣当忠子当孝，人世自具不解缘。","一朝完身归太古，斯情赖有酒杯宽。","壶公岁月壶中久，合与徜徉卅六天。","遥望宫阙森瑶岛，俯瞰世界几大千。","是时群仙皆厕侧，桐君橘叟讷不言。","守此智珠勿复失，便是壶天九转丹。","奚待琐细谈元妙，爱护宝鼎和元田。","我闻此言亦颔首，酌以大斗开欢颜。","有酒学仙无酒佛，此情此理何拘牵。","酩酊终日乐吾乐，固非学佛亦学仙。"]},{"t":"题胡馨甫西泠饯别图","f":"七言古诗","c":["我生壮志常卓荦，不好诣人相徵逐。","读书不拘章句间，策时端望激清浊。","君生亦独有奇气，峥嵘不负此头角。","出山霖雨在山泉，夙昔襟怀思烂熟。","无何烽火起天涯，满地干戈嗟逐鹿。","请缨弱冠推终军，破浪长风快宗悫。","丈夫效命在疆场，烈士许身冒矢簇。","擒贼尤当擒贼王，匹马短褐出帷幄。","鼓不失声血殷轮，伤臂未可伐斤斲。","大吏以此重君才，入告天子授君禄。","归脱征衣二十年，还我书生真面目。","春风渡口浣战袍，秋雨床头鸣剑椟。","四海虽曰歌荡平，雄飞不能效雌伏。","寻诗前度识刘郎，知我今朝有鲍叔。","功名自得绍家声，强仕岂肯甘栈粟。","会当癸酉夏秋交，剑佩琴囊装重束。","故旧无计留远行，饯别西湖话心曲。","飞絮已尽柳浪青，新醅正熟酒杯绿。","喟然谓此非偶然，质之画师图尺幅。","画图难画离别情，黯然魂消不自觉。","是时我独客吴宁，八华双岘看不足。","白云洞口白云深，拟结茅庐鸣鸣瀑。","既为披图题篆额，复缀斯言远道祝。","祝君早日赋归来，异地同心重把握。","还当拓地明圣湖，践约六桥与三竺。"]},{"t":"清明晚眺南郊","f":"七言律诗","c":["犹欣客里驻风光，偶步晴郊引兴长。","为访残碑除薜荔，无多荒冢奠壶觞。","斜阳半塔含山紫，野色千畦送菜黄。","归道杜鹃啼不住，已青春草许祠堂。"]},{"t":"咏程洛翘广文园中白桃花即次同游白云洞诗韵","f":"七言律诗","c":["一枝偏不藉铅华，羞被人呼二月花。","情澹堪邀风外竹，乳香试品雨前茶。","美人有韵含朝露，仙子无言对暮霞。","桃李门墙齐洁白，与同佳兴属君家。"]},{"t":"叠前韵再咏白桃花","f":"七言律诗","c":["谁期悃愊竞无华，属在夭夭灼灼花。","已嫁胭脂归苑杏，全分颜色与山茶。","非关怨恨销残雪，岂为娇羞助落霞。","莫管渔郎问津否，红尘早不到仙家。"]},{"t":"再次俞芝生韵咏白桃花","f":"七言律诗","c":["红尘回首逐纷华，莫把仙姿肉眼加。","一抹纤腰随柳岸，几家清梦锁梨花。","春寒渡口空含雨，诗冷溪头欲浣霞。","却好妆台香色和，敷成半面向人遮。"]},{"t":"初夏南郊晚眺用洛翘韵","f":"七言律诗","c":["读书长昼得馀閒，步出郊原未掩关。","曲涧绿阴人汲水，半林红日鸟还山。","境由心静多成趣，诗为清真未肯删。","茅屋几家欢父老，从知化雨早来颁。"]},{"t":"王鉴叔藏有名纸欲易以诗因次其送春诗韵","f":"七言律诗","c":["浣花笺美锦江西，为换诗章得品题。","已误爱憎招野鹜，更难鼓吹效黄鹂。","洛阳纸贵誇霏雪，题扇桥头快落霓。","聊作鲁公求米帖，鸡林声价漫相提。"]},{"t":"次韵复师竹赠诗","f":"七言律诗","c":["兵火流离不计年，相逢端赖有情天。","消愁满引琼酥酒，话旧还亨石乳泉。","庭长芝兰皆挺秀，门盈桃李倍鲜妍。","偶时登眺来双岘，依样归云断复连。"]},{"t":"叠前韵题竹簃戊辰年师竹所筑","f":"七言律诗","c":["栽竹成簃越五年，寒生中夏雨馀天。","峥嵘头角篱抽笋，虚白心肠石煮泉。","半榻围棋神抖擞，三竿醉酒气清妍。","不如人有如人处，别号与君两字连。"]},{"t":"题师竹游雁宕诗卷即用其宿净名寺诗韵","f":"七言律诗","c":["閒来选胜并探幽，想见诗才造凤楼。","随手一编兵火历，回头十载爪泥留。","鞍归马岭登临慨，岘化龙湫风雨愁。","闻道天台通一路，阮刘何日许重游。"]},{"t":"梓材以下乡诗见示次韵复之 其一","f":"七言律诗","c":["孔迩歌来乐万家，使君风度自清华。","艳称渤海千秋绩，新植河阳满县花。","草野通情劳笠伞，诗篇馀事散云霞。","爱民自得斯民爱，领取风光一串茶。"]},{"t":"梓材以下乡诗见示次韵复之 其二","f":"七言律诗","c":["鸣琴雅抱独宽閒，社稷民人事事关。","教养兼施清界尺，文章致用焕云山。","罪轻法网何妨解，草害良田务尽删。","却好庶黎齐慰日，仁风果得此邦颁。"]},{"t":"登吴宁台柬梓材台在东阳县廨后园","f":"五言古诗","c":["吴宁有高台，台名吴宁建。","南唐迄有明，累朝勤葺缮。","我居台之西，楼阁列灿烂。","倒影入池塘，波平揩匹练。","桃柳数十株，荫密新栽遍。","花落閒扑窗，絮飞徐沾砚。","旅子知昼长，抛卷神初倦。","邀客登斯楼，风光来面面。","层磴架岧峣，危槛复盘旋。","山翠压城高，岭石补云断。","春色明媚时，一时经百变。","田野扇和风，耒耜集芳甸。","遗爱在此间，古今人如见。","况移孝作忠，盛名犹炳焕。","以此教斯民，斯民饥渴愿。","须臾起晚炊，郭外斜阳半。","驱犊归家家，柴门蒸麦饭。","相聚话使君，农欢妇无叹。"]},{"t":"四月九日重游白云洞","f":"五言古诗","c":["南风吹麦秋，许我续前游。","珠溅泉犹滴，雷鸣瀑乍收。","残碑摩字画，奇石拾溪流。","最好新茶煮，炉烟沸一瓯。","未尽登临兴，松冈晚霭笼。","滩头高树绿，人背夕阳红。","花草行囊共，烟霞两袖充。","后来当预约，定不负诗筒。"]},{"t":"咏洛翘园中榴花","f":"七言律诗","c":["白头花已老文君，赖有庭榴照夕曛。","画烛高烧迎绛帐，池波微步妒红裙。","独惺芳草三分色，已隔梨枝一段云。","多子古来推此种，及时灌溉自殷勤。"]},{"t":"白榴花叠鉴叔韵","f":"七言律诗","c":["江南花事记诗章，此地相逢喜欲狂。","香逊梅枝传驿使，清芬桃观续刘郎。","裙拖缟练羞红紫，玉压钗鬟冒雪霜。","待到水晶如实结，风光犹未老萧娘。"]},{"t":"月蚀复洛翘","f":"七言古诗","c":["四月甲子岁癸酉，月有食之既八九。","乐官奏鼓啬夫驰，村妇揳搔庶人走。","角尾互交失常经，星辰错落灭牛斗。","浮云掩蔽经须臾，玉盘捧出候长久。","有客为我说象纬，日月之蚀在某某。","当年故事寻羲和，此日天心无休咎。","又谓日食阴掩阳，伐鼓公朝集矇瞍。","扶阳抑阴理宜然，扶阴抑阳莫擘剖。","精理灏气贯古今，斯人斯言难翕受。","粤自二曜启鸿濛，两仪本不分先后。","赤黑之气侵于房，在上临下良非偶。","天子临殿变食居，诏使宗伯下朝右。","焚香诞告观象台，御史大夫齐稽首。","扶阴即是扶阳心，日月璧合黄人守。","若以祲灾为寻常，天变不畏复何有。","程老谈天何醇醇，长篇发自悬河口。","子午两位决去从，赤黄异道明可不。","愿布此情海内人，终身戴天识高厚。","安得儒臣万言书，朝端又见黄岩叟。"]},{"t":"月夜登吴宁台赏白荷","f":"五言古诗","c":["白桃复白榴，咏花花事了。","长夏独斋居，深惜名花少。","方塘半亩馀，风光犹不老。","新茁白荷花，丰姿常修好。","露珠颗颗圆，翠盖田田小。","风定香暗来，堤桥相迤绕。","主人雅好客，铺席临池沼。","瓜果杂筵陈，烟景资探讨。","瞥见明月明，捧出玉盘早。","团栾满一轮，当头愈皓皓。","劝酒有吴刚，洗盏乐醉倒。","近水快楼台，天机活鱼鸟。","宿鸟惊树林，游鱼刺蘋藻。","名花千朵明，掩映光微渺。","恍若下嫦娥，婵娟斗奇巧。","抑若洛女神，出没曳裙缟。","徘徊冰鉴亭，此身清濯澡。","花影浸衣裳，呼童浑不埽。","莫辨襟上痕，乡心忽如捣。","何处横笛音，数声起缭绕。"]},{"t":"送芝生归山阴","f":"五言古诗","c":["聚散会有时，离合本难必。","所苦送行人，才逢又惜别。","我与俞子交，交新不数月。","作诗道性真，对酒乐坦率。","金华富山林，合住神仙窟。","豪兴遏青云，高谈霏玉屑。","君本慧业人，浮华已屏绝。","痛痒重民生，读书兼读律。","霖雨出世心，舟楫致君术。","兀坐风月宵，此念时蕴结。","同有倚闾亲，白云怅辽阔。","萱草树忘忧，难得是爱日。","有鹿鸣高秋，烈士志未灭。","十年书剑成，誓不甘蠖屈。","荷塘系归帆，山径驰车辖。","祖饯起骊歌，声情俱寥豁。","君爱我最深，临岐语不出。","大地隔形骸，天机连活泼。","行我心所安，春华期秋实。","浩哉至理言，小儒闻咋舌。","把晤明圣湖，酒熟莼羹滑。","后日慰相思，此愿如饥渴。"]},{"t":"寿龚甫三十","f":"七言律诗","c":["髫龄回首雁行连，已度星霜三十年。","爱日高堂随杖履，閒愁时事过云烟。","仁山智水心同乐，秋实春华笔妙传。","愧我荒居无可献，白云欲赠思悠然。"]},{"t":"偕梓材、洛翘、师竹、芝生作消暑集，尝白莲花瓣，分得渔字","f":"五言古诗","c":["采采白莲花，池塘半亩馀。","明霞落波晚，红日照林初。","嘉宾常欢聚，消暑足清娱。","鸡豚苦下箸，瓜果足园蔬。","主人出新意，折花充庖厨。","我曾餐兰菊，秀色并可茹。","天地为炉炭，山水得膏腴。","况此白菡萏，清不染泥淤。","烹调妙燔炙，瓣瓣落瑶琚。","奉出白玉盘，香味与之俱。","清气沦骨髓，芳泽润肌肤。","催诗分雪藕，酌酒和琼酥。","充我冰洁肠，烦热快涤除。","彼哉尘俗子，未许为酒徒。","膏粱涂痴腹，粗粝饱腐儒。","爱花花愈憎，臭味自然殊。","若使餐此莲，出污而入污。","安得素心侣，英华共含咀。","邀花入肺腑，谅勿蒙其辜。","座客发狂笑，语奇天下无。","花不用钱买，酒岂为我沽。","今夕尽足乐，心事梦樵渔。"]},{"t":"消暑集梓材处分得到字兼次洛翘西郊送春诗韵","f":"楚辞体","c":["长夏官衙如水清，鼠雀牙角息纷闹。","明镜高悬曰敏公，疑罪轻刑在耄悼。","偶时局促陋辕驹，拾级高楼齐登眺。","笔走龙蛇赵吴兴，卷抹丹青文待诏。","此眼青白本无常，四面青山为倾倒。","秋到池莲开益多，朵朵争似何郎皃。","作为歌章写素怀，微细含毫妙惟肖。","何处古寺晚打钟，池上风翻隐约报。","报道座客不须邀，宾皆主兮庐自造。","消暑却能消我忧，甘澍叠沛新感召。","祷雨喜雨歌莫停，黄绢幼妇词绝妙。","赏雨茅屋在此间，雨后微风趁夕照。","狼藉杯盘浑不知，恍若南阳快坐啸。","炙莲为馔岂在多，雪藕为丝许胜少。","乐此佳肴许久长，兰臭连番画缭绕。","惯闻健足策杖游，雁宕天台先引导。","他年游屐假谢公，一洗俗尘涤浮躁。","安能抑郁长居此，笺注鱼虫锱铢较。","摘名山句充锦囊，汲越溪水煎茶灶。","广寒宫阙自清凉，手拈奇花口微笑。","不然蹇驴深林深，短檐不碍方山帽。","耕夫织妇清率真，灾祲无待民控告。","仙境尘寰两不殊，今夜梦魂应飞到。","父母斯民何为哉，箫鼓来朝赛社庙。"]},{"t":"消暑集分得中字效柏梁体","f":"七言古诗","c":["高歌对酒感慨中，何来铁汉唱江东。","臭味多同兴正浓，酒令俨如军令逢。","欢然座上有车公，催人懊恼有西风。","欲以酒兵挫其锋，我马既同车既攻。","登坛大将策奇功，借箸为筹我适从。","俎豆坛坫快折冲，侍儿环绕肃军容。","奔足长阪怒花骢，爪肆拇战疾游龙。","左右猿臂挽强弓，中流砥柱特磨铜。","欲还世界气和融，书勋妙笔补天工。","座旁有客笑接踪，谓君所见何庸庸。","古来否泰与塞通，来往循环运不穷。","炎威太过势蒙茸，清凉一味椒空濛。","暑气亏时寒气充，无非造化之陶镕。","岂若趋炎热心胸，翻云覆雨角雌雄。","善哉斯言得折衷，恍闻暮鼓与晨钟。","消暑会亦有始终，阶下秋叶坠疏桐。","一堂高会剪烛红，相与欢进酒满钟。"]},{"t":"洛翘见示祷雨歌即日大雨用均志喜","f":"楚辞体","c":["天子赤子关怀抱，旱魃偶然当其道。","君作歌章情吁天，天心那得不诞保。","忽于同日同候时，黑云翻墨出林表。","狂飙四起吹满楼，对面层峦封被早。","奔雷掣电杂两间，金铁鏦铮鸣多少。","直泻洪涛势倾盆，珠玑齐跳入池沼。","闻说西天法雨来，碧海银河讶倾倒。","骑神龙兮神哉身，隐约云雾露鳞爪。","稻田千亩兴勃然，大气盘空何夭矫。","此时兀坐有真吾，壁破水浸已环绕。","湿尽床灶不足忧，喜与斯民共温饱。","穷巷藉得免追呼，茅檐或能欢父老。","祷雨歌后喜雨歌，从此十雨五风便是宝。"]},{"t":"咏洛翘庭中紫薇花用前榴花诗均","f":"七言律诗","c":["玉堂声价上青云，何幸清斋话夕曛。","霞粲深红连绛幄，烟笼浅碧衬罗裙。","凉归高树留题健，坐对黄昏结屋勤。","漫道元微之不作，惜花今日又逢君。"]},{"t":"回杭秋试洛翘以诗送行组织近事用韵效之","f":"七言古诗","c":["半载追随讲学堂，丰裁群仰鲁灵光。","书成半部堪治世，月见前身快举觞。","立雪程门传道派，归云仙洞怅家乡。","名推山谷诗称祖，徒许高阳酒作狂。","骊得智珠惊藻饰，鳄驱沧海蔚文章。","画兰成社閒消暑，傍竹题箊早纳凉。","鱼牍移诗忙走笔，狸奴接客卧斜阳。","壶斟庭桂泡佳酿，盘摘园蔬得饱尝。","满壁新词探宿海，半潭秋水澄星潢。","紫薇轩对筵开妙，红蓼阶翻句亦香。","河洗甲兵驰露布，词成锦绣织霓裳。","邯郸学步聊如是，敢与先生旗鼓当。"]},{"t":"七夕由东阳至诸暨肩舆杂成倚前韵","f":"七言古诗","c":["驾起肩舆路正长，人情风土费评量。","烟炊晓岫松笼翠，露被前宵枫渐黄。","榴实道旁殊苦李，槐阴渡口即甘棠。","村翁閒话壶觞适，浣女传喧荷芰香。","绿树蝉声迎旭日，青林鸦背落斜阳。","代茶解渴梨千颗，徒步寻舟水一方。","查果流红村作市，棉田霏白妇提筐。","影来雉堞招遥塔，歌起渔船出野塘。","农踏桔槔新值雨，樵冲岩穴独乘凉。","秋风吹叶看明月，人迹浮桥忆早霜。","茅舍老牛勤舐犊，草堤童子笑亡羊。","回头别有难忘处，洞口归云护草堂。"]},{"t":"题贾小谷独立图","f":"五言古诗","c":["瞻彼华顶石，巍巍高无极。","抚此涧底松，郁郁挺千尺。","卓哉贾氏子，胸次常超特。","不辞近市居，清浊齐荡涤。","人为此身病，身病良足惜。","不知有此心，心心印无迹。","绘成独立图，古道见颜色。","天地情所钟，万物尽充积。","辣手许转环，砥足柱家国。","登高快一呼，众响闻历历。","漫道群居卑，独乃群之的。","悬高隐市朝，道大无反侧。","长坂思骏蹄，云路奋健翮。","君子识其真，无入不自得。","盍观南山竹，不揉自能直。"]},{"t":"先大人崇祀湖府名宦八月十七日堂祭杭城","f":"七言律诗","c":["试罢秋闱兴未阑，肃将祀事快团栾。","西泠菱芡登筵洁，东浙云山隔岸宽。","敢告千秋绵俎豆，差欣五郡集衣冠。","来朝苕霅溪头路，知有扶筇父老欢。"]},{"t":"九月四日重至东阳寄杭诸友 其一","f":"五言古诗","c":["握手行江曲，寂寞破清谈。","离愁浩无际，烟波逐征帆。","白蘋飘秋渚，青松依石岩。","欸乃一声去，江流暮色涵。","回首系篷处，灯火落两三。"]},{"t":"九月四日重至东阳寄杭诸友 其二","f":"五言古诗","c":["泊舟高城下，乘舆当安步。","半载重行行，秋来异春去。","春山桃柳芳，秋岸荻花暮。","停车看不足，霜叶遍红树。","斜阳照人家，今宵道且住。"]},{"t":"重九夜饮梓材处用洛翘韵","f":"七言古诗","c":["当秋作客独劳劳，山川靳不乐我曹。","壮观八月十八潮，曲江涉足欺狂飙。","九月九日约登高，山城又值雨潇潇。","兀坐斋前空寂寥，小窗容膝安书巢。","人烟缭绕起衡茅，白云相接远山腰。","主人为我集宾僚，晚菘早韭充厨庖。","清酒百壶倒醇醪，重来吴宁兴更豪。","插菊采萸快此朝，老少颁白并垂髫。","况复高会尽良宵，笙箫夜半薄云霄。","鼓吹酒肠斗石浇，不须两廊椽烛烧。","灯明一点焚兰膏，醉后欣然口成谣。","不假锤炼与推敲，笑彼刘郎不题糕。","拘牵字句徒纷淆，程老词源何滔滔。","先成珠玉惊挥毫，佐者健将姓属姚。","独整旗鼓酣曲糟，右手持杯左持螯，拇战千百不曲挠。","我不如人不复聊，愧如燕石溷琼瑶。","愿收诗筒和酒瓢，相从三笠与六桥。","吟就此篇解客嘲，不殊芥舟覆堂坳。"]},{"t":"秋闱填榜日饮洛翘处","f":"五言律诗","c":["先生真解事，此日集壶觞。","变化鱼龙地，盘桓翰墨场。","一庭秋菊色，满座宝炉香。","倚槛忘归去，南山对晚妆。"]},{"t":"得秋闱下第之信倚前均寄洛翘","f":"五言律诗","c":["三年仍不第，傀儡笑登场。","愧我无真学，多君有热肠。","奇文占吉兆，佳句挹浓香。","无计为酬应，时来就菊觞。"]},{"t":"同日师竹携酒肴来谭","f":"五言律诗","c":["此心何郑重，携酒与肴来。","解语花随菊，忘情客举杯。","涤肠销傀儡，侧耳费疑猜。","醉后新诗就，高歌答水隈。"]},{"t":"初冬途遇高香亭二尹招饮师竹处转至王宅","f":"五言古诗","c":["新月迎人面，其光皎且纤。","道遇高达夫，气宇雅不凡。","访碑来古寺，煮茗供清谭。","庖人具鸡黍，藉欲客留淹。","有客期不至，移樽提筐篮。","不愁西风急，昏暮叩绛幨。","绛幨何清寂，主人作仆兼。","载酒西园醉，壶觞不停斟。","书声隔窗牖，拇战声相参。","东邻新娶妇，红烛照画帘。","裙钗罗筵席，羯鼓已挝三。","洗盏更绣阁，要客不辞馋。","我本逢萍水，此邦好事添。","同行有二老，酡颜掀髭髯。","一笑持樽酒，殊有元妙含。","万事是偶然，今夕何乐耽。"]},{"t":"香亭招饮竹屋在法界寺用关王二君题寺图诗均 其一","f":"五言律诗","c":["钟报城西寺，时来一叩门。","竹疏云压屋，花少菜锄园。","饶有林泉趣，仍无车马喧。","画图今不见，题句溯词源。"]},{"t":"香亭招饮竹屋在法界寺用关王二君题寺图诗均 其二","f":"五言律诗","c":["主人真不俗，当户小筵开。","樽满斟新酿，阶平埽旧苔。","诗僧留古塔，循吏望高台。","雅集无今古，伊谁济世才。"]},{"t":"洛翘以致祭白云祠诗见示用均复之","f":"五言律诗","c":["景行堂前坐，从知别有天。","水流红叶外，山搁白云巅。","旧迹留桑梓，良时荐豆笾。","使君传教化，珍重有诗篇。"]},{"t":"寿师竹五十有三","f":"古风","c":["一日之七岁庚午，大秩筵开数计五。","越今年华辛壬癸，我来旧雨得重聚。","昨回一阳百福生，集启消寒继消暑。","入门何须问宾主，浮以大白斟以醑。","酒酣始知诞降辰，兕觥酌彼鹤筹数。","君独前席致我词，献寿投桃皆无取。","新诗换得樽浊醪，胜比金钱值刻楮。","我闻昌黎进表章，谏迎佛骨浩气吐。","春秋刚逢五十七，力挽衰风擎天柱。","又闻知遇陆宣公，二十二人榜龙虎。","陆之生日是明天，沆瀣师生直接武。","二公今已升庙廷，笾豆馨香列樽俎。","黉宫香火本非僧，礼乐肃修合柷敔。","君秉铎教历有年，大训赤刀重西序。","古来金石寿诗书，振起斯文乐蹈舞。","况是东阳好山林，洞天久许天伦叙。","閒筑竹簃布酒棋，时摘肴蔬开园圃。","迟我数年莫厥居，云洞茅檐不待补。","相与徜徉耄老天，此酒此诗證出处。","君不见周子定居庐阜时，濂溪风月年年今不古。"]},{"t":"踏雪至城南归饮师竹处为消寒初集","f":"五言古诗","c":["严寒生虚空，孤坐苦清绝。","良朋踏雪来，邀看南山雪。","城南山势高，排空拄千笏。","峰峰削玉成，此际峻且洁。","遥塔萎其下，尘埃齐超拔。","地宽眼倍明，云冻天犹阔。","朗朗不辞行，风微吹觱栗。","欲汲雪一瓯，烹茶疗枯渴。","茅舍有人家，叩扉呼不出。","有客沽旧醅，今夕乐举杯。","高轩面园圃，菜绿分叶肥。","汲汤佐新笋，釜沸响轻雷。","瓶笙清如洗，炉小火初围。","美人来席前，数点报红梅。","酒肠欣得煖，仙骨翩不归。","何以酬妙景，门外雪又飞。"]},{"t":"雪后偕芝生登吴宁台探梅 其一","f":"五言古诗","c":["布被冷彻骨，寒威入窗隙。","晓起推纸窗，积雪当檐额。","望远登高台，朔风人面刺。","台高雪亦高，携屐破琼璧。","画图粉本宽，荒城玉带窄。","西南逼诸峰，峰峰立奇特。","天半铺冻云，云雪共颜色。","想见飞瀑泉，洞口寒不掷。"]},{"t":"雪后偕芝生登吴宁台探梅 其二","f":"五言古诗","c":["有梅植台北，临风发微香。","寻芳迷仄径，踯躅傍池塘。","池小凝薄冰，玲珑水一方。","一拳起白鹭，惊散双鸳鸯。","同侪畏清冷，入室薄衣裳。","几砚炙犹冻，盆梅疏欲僵。","终日苦袖手，远道思不忘。","相持一樽酒，与对明月床。"]},{"t":"消寒二集用洛翘师竹均 其一","f":"五言律诗","c":["短檐消残雪，冰柱几许长。","炙砚苦觅句，十指寒欲僵。","朋来促膝话，泉烹新笋香。","夜寒愁壶冻，行酒屡停觞。"]},{"t":"消寒二集用洛翘师竹均 其二","f":"五言律诗","c":["喜晴快雪天，翰墨證夙缘。","酒气达指甲，山影罗几筵。","片片落诗卷，清出笔豪巅。","愿为生花管，春风生眼前。"]},{"t":"消寒三集饮香亭处分得欲字","f":"五言古诗","c":["消寒集第三，重来聚竹屋。","屋小炉火红，竹疏窗纱绿。","我到独濡迟，走仆连番速。","细雨洒前宵，步行石崅荦。","当门石尤奇，迎我如立鹄。","盘飧已罗陈，野味胜鱼肉。","主客一笑言，今夕安且燠。","吾生不善饮，而喜对糟麴。","三爵已酡颜，醉倒不自觉。","客持右军书，琳琅重满幅。","惜余已矇眬，家鸡浑野鹜。","把烛跋其尾，濡墨沾毫秃。","催诗寺钟声，声声印心曲。","诗新句早成，此际淡无欲。"]},{"t":"消寒四集饮洛翘处分得一字","f":"五言古诗","c":["高山多积雪，登高望奇特。","正欲结伴游，先作消寒集。","寒消第四筵，竞入芝兰室。","炉爇柏叶香，扑鼻酒香挹。","豪客置席间，奇语出奇笔。","笔落乱云烟，语射中虮虱。","时阑兴未阑，青钱选一一。","主人策酒兵，恍如铜柱立。","抑如沽春酿，杖头先生得。","东家拓菜园，菜叶尽肥茁。","醉后踏寒畦，蓠外人如鲫。","共得咬菜根，无使有此色。"]},{"t":"消寒五集复饮师竹处分得酒字","f":"五言古诗","c":["前日宴高台，朔风寒入口。","昨朝游洞天，雪花大如手。","雪消风未消，今夕会良友。","泥融溅街衢，折柬快出走。","主人步失足，兴浓忘掣肘。","陟山艰杖藜，铺席能对酒。","酒酣令愈奇，筹竹献左右。","西子纱浣妍，东施颦效丑。","伟哉范少伯，沼吴功不负。","泛湖亦浇愁，觞政妙无有。","我是于越人，愿从大夫后。","网设不罹鸿，兔尽走烹狗。","消寒仅旬月，美酒费百斗。","一饮一集成，待到春九九。"]},{"t":"消寒六集复饮洛翘处分得爱字","f":"五言古诗","c":["山城多鸣鸟，有鸟集豕背。","豕走鸟不飞，閒自啄其喙。","禽兽有蠢灵，所见非所在。","偶集我眼中，怪事书所未。","诗酒会消寒，阅微启精邃。","肴馔列羽虫，雉鸽推群类。","野鹜落凫飞，天鹅寂雁唳。","羽翼竞丰盈，鸡鸭薄滋味。","嗟此握爪拳，何甘投鼎鼐。","失足由网罗，大半为食饵。","吾观高冈凤，一举烟云翅。","又观空山鹤，长鸣风雨晦。","岂不值饥渴，饮啄得素志。","誓不争食栖，适性行无碍。","同席解鸟语，雅人必深致。","莺鸣求友声，非欲弄清脆。","鹦鹉学人言，从俗求妩媚。","声同应实殊，浮沈在聋愦。","苟无真知音，鲜勿割所爱。","不见桀之犬，可向陶尧吠。"]},{"t":"消寒七集饮竹屋分得帘字时从西郊步归","f":"五言古诗","c":["偶忆送春游，计月才届三。","今朝重携手，河梁朔风严。","岁月倏忽易，流水听瀸瀸。","飞虹卧雪中，斜日落层岚。","人影侵在地，历乱舞松杉。","何来不速客，一一集禅庵。","修竹如相识，万个字空嵌。","折节呼士前，俗驾皆扫芟。","主人藏斗酒，厚味咀醰醰。","卜夜添炉火，分题褪鼻尖。","七人逢七集，寒暑理相参。","优游乐卒岁，世味外酸咸。","窗纸忽然白，新月朗磨镰。","归来数梅朵，对影碧筠帘。","花香与酒香，齐梦到黑甜。"]},{"t":"由白云洞值大雪次韵复杨桂峰","f":"七言律诗","c":["四壁青青沈石苔，一番吊古一登台。","最难风雨怀人至，况是山林踏雪来。","飞瀑潺潺疑玉响，危崖树树讶花开。","把樽几度临窗饮，此地围炉未忍回。"]},{"t":"次韵酬王鉴叔","f":"七言律诗","c":["劳劳车马逐鞭丝，心事纷如岁月驰。","才客即思归去日，未回已计别离时。","无多骨肉萦亲梦，有限韶华减客姿。","求富食贫常尔尔，独惭闻道已嫌迟。"]},{"t":"腊月回杭州次龚孝廉送梓材诗韵留别东阳诸君 其一","f":"五言律诗","c":["惯作风尘客，舟车往复回。","时惭驽下驾，未获骥呈材。","酒作驱愁帚，诗无辟债台。","消寒成一集，笑语许追陪。"]},{"t":"腊月回杭州次龚孝廉送梓材诗韵留别东阳诸君 其二","f":"五言律诗","c":["人誇小邹鲁，此地快遨游。","家国承遗泽，馨香报晚秋。","洞花春雨足，山树白云留。","袖得新图卷，吾怀往事悠。"]},{"t":"腊月回杭州次龚孝廉送梓材诗韵留别东阳诸君 其三","f":"五言律诗","c":["春秋佳日里，待我有情天。","桃柳楼台闹，芙蕖雨露圆。","教人传木铎，策我藉蒲鞭。","如是芳邻结，何须买万钱。"]},{"t":"腊月回杭州次龚孝廉送梓材诗韵留别东阳诸君 其四","f":"五言律诗","c":["道不分南北，崎岖有大隗。","旅情寒鸟唤，诗意冻云催。","双岘留题去，西湖返棹来。","临岐还痛饮，可耻罄瓶罍。"]},{"t":"途中偶成用前韵 其一","f":"七言律诗","c":["残冬又得买舟回，晓驾肩舆拨雾开。","山背雪馀犹我送，林端云起望人来。","寒鸡三唱清茅屋，春水微生响曲隈。","赢得征途无限趣，一壶新酿一盆梅。"]},{"t":"途中偶成用前韵 其二","f":"七言律诗","c":["不道新春同我回，千门爆竹听如雷。","摇摇旅思眠难稳，隐隐城头钥未开。","月落半江帆影澹，潮平五夜角声催。","推窗迟见东方白，安得戈挥海日来。"]},{"t":"春雹折盆梅感赋","f":"七言律诗","c":["同经霜雪耐时艰，历尽崎岖东浙山。","岂料冰珠翻碧海，顿教仙骨老朱颜。","香魂未断应来复，云洞留缘空自还。","毕竟天工神守护，不令凡艳落人间。"]},{"t":"孟春共甫之吴叔寅北上伯约之甬予将之东阳赋此志别","f":"五言古诗","c":["合冰当南风，春日解河浒。","相生实相融，离合谊有取。","我归明圣湖，残雪趋腊鼓。","短晷忽西驰，花气郁蓬户。","梅芳玉照堂，天香竞吞吐。","放眼云居峰，怒潮奔貔虎。","良会有穷期，挂席分南浦。","江汉隔形骸，契作金兰谱。","客自金华来，邀我适乐土。","石洞云片飞，幽岩泉滴乳。","宋元接源流，何王与金许。","尚友有古人，事贤得所主。","况历名胜区，燕洛人才聚。","浩乎乘桴游，沧海碧眉宇。","明珠发奇光，黄鹄期高举。","能浚此性灵，旧雨复新雨。","高堂白发生，踯躅意良苦。","吾辈皆游子，亲年向谁数。","衣冠拜别时，山川忘艰阻。","所持爱日心，萱草北堂树。","天涯多廓寥，防意破强虏。","声色甘如饴，不啻伐性斧。","他日同赋归，文字饮樽醑。"]},{"t":"暮宿诸暨牌头，题壁用鉴叔诗韵","f":"七言律诗","c":["忽惊怪石压山头，独立苍茫不计秋。","突兀旅怀浑作对，崎岖客路惯忘愁。","投鞭此地閒迎送，续句前游听去留。","俯视纷纭车马者，不殊尘世一蜉蝣。"]},{"t":"过宣何岭","f":"七言律诗","c":["已入山林深复深，忽逢峻岭策千寻。","探梅添得诗人料，履险犹馀游子心。","老树摩空云滴翠，黄花缀壁石镕金。","青春此去东阳近，一路清溪有好音。"]},{"t":"雨抵东城","f":"七言律诗","c":["茅檐深处宿征车，侵晓催行画不如。","云气才封三里郭，雨丝已湿半肩书。","花飞野寺沟流出，舟坐春江天上居。","多少旅人来唤渡，年年作客敢愁予。"]},{"t":"花朝饮师竹处","f":"五言古诗","c":["春雨困连朝，此心独惆怅。","红霏隔院花，蘋泛圆池涨。","嘤嘤好鸟声，晓窗闻纸帐。","晴旭忽照檐，浓黛抹千嶂。","雅怀启雅人，折柬饮春酿。","春酿何醲郁，越醪浑不让。","杯盏罗新奇，酌酒在无量。","座开碧桃花，含羞笑相向。","笑我醉不知，误挫酒国将。","桃李芳恒蹊，春风坐和畅。","况是花朝朝，花花竞相放。","何待羯鼓催，诗催两无妨。","东斋有琼枝，春来花无恙。","君子结素心，涉趣左右望。"]},{"t":"读三鱼堂文集","f":"五言古诗","c":["孔门道不二，传道有程朱。","程朱别其派，门户遂分殊。","从者病拘滞，攻者空诋诬。","授受各有本，渊源莫可俱。","有明尚虚寂，阴释而阳儒。","大道不遽投，讲堂启三鱼。","传经崇正学，吏治出诗书。","孰谓心即理，善恶入迷途。","孰谓静不动，渣滓玷太虚。","主敬与穷理，不可离须臾。","松阳留讲义，微言得持扶。","洋洋象山语，非不味道腴。","姚江及白沙，良知举一隅。","无如浅浮子，泛滥失所居。","辟之不遗力，后学赖步趋。","博文约以礼，体认越粗疏。","我读学术篇，此情列粲如。","师承今未远，翘首望当湖。"]},{"t":"四游白云洞次前明张忠敏重游白云洞韵","f":"七言律诗","c":["春游结伴计经年，探胜寻幽思渺然。","酒味不嫌茶味澹，道心争似石心坚。","一堂风雨泉声护，万古台池花气妍。","自愧数来无可献，白云袖得有前缘。"]},{"t":"是日适逢寒日归途有作次方干寒食过东阳韵 其一","f":"七言绝句","c":["春来游兴比花浓，归折花枝路几重。","绿野风和人薄醉，閒过山寺不闻钟。"]},{"t":"是日适逢寒日归途有作次方干寒食过东阳韵 其二","f":"七言绝句","c":["他乡半是故乡人，佳节同游日未曛。","荒冢纸灰忽飞起，归心谁得似归云。"]},{"t":"陈雪杭邮寄白云洞读书图题作，诗以复之","f":"七言律诗","c":["怕听他乡金缕歌，新词题到怅如何。","东风有脚留诗住，飞瀑无心送鲤过。","石洞句多惭务观，水亭图寄话东坡。","明朝欲放云归去，长与严江月影磨。"]},{"t":"清明南郊看桃过友成、崇正两书院遗址感赋 其一","f":"五言古诗","c":["南山聚名迹，岁久苦沈湮。","有桃芳山麓，络绎招游人。","游人爱春绿，谁能重斯文。","藉得徵文献，我辈全其真。","丰碑立道左，风雨泣晨昏。","鸿文不可识，手剔藓苔痕。","大书讲学处，成公遗泽存。","吾怀东莱子，南宋走浙闽。","北山仁山继，婺学培本根。","矧此友成号，赵氏实始振。","从学有乔葛，儒林作名臣。","忠如李正节，浩气塞乾坤。","降至倪陈辈，授受实传薪。","贤哲集于此，花鸟露精神。","弹指数百载，黍油麦苗新。","池清閒澡濯，左右犹逢源。","想见侍坐暇，出入道义门。","问碑碑不语，梨花满前村。"]},{"t":"清明南郊看桃过友成、崇正两书院遗址感赋 其二","f":"五言古诗","c":["村前塔影矗，粉白比琼玉。","循行踏香泥，清溪曲而曲。","溪水送好香，潺潺来断续。","空山空无物，三椽铺老屋。","草深狐兔眠，树枯鹯鹰逐。","村妪懒不知，门外饭脱粟。","瓦砾埋残碑，褰裳从头读。","知是古梵宫，缁流竞托足。","有明郑长官，崇正乐教育。","东望石洞遥，西顾八华绿。","叶许此中兴，名义良不俗。","修葺相接踵，苕溪费博学。","祔以孙石台，祀事衣冠肃。","何经百馀年，山灵额频蹙。","巍巍西岘峰，终古挂鸣瀑。","唐宋峙二亭，涵碧与水乐。","刘郎大小苏，题句争诵熟。","地脉毓秀奇，兴废常往复。","所期贤有司，不让前贤躅。","鼓吹有六经，便是此山福。"]},{"t":"香亭招饮竹屋","f":"七言律诗","c":["道人不见写秋荷，剩有溪流环素波。","三到禅关容醉客，一番清梦笑春婆。","桃栽小榭红妆瘦，竹压平檐绿荫多。","绝妙暮山登啸处，馀音缭绕答樵歌。"]},{"t":"上巳送师竹归苕溪用前韵","f":"七言律诗","c":["送归人值暮春天，顿触离怀在眼前。","满地绿阴诗似海，一帘花影酒成仙。","惠连未醒西堂梦，安石还随东墅缘。","惆怅武林山水接，思亲忍读白云篇。"]},{"t":"同日饮洛翘处转至周宅","f":"七言古诗","c":["窗前学书晋永和，窗外山色入青螺。","永和帖言休禊事，群贤不集劳思多。","午餔将酣手将覆，忽来知心载酒过。","神如行云流如水，以文为网礼为罗。","罗致奎映楼之北，兴高若剑出太阿。","鹦绿泉香烹新茗，鹅黄酒泛郁金波。","笑我连朝困饮食，疲兵那得荷矛戈。","再战再北援不至，不入诗魔入睡魔。","座中佳士新取妇，宛如兔丝附女萝。","夭桃枝头春意闹，踏青池畔裙色拖。","酒馀罔识时朝暮，踵门醉倒屋婆娑。","春华自当惜年少，结并蒂花出水荷。","嗟哉东园有好女，徐行佩玉不鸣珂。","芳菲固得赏幽谷，过时不采空蹉跎。","归读南华经一卷，轩车不到新如何。"]},{"t":"至法界寺访宋胡侍郎铸钟香亭留饮","f":"七言古诗","c":["古华严寺有名钟，作自赵宋祥符中。","勒四言铭闻人建，铸者为谁曰胡公。","胡公仕宋侍郎职，尝苦金严年不丰。","请宽苛政蠲丁税，诏书特下快民风。","自是乡贤惠桑梓，一乡庙食祀有功。","乃今人未明其故，漫加帝号齐尊崇。","香火年年连吴越，不独编氓祝婺东。","我来吴宁寻遗迹，有法轮碑峙岘峰。","先民已叹沈沦久，长对空山夕照红。","寺居城闉往来数，欲访钟铭追前踪。","几经烽火变迁后，铁石销磨金在镕。","此铜钟且无其器，遑云斑剥蚀苔封。","我闻汤盘与孔鼎，词存千古走蛟龙。","层楼猛簴今寂寞，黄钟大吕闻太空。","何必金刹考古制，欲与凫氏论旋虫。","高子幸非辩追蠡，蓄酒如池香味浓。","招我一笑莫停饮，绣佛场前列千钟。","我侪善学端有在，如木钟撞金木攻。","大小鸣由大小扣，发人清省备藐躬。"]},{"t":"步东郊至卢宅","f":"七言律诗","c":["贪听溪流夹路喧，同人缓步入前村。","满郊绿树迎长阪，一带平桥护短垣。","好鸟声声春水畔，斜阳处处远山痕。","落花被径无人埽，客到何妨不叩门。"]},{"t":"襄校东阳县试卷事竣柬梓材","f":"七言古诗","c":["东白巍峨毓秀奇，搜岩采干系吾思。","方欣文字随缘结，适届珊瑚撒网期。","首夏风光荣草木，残春烟景艳台池。","筵烧椽烛纱窗静，梦醒藤床角枕移。","问字非关扬子宅，瞻型恰傍向公祠。","红莲朵朵廓开缓，白战家家铁不持。","院锁无哗清雀角，笔排有阵落乌丝。","惊人未得长城句，快我先闻幼妇词。","乱似暮鸦当户噪，情同归燕隔帘窥。","为分燕石心常苦，恐溷鱼珠手屡披。","冰雪为怀量玉尺，文章佐酒酌琼卮。","芭蕉绿荫粗能赋，泉石清音可与诗。","思坂谁堪展骥足，解经绝少说羊皮。","书多破体区淮别，句碍冘长去蔓滋。","既获品题佳士许，更教得失寸心知。","标来新义差明眼，思入匪夷亦解颐。","十倍邻封才济济，兼旬分校日迟迟。","鸡群不数尝千蹠，鹤立偏教失一夔。","漫道晷檐争小试，还占台阁是初基。","儒臣云集欣留葛，孝子风徽赖有斯。","石叱洞天仙得路，金携昏夜我谁欺。","幸资璞玉他山错，岂乏明珠沧海遗。","沆瀣从知关夙契，苦辛敢自负初时。","功名鹊起前程远，八华遗芳在得师。"]},{"t":"用洛翘韵咏紫阳花五十韵","f":"五言古诗","c":["空山留小草，花亦紫阳呼。","古洞今名郭，奇葩尚系朱。","苍黄随浊世，清白见真吾。","乞种原无伪，营生莫笑迂。","深红排小蕊，嫩绿衬灵株。","春暖英含秀，秋凉萼吐苏。","晴霞烘远岫，绛雪映名区。","支派承濂洛，良苗接泗洙。","心田勤灌溉，艺苑漫荒芜。","圣域无凡艳，贤关有坦途。","佩来青异拾，拖去翠平铺。","省识尘氛澹，从知道味腴。","傍厓严砥砺，面壁切廉隅。","区别锄非种，栽培擅化枢。","露浓庭折槿，日永案编蒲。","径岂嗟茅塞，功还积染濡。","陌新忙粉蝶，岩暮落金乌。","乐处疑馨桂，遐心咏束刍。","本根寻鹿洞，枝叶外鹅湖。","兰操丰标洁，荆荣德教敷。","宾寅旸谷近，卓午峭峰俱。","识主飞巢燕，追踪幻履凫。","砚耕同晚岁，学殖得吾徒。","迁地荣枯判，踰闲大小殊。","人看汾树隔，材比峄桐孤。","蠲忿萱无藉，摩空藻每纡。","剪裁殊贮柿，粉饰慎操觚。","异卉供欣赏，群芳式楷模。","伯恭常坐啸，华父此驰驱。","至理拈微笑，柔姿道大扶。","覃思同灿烂，树骨自清癯。","郎署薇堪对，文坛杏转输。","林应称箸作，采欲润璠瑜。","多识诗笺陆，生机易变虞。","和风披座满，化雨滴阶苏。","魏第争声价，匡庐入画图。","蜀葵神向往，水蓼手描摹。","雅拟康成带，休誇玉局符。","凤仙形碻肖，蛾子术难诬。","润色寻章句，光华照典谟。","兰滋吟叶适，梅隐忆林逋。","潘县开难遍，陶篱采足娱。","再芳苗裔盛，遗象瓣香孚。","草稿残馀籍，丹铅剩说郛。","蜂儿兼旧榧，鱼婢戏初芙。","匿迹春生脚，韬光物耀躯。","莲芳怀茂叔，窝乐访尧夫。","药圃生芝圃，长衢击壤衢。","性禾咸长养，善米例泥涂。","八婺绵遗泽，芬芳式大儒。"]},{"t":"中秋前夕牌头题壁依前韵","f":"七言律诗","c":["万山妆澹到中秋，归路年年快卧游。","水泻平桥移足底，树狂落叶打人头。","久疏似友新醅饮，乍晤犹亲旧句留。","此去大江看月满，转愁风雨急扁舟。"]},{"t":"九月二日病赴睦州 其一","f":"七言绝句","c":["挂帆镇日忘舟行，时讶床头金铁鸣。","过尽严滩七十里，隔篷惟听画眉声。"]},{"t":"九月二日病赴睦州 其二","f":"七言绝句","c":["相逢萍水话扁舟，舟到严陵竟卧游。","瞥见双峰云外插，此心添得是离愁。"]},{"t":"偕海宁倪又田登秀亭","f":"七言古诗","c":["严陵山水蓄不平，气撼大江奔鲲鲸。","此峰又如赴渴马，勒鞍突入梅花城。","城头历乱姑缭曲，三百六十朵数清。","何年妙手著山顶，拓地庀材筑此亭。","山已钟灵名毓秀，合似秀名为亭名。","南北峰头齐插脚，东西湖面净洗晴。","我来秋高气愈爽，倪迂倪迂得共登。","云路原非别有天，我欲与子御风行。","山下有泉分清浊，探原此地最上乘。","此心本原證无异，濯缨濯足徒取憎。","目极江涛东流去，日落林峦猿鹤惊。","山前遥指荒祠在，还当一访严子陵。"]},{"t":"饮建昌山亭寻先题亦潇洒楼遗址，敬次原韵","f":"五言古诗","c":["山色盘苍郁，奔赴严子江。","建昌勒其下，江涛气势降。","独宏保障功，合住神仙宅。","烟雨护林峦，蛟龙潜波泽。","我来九秋节，萧瑟物尽搜。","狂飙面疾割，小月斧初修。","酌酒暮山头，山行何朗朗。","吟啸当危栏，万山音环向。","作赋悲王粲，落帽笑孟嘉。","零落有时至，所惜在朝华。","遗址寻岩阿，真情起林表。","犹是好江山，那不乐鱼鸟。","望云亲不见，卅载系我思。","思之不可得，恐为猿鹤嗤。","舟帆江水流，云雾峰头逐。","时乎不再来，宝剑长鸣椟。","会出造楼手，潇洒见旧胸。","先贤与先泽，我自得所从。","好句留性天，慎勿戕柳杞。","把盏竹翠间，敲棋松阴里。"]},{"t":"登四面云山楼赠宗郡守","f":"古风","c":["我生夙抱看云癖，欲驾霄汉舒长翮。","我生好入名山游，欲跨鸾凤穷双舄。","年年赤脚走八华，踏破洞云处处遮。","山灵招我往复还，许我身住白云家。","无端飞入富春里，南北东西看云起。","好山面面回，高楼一望发狂喜。","上有飘渺之亭台，下无纤屑之尘埃。","浩乎远者是江水，缭而曲者是城垓。","有时幻作龙蛇势，飞泉百道忽奔逝。","有时化作锦绣裳，美人长袖来摇曳。","片刻能呈无数妆，出云降雨人尽望。","封蔽千岩日不足，神灵到此快徜徉。","无何收尽人间雨，轻云一缕当空舞。","停停袅袅香上炉，勃勃蓬蓬气出釜。","云山变幻本无穷，爱此云山四面通。","凭阑日日忘休息，乌龙之状其犹龙。","范老当年称潇洒，此地长吟事真解。","赵公赏春筑有亭，好山不用一钱买。","何幸风流新使君，继起山楼说看云。","云山岂为逞奇诡，欲祈甘澍福我民。","鲰生雅不解忧乐，对此胸襟亦寥廓。","山邪云邪伴斯楼，飘飘欲觅缑山鹤。"]},{"t":"偕叔兄襄校严郡试卷居双峰书院先人课士地也，感赋","f":"五言古诗","c":["桐庐江清浅，潇洒属兹邦。","官师推人杰，赵范与吕张。","清献琴鹤去，希文柤豆香。","遗徽留教养，东莱实提纲。","况有南轩辅，吾儒道大光。","道光岁乙未，先人除上庠。","寻原历五载，珊网期相当。","远迩人负笈，利钝锥处囊。","谓士无气节，先筑子陵堂。","谓士无勇敢，大书商氏坊。","时逾兵火劫，人心犹未忘。","幸哉贤太守，不令斯道伤。","劝农归根本，兴学资息藏。","十月旁死魄，闱棘锁峰双。","罗致我兄弟，文字饮壶觞。","明月成三影，夜雨话连床。","有时窗风发，灵椿僾乎望。","当日丹铅席，今朝角逐场。","境虽异今昔，神来不殊方。","叹我吹埙篪，学殖将芜荒。","聊慰联棠棣，不为参与商。","入梦言当务，勿以文艺狂。","用力有未逮，漫自擅雌黄。","课功有未邃，毋自快否臧。","恍见趋庭对，心神两彷徨。","醒来披卷帙，高烛何辉煌。","理达辞能举，斐然亦成章。","后生非不秀，先达在洋洋。"]},{"t":"雪杭杀鸡酌酒招书屏幅，因事不果，以诗志之","f":"古风","c":["不爱家鸡爱野鹜，王子当年诽痴腹。","为爱野鹜杀家鸡，陈子今朝见太奇。","我生少壮忘执笔，谴呵时闻趋庭日。","稍知执笔喜大书，钩银画铁力不如。","学力未深见未广，涂成墨猪空有象。","象作秋蛇春蚓形，或文浅陋语不经。","何期索者集沓至，岂以此行为高致。","无乃嗜好俗浮沈，非因换鹅写来禽。","可怜刻楮年年苦，学书未就苦如许。","呵冻寒天冷不知，挥毫夏暑汗下滋。","陈子本亦善点画，闻我斯言齐蹙额。","焚弃笔砚涉不情，奔走投好实自烹。","解人鲜不能解事，酒肴今非为君饵。","得意濡首倍足豪，又非以书卜老饕。","二载心交见如此，实与此情类相似。","不然退笔成冢亦何为，前贤多少快临池，虞褚颜欧偶见之。"]},{"t":"十月十九日去严州","f":"七言律诗","c":["果见严滩彻底清，孤舟来去怎忘情。","江如学派迂能达，山似诗怀看不平。","出水送君鱼知味，穿林识我鸟呼名。","双峰回首慈云近，亲舍今朝有阿兄。"]},{"t":"长至后一日奉东邑节孝姓氏总牌入祠，赋诗落成","f":"楚辞体","c":["两仪分乾坤，阴阳至理存。","生而为夫妇，肇始重人伦。","常变不逾节，死生安足论。","所以性天在，海陬协平均。","为妇全其节，为女孝于亲。","捐躯临患难，就义得归真。","我长苕霅间，趋庭时有闻。","阐幽扬毅魄，发显表贞魂。","烽火十数载，姓氏忽焉泯。","太岁在癸酉，招我有白云。","片片起古洞，道义为之根。","善哉顺地道，雅与德为邻。","惜历红羊劫，名半萎灰尘。","父母斯土者，臭味幸同群。","遗轶承残简，耆老徵献文。","隋宋迄今日，千百会纷纭。","曰贞烈节孝，大书列四门。","仅以贤寿著，未敢与明禋。","我作姓氏考，体例藉披陈。","次年一阳至，享祀升苾芬。","刲羊中堂屋，神兮降悽焄。","父老乐皞皞，妇孺话欣欣。","仪成礼未毕，有客情致殷。","叹自兵乱后，大义多沈湮。","夫妇之道苦，阴霾阳不振。","或以中道绝，或以末路分。","志气浸浇薄，非皆由贱贫。","廉耻丧习惯，非皆忘旧恩。","怛然闻斯语，使我额蹙频。","秉彝好懿德，善良今其熏。","敬为叙此意，敢告未亡人。"]},{"t":"将去东阳留别诸友用洛翘韵","f":"七言律诗","c":["阳生冬至又来春，遽唱骊歌拂袖尘。","飞雁搏沙原小聚，鸣莺求友听常新。","山林迎送偏劳我，翰墨因缘大快人。","临别开尊无限意，顿教佳酿失芳醇。"]},{"t":"留别李春皋阁学 其一","f":"七言律诗","c":["秀气何年毓木香，士林争仰鲁灵光。","将周甲子琼林宴，早到公卿弟子行。","坐对孔山乔葛远，学习婺派吕朱长。","回头卅馀年前事，半入篇章人不忘。"]},{"t":"留别李春皋阁学 其二","f":"七言律诗","c":["鲰生何幸接光仪，两载追随遇亦奇。","华衮褒成先子赞，师门介我校官诗。","一庭花树春秋好，满郭云山来往宜。","此日阶前辞别去，敢云问道已嫌迟。"]},{"t":"师竹属孔生绘雪中山水赠行，因名消寒归去图，系以诗","f":"五言律诗","c":["一天风雪里，归去是今朝。","送客诗初就，推篷冻未销。","连年云洞话，三折富春潮。","清白留图画，斯人不可描。"]},{"t":"腊八由东阳至金华肩舆值雪，用洛翘赠行诗韵 其一","f":"七言律诗","c":["车驰一路静无哗，司马题桥今莫誇。","天为旅人添好事，雪非诗意不飞花。","空林落寞栖巢鸟，茅屋依稀卖酒家。","嗟我仆夫殊老马，涂迷日暮怅三叉。"]},{"t":"腊八由东阳至金华肩舆值雪，用洛翘赠行诗韵 其二","f":"七言律诗","c":["漫道轻车似水流，苦行苦若我吟秋。","帘垂终日嘲新妇，玉种千山学卧游。","憀落荒村无犬吠，弓刀小队映蝥头。","閒除篷雪融成水，题句邮亭佳话留。"]},{"t":"腊八由东阳至金华肩舆值雪，用洛翘赠行诗韵 其三","f":"七言律诗","c":["纵横驿路息吟肩，漫说明朝雪霁天。","倦整行囊衫尽湿，独醒长夜枕频迁。","邻家饭熟饶情话，渔市人归数酒钱。","赢得竹居今住竹，一编怅触别时筵。"]},{"t":"腊八由东阳至金华肩舆值雪，用洛翘赠行诗韵 其四","f":"七言律诗","c":["连朝风雪去东阳，征路争如云路长。","池傍堤高迷辙迹，履艰地滑甚冰霜。","重城启钥衔枚走，深夜敲门煮酒忙。","同是他乡行役者，书成寄与雁鸿行。"]},{"t":"岁朝杭寓独居书除夕思母之作五首 其一","f":"七言律诗","c":["偶住西湖六度春，旅怀怅触在今辰。","一年怕说是除夕，卅载何曾离老亲。","独酌屠苏滋味薄，频闻爆竹岁华新。","遥知塔拥双峰里，压岁分钱少一人。"]},{"t":"岁朝杭寓独居书除夕思母之作五首 其二","f":"七言律诗","c":["妻孥劝酒不停杯，分岁迎年自主裁。","席设一堂团聚样，仪成遥拜笑颜陪。","推情此际谋诚拙，追念前尘我尚孩。","间听小孙初学语，娘娘明日好归来。"]},{"t":"岁朝杭寓独居书除夕思母之作五首 其三","f":"七言律诗","c":["归来必得阿兄随，否则仍怀异地思。","萱草果能蠲忿恨，雁行何敢独差池。","岁原无晚他时砚，白不能除两鬓丝。","安得诛茅偕隐去，名山终养我奚疑。"]},{"t":"岁朝杭寓独居书除夕思母之作五首 其四","f":"七言律诗","c":["生憎世俗太粗疏，未得真情赋遂初。","禄养岂能全志养，分居总不若同居。","情欢野老偏隆古，孝尽颛愚胜读书。","同是思亲逢节候，天涯多少倚门闾。"]},{"t":"岁朝杭寓独居书除夕思母之作五首 其五","f":"七言律诗","c":["倚遍阑干兴未阑，无端狼藉笑杯盘。","荆妻依恋庭帷远，游子归来风雪寒。","壮盛韶华空寂寞，迢遥家室话团栾。","春晖从此年年好，何计偕承菽水欢。"]},{"t":"张黼臣见题拙稿步韵谢之","f":"七言律诗","c":["迩年世事尽翻新，诗酒如君亦雅人。","拨去穷愁留血性，好看春色助精神。","乔枝旧契书容读，棣萼新芳趣自真。","覆瓮一编叹已久，今朝何幸拂浮尘。"]},{"t":"春仲偕黼臣乘小舟泛西湖，由孤山白沙堤步归，次前韵 其一","f":"七言律诗","c":["草色青青柳色新，偷间学作少年人。","斜阳半郭情饶我，诗景全湖妙入神。","艇小冲开春涨暖，花浓照见酒怀真。","平湖陡觉湖平好，未到孤山早涤尘。"]},{"t":"春仲偕黼臣乘小舟泛西湖，由孤山白沙堤步归，次前韵 其二","f":"七言律诗","c":["西泠别后两年新，山色如逢蕴藉人。","但得楫舟安水国，无愁波浪弄风神。","岩空人去閒花住，岸远禽来好语真。","回首婺东桃洞在，几多春意绾车尘。"]},{"t":"题馨甫亲舍望云图册","f":"楚辞体","c":["我生少小悲失怙，十五年来未抔土。","壮来又叹轻别离，六十老母难得聚。","举头浩浩白云天，无尽行云有尽年。","归云不比去云速，别亲那得省亲难。","钱塘老友胡馨甫，废诵蓼莪痛肺腑。","孝思发为古文章，画图咀出旧甘苦。","自说从军燕赵间，东南半壁惊烽烟。","骨肉分飞家书绝，关河迢递金鼓喧。","途穷日暮辄回首，怅望家山何处有。","一日思亲十二时，归梦不归难消受。","惟有云影来朝朝，送入天涯路不遥。","隐约亲舍出其下，见云如见双亲招。","招之不至心凄怆，把酒问天何独妨。","悔身不如雁与鸿，秋来犹得飞南向。","我闻此言发长叹，多少游子摧心肝。","生不能养死不葬，一般滋味总辛酸。","嗟嗟人生穷通得失皆天成，何必纷纭车马去门庭。","纵然负米逮养出百年，藜藿当年无限情。","况乎菽水莫承常常尔，迟暮光阴疾奔驶。","转瞬已不见高堂，永诀暂离伤奚似。","披斯图，泪如珠，愿为天下人子大声而疾呼。","与其风尘奔走富且贵，不若贫贱困苦长家居，云兮云兮知我乎。"]},{"t":"清明独步湖上饮临水酒家 其一","f":"七言律诗","c":["又到清明桃李开，钱唐门外独徘徊。","野田荒冢谁存问，风雨烟波孰主裁。","近水楼台招我去，随堤鱼鸟逐人来。","销金窝乏销金侣，剩有南山照酒杯。"]},{"t":"清明独步湖上饮临水酒家 其二","f":"七言律诗","c":["酒醉黄垆暮不埽，湖光呼吸入几微。","沽钱遇客非尘俗，放棹逢僧亦化机。","得佐新泉烧野火，莫攀垂柳插柴扉。","回头犹怅重城隔，难与閒鸥日日飞。"]},{"t":"次韵复黼臣赠诗 其一","f":"七言律诗","c":["滔滔江水去如斯，犹幸知心遇未迟。","诗不求工偏适性，事惟近古那嫌奇。","传家自具龙驹种，处世无营鴳鹊枝。","太息故人今不作，羊公谁见岘山碑。"]},{"t":"次韵复黼臣赠诗 其二","f":"七言律诗","c":["橐橐斋前听屐过，一庭皓月映藤萝。","阮生此日雄心减，平子当年作赋多。","坐对银缸閒漏刻，兴乘画棹到烟波。","好呼越酿欣同癖，驱我愁魔有酒魔。"]},{"t":"题山阴沈少牧绉绿山房印笺为黼臣作 其一","f":"七言绝句","c":["女娲鍊石夺天工，散作丹砂落纸红。","刻画本来臣独擅，壮夫何必陋雕虫。"]},{"t":"题山阴沈少牧绉绿山房印笺为黼臣作 其二","f":"七言绝句","c":["元龟负篆导山川，禹庙同瞻东浙仙。","赖有一编传古意，不须青玉说当年。"]},{"t":"次韵送黼臣之吴门 其一","f":"五言律诗","c":["毕竟狮林好，江山特放回。","苏台香雨散，吴市美人来。","船到疏钟夜，花倾曲水杯。","刘郎重到日，春树不须栽。"]},{"t":"次韵送黼臣之吴门 其二","f":"五言律诗","c":["昔我吹箫地，临岐约略论。","夕阳荒寺梦，古塔旧巢痕。","梁庑空颜色，胥门乱晓昏。","寄声浣纱女，能有未归魂。"]},{"t":"咏桃李杏梨四花各以士事比之 其一 桃","f":"七言律诗","c":["才士年华一望新，好将红紫斗芳辰。","奇文焕烂殊平淡，绝世声名得笑嚬。","艳福许消金谷酒，凡枝不到武陵春。","恒蹊此日推先步，多少秦人未问津。"]},{"t":"咏桃李杏梨四花各以士事比之 其二 李","f":"七言律诗","c":["高士风光在目前，不须丰度溯当年。","独清格调神都静，亦列门墙气倍妍。","水榭立残明月夜，朱栏倚遍暮春天。","伴来桃杏皆时辈，敢以孤芳谢众缘。"]},{"t":"咏桃李杏梨四花各以士事比之 其三 杏","f":"七言律诗","c":["佳士襟期似旧不，山林廊庙莫须求。","繁华才醒江南梦，车马方誇冀北游。","未减诗情红日里，长留春意小枝头。","归来初罢琼林宴，间与东风快唱酬。"]},{"t":"咏桃李杏梨四花各以士事比之 其四 梨","f":"七言律诗","c":["寒士生憎物候繁，犹能花样及时翻。","胭脂不染留真面，风雨无欺赖宿根。","雪压一枝难免俗，冰清半夜最销魂。","年来无复游人问，空对黄昏深锁门。"]},{"t":"题秦虎侯所绘梅花风雪图卷为杨春浦作","f":"楚辞体","c":["雪花历乱扑衣裾，梅花错落逐舟车。","花花姑为逞奇诡，惆怅诗人长道途。","秦子当年发雅兴，斗酒十千踏雪沽。","醉歌高楼拂素纸，诗画赠行行不孤。","海风捲起波涛立，日暮征帆远莫呼。","徘徊歧路归不得，君去越兮我留吴。","况复红羊逢大劫，太息干戈无地无。","东南半壁擎天柱，甬江申江燕幕居。","所赖此心共千里，不愁饥渴害真吾。","男儿破浪长风志，所恃忠信涉江湖。","何以昊天独不吊，不使贤豪老其驱。","后先齐赴玉楼召，空馀翰墨式楷模。","我钦友谊重金石，契结人间道不殊。","既为题卷颜风雪，敢为缀句长欷歔。","多少交情惭管鲍，盍不回头认斯图。"]},{"t":"高香亭由东阳寄何氏兰亭本，诗以谢之","f":"五言古诗","c":["熟闻何一白，流传一片石。","石刻晋永和，禊帖留真迹。","当宋南渡时，维扬失不获。","三百有二年，淘井竟觅得。","天许还会稽，婺在会稽域。","我客婺之东，两载欣游历。","烽火几变迁，石已遭分擘。","分石藏四家，家藏倍珍惜。","购之良独难，宝筏回空寂。","何幸高达夫，求不遗馀力。","典裘得青铜，手民给千百。","乡民识好官，开诚表先泽。","我居西湖西，梦寐萦反侧。","忽下朵云来，惠及山中客。","尺幅饱琳琅，银钩兼铁画。","愧非学书人，真本赚萧翼。","白云往复还，不愁江天隔。","愿如金石交，不在数晨夕。","复读所寄书，坐慰如良觌。","世无薛绍彭，赝本从何易。"]},{"t":"三月二十六日与共甫偕吴门吴憩堂游云栖，翌晨步江干转至虎跑寺，由湖上棹归 其一","f":"五言古诗","c":["钱唐江一曲，处处栽修竹。","竹林深复深，接入五云麓。","有坞曰云栖，五色云归宿。","赵宋结茅庵，代住高人躅。","前明隆万间，祩宏僧不俗。","坐爱好山林，铸就新语录。","一卷法慧经，年年人熟读。","塔院在其旁，高树盖新绿。","好山有好泉，潺潺听往复。","佳处在此间，逾时看不足。","洗心亭洗心，归路淡无欲。"]},{"t":"三月二十六日与共甫偕吴门吴憩堂游云栖，翌晨步江干转至虎跑寺，由湖上棹归 其二","f":"五言古诗","c":["移舟泊江干，晚烟春树团。","同行懒归去，秉烛发高言。","沽酒招舟子，聊慰江上寒。","蓬窗时眺望，波平静不澜。","妓船管弦息，沙岸鸥鹭閒。","此心有法慧，何必谢尘缘。","梦入华虚境，驰驱大道安。","潮声惊夜半，疑是出山泉。"]},{"t":"三月二十六日与共甫偕吴门吴憩堂游云栖，翌晨步江干转至虎跑寺，由湖上棹归 其三","f":"五言古诗","c":["山泉说虎跑，游兴晨更豪。","舍舟登彼岸，行行不辞劳。","数里越云岭，泉声何滔滔。","两山夹集树，高际拂凉飙。","三椽铺老屋，山僧先诛茅。","寻胜倚古井，汲泉野火烧。","传闻泉流出，并自李唐朝。","寺僧苦潦渴，神遣二虎淘。","往事莫须问，饮我热已浇。","碑摩东坡字，读之意亦消。"]},{"t":"三月二十六日与共甫偕吴门吴憩堂游云栖，翌晨步江干转至虎跑寺，由湖上棹归 其四","f":"五言古诗","c":["鸡黍田家具，深林乐且住。","酡颜立茅檐，茶笋香处处。","有鸟忽呼归，我亦寻归路。","仄径出蚕丛，花港唤野渡。","买棹回峰前，好风为之御。","苏堤白沙堤，多少游人误。","香车络绎来，画船泛无数。","昨江今日湖，风景笑如故。","禅心与道心，至此一齐悟。"]},{"t":"用西洋法照象，诗以纪之","f":"五言古诗","c":["铸金象人物，后世易青丹。","丹青成容易，不若铸金难。","所以金能寿，画图偶尔传。","然犹有传者，良由致力全。","画家言画法，点睛越数年。","智竭神乃见，阿堵传笔先。","何来西域制，迩时成大观。","有水黝其色，瓶注秘不宣。","云是采仙药，合成费万钱。","天朗气亢爽，裙屐集喧阗。","红日当头朗，明镜睻目鲜。","彼镜摄此镜，容貌别嗤妍。","沃以涓滴水，气勿临风迁。","倏忽擘素纸，须眉呈宛然。","我来偶为此，形影化无端。","岂有精妙识，能达秋毫颠。","大都人工巧，不能夺上天。","吾闻药石性，不比金铁坚。","逾时性弛药，色亦化云烟。","嗟哉人寿世，百年空往还。","我象欲示后，何先我生湮。","难易分久暂，至理实无边。","海外多奇术，孰能逃圣言。","我相本非相，作此随俗缘。","家室识今吾，玩而老我焉。","若夫真面目，自来多不刊。","英姿来飒爽，瞻拜古衣冠。"]},{"t":"次韵复湘文观察寄示白芍药诗 其一","f":"七言律诗","c":["新使声华驾沈珩，诗章何幸得投琼。","元君佳兴琉璃净，韩子仙宫格韵清。","昭质不知金带贵，冰心争说玉壶明。","富春山里春多少，夺得延春亭畔生。"]},{"t":"次韵复湘文观察寄示白芍药诗 其二","f":"七言律诗","c":["休将婪尾惜芳筵，犹永年年清白传。","翻锦那堪云缦缦，当阶赖有月娟娟。","情深雪海春离别，色乱香丝人渺绵。","羡杀前身东武种，盘盂样拥玉团圆。"]},{"t":"又次韵二首 其一","f":"七言律诗","c":["我是璇宫近侍身，浓妆忍与碧朱伦。","缟衣未卸番风尽，珠泪才乾仙露新。","正说光华依旭日，何期霜雪殿阳春。","非关白发谈天宝，悽绝琼楼乍坠人。"]},{"t":"又次韵二首 其二","f":"七言律诗","c":["瑶台底是绝人群，稽首东皇挽日曛。","风物纵成双鬓雪，尘寰已隔万重云。","非徒粉本扬州画，欲使灵根天下闻。","小草无心安朴素，梢头弄句不成文。"]},{"t":"叔韵以城西看山诗索和倚韵复之","f":"古风","c":["城西山势如游龙，起伏奔驰神莫状。","城西山色如好女，隐约倩秀遥相望。","报俶塔近白沙堤，东接城垣尤豪宕。","奇石危磴破空来，突兀直前无依傍。","我居穷巷将及岁，寂无闻见心惆怅。","霉雨匝月更困人，鱼鳖灶床清抱恙。","幸看此山日不足，高楼俨列碧屏障。","兼喜雉堞一道横，流水短墙均无妨。","姑作曲势走往复，山容未宥使全放。","宜雨宜晴亦宜月，妙境天开何清旷。","有时杯影落桥头，灵光呼吸涤肺脏。","呼之欲出招不前，画意诗情淡相忘。","酒醒转恐愁又来，山作解人总笑向。","嗟彼西湖多少等临客，孤负此峰莫能访。","香车宝马过云烟，畴得刻意穷形相。","忽来同调说看山，示我新诗胆益壮。"]},{"t":"竹醉日","f":"七言律诗","c":["鄠社檀溪夙著名，琅玕醉倒别关情。","雪消前度开清宴，风暖今朝怅举觥。","涓滴酒泉聊慰藉，蹒跚仙骨独分明。","虚心借问东南美，多少云根外水生。"]},{"t":"分龙日","f":"七言律诗","c":["江海空濛烟雨天，分龙时节话年年。","谁知鳞甲翻长夏，常见风云战野田。","犁逐千家秧插未，虹藏万壑水流膻。","南辕北辙原无别，准备雷车改著鞭。"]},{"t":"西湖棹歌 其一","f":"七言绝句","c":["春波淡漾雨如丝，放棹湖滨最好时。","几处楼台明灭里，黄莺啼上绿杨枝。"]},{"t":"西湖棹歌 其二","f":"七言绝句","c":["垂杨两岸舞枝慵，水涨桃花浪几重。","却爱船如天上坐，一声风送凤林钟。"]},{"t":"西湖棹歌 其三","f":"七言绝句","c":["钟声断续出招提，泼剌游鱼上草泥。","赤脚老渔生计足，湖东棹过又湖西。"]},{"t":"西湖棹歌 其四","f":"七言绝句","c":["绕城浑在水云乡，剪刀裁云费较量。","旧水不知新水碧，晴云争似雨云忙。"]},{"t":"西湖棹歌 其五","f":"七言绝句","c":["山青雨后片云无，月点湖心琼玉铺。","潭印两三人影度，夜深惊起一双凫。"]},{"t":"西湖棹歌 其六","f":"七言绝句","c":["花明鸟语绾行云，荡桨归来日未曛。","转过苏堤人不见，停舟又到岳王坟。"]},{"t":"卜居六咏 其一 风亭","f":"七言律诗","c":["先筑茅亭地拓弓，泠然惠我有清风。","劳劳历尽关河险，面面犹吹尘垢空。","雨过偶然巢喜燕，云开争羡遇飞鸿。","前程万里知多少，都在披襟独立中。"]},{"t":"卜居六咏 其二 月榭","f":"七言律诗","c":["曲榭新除亭外幽，贪看月色半勾留。","欣徵冰抱邀明镜，恐误池鱼触玉钩。","华压栏前移得影，云浮树杪漫当头。","从知皓魄无私照，何必经营近水楼。"]},{"t":"卜居六咏 其三 回廊","f":"七言律诗","c":["才经水榭是修廊，往复回环路不妨。","姑作盘旋奇蓄势，能舒步履漫嫌长。","飞飞粉蝶随平槛，曲曲花枝绕短墙。","月转帘腰留一角，及时珍重在诗肠。"]},{"t":"卜居六咏 其四 曲室","f":"七言律诗","c":["廊前曲室费评论，邃密商量道大存。","满壁图书供老眼，一房花石护云根。","懒闻世事居当户，欲谢尘踪坐闭门。","赢得斜阳窗外逗，谁云时节近黄昏。"]},{"t":"卜居六咏 其五 凿池","f":"七言律诗","c":["活泼源头悟到时，才成曲室复芳池。","缘他濠濮知鱼乐，不为楼台得月迟。","尺寸程将工计较，方圆样费我寻思。","著书户闭由来久，涤砚而今便自持。"]},{"t":"卜居六咏 其六 种树","f":"七言律诗","c":["无多绿树荫茅庵，既得栽花种亦堪。","辛苦十年期有用，安排一院孰能谙。","有书偶傍跟前读，作赋何劳枯后参。","杞梓楩楠材足贡，不徒竹箭美东南。"]},{"t":"晚桂","f":"五言古诗","c":["百卉俱飘息，丛桂出高冈。","年年七八月，空际散天香。","有桂独后发，若自甘退藏。","繁枝零玉露，翠节霏轻霜。","西风战阵阵，清籁杂金商。","纫兰既失佩，裂荷早无裳。","仙骨经折磨，高韵起抑扬。","仰天望蟾阙，一枝列上方。","高撷此花者，徐步乐翱翔。","何以同此质，瞠焉不可望。","无知在草木，有意听彼苍。","冬荣本我辈，先后何自妨。","晚枫爱红叶，晚菘饶秋光。","嗟哉涧底树，金粟缀郎当。","迟迟非本意，羞与众草芳。","月中能寄语，乞为谢吴刚。"]},{"t":"早菊","f":"五言古诗","c":["我闻韩魏公，黄花看晚节。","晚而以早名，无乃失其实。","窃谓实辅名，记取花之发。","秋飙扇乍凉，层英齐挺出。","秀色早天成，清香流未歇。","已遍东西园，才到重阳日。","酒兴与诗情，从头说一说。","老圃多秋容，后尘步何术。","盍勿缓须臾，同过九秋月。","花意独不然，幽人抱贞吉。","风雨叹朝朝，岁序惊倏忽。","见几苟不先，鲜能守素质。","况乎傲雪霜，恃此姗姗骨。","树骨于未寒，敖熊且剪灭。","采无栗里陶，餐乏三闾屈。","何必故迟回，虚誉盗高洁。","但经一味凉，足洗三伏热。","芳菲在及时，位置任造物。","并约岭上梅，先报春活泼。","如是称晚香，如是称隐逸。"]},{"t":"秋暮师竹过访偕伍硕甫舟泛西湖纪事集成 其一 湖滨携酒","f":"五言古诗","c":["有客来远方，清晨入我室。","遨游西子湖，此愿如饥渴。","携步到湖滨，孤篷空无设。","山色与湖光，对之叹奇绝。","解意当垆人，助我兴活泼。","遗我酒一壶，不愁秋瑟瑟。"]},{"t":"秋暮师竹过访偕伍硕甫舟泛西湖纪事集成 其二 舟中持螯","f":"五言古诗","c":["秋菊如人瘦，霜螯比肉肥。","既得新越酿，尤爱是团脐。","蟹本无肠物，辱身在涂泥。","今享有心者，俨与樽俎齐。","持来左右手，毕卓是也非。","一波冲鸥鹭，偕至西湖西。"]},{"t":"秋暮师竹过访偕伍硕甫舟泛西湖纪事集成 其三 槛外观鱼","f":"五言古诗","c":["濠上游观乐，游鱼乐何如。","游人亦鱼类，其乐雅相于。","三潭澄秋水，掩映有菰蒲。","朝暾露城郭，波红一角铺。","炎凉到水国，鳞族为之趋。","凭栏忘归去，须知我非鱼。"]},{"t":"秋暮师竹过访偕伍硕甫舟泛西湖纪事集成 其四 寺前放蝠","f":"五言古诗","c":["非虫亦非鸟，蝙蝠状独奇。","又有可奇者，孤眠寺榻西。","谈笑群客至，若不与闻知。","岂病身小弱，我为袖携归。","昏黄出山外，超然忽高飞。","飞鸣出意外，此类犹知时。"]},{"t":"秋暮师竹过访偕伍硕甫舟泛西湖纪事集成 其五 岳坟醉酒","f":"五言古诗","c":["酌酒坐茅檐，檐短酒气吐。","高树蔽目前，全湖茫无睹。","结邻野人家，听我谈肺腑。","肺腑无可陈，岳坟一抔土。","洒酒不尽欢，拔剑思张弩。","铁人知不知，墓门寒千古。"]},{"t":"秋暮师竹过访偕伍硕甫舟泛西湖纪事集成 其六 空谷传声","f":"五言古诗","c":["里湖夹两山，地势倍周匝。","左有放鹤亭，右有宝俶塔。","吟啸出其间，高岸为之答。","醉叱使退归，我亦素娴习。","无乃孤山孤，生性未能合。","樵歌起山头，竟不暇应接。"]},{"t":"臈月将由杭之湖州次韵答载之 其一","f":"五言律诗","c":["不尽分离意，今宵付与多。","围炉成雅会，对酒发高歌。","苕水平如练，明湖净不波。","移舟当雪霁，皓月照藤萝。"]},{"t":"臈月将由杭之湖州次韵答载之 其二","f":"五言律诗","c":["自问迂疏者，相知有几人。","十年倾盖旧，匝岁触怀新。","食右功期化，论交味饮醇。","他时重聚首，益智话频频。"]},{"t":"二十五日由湖回杭，钝斋主人置梅酒舟中，越宿花放，喜赋柬主人","f":"楚辞体","c":["昔日金华去，梅花护我车。","车行苦辘轳，花枝冷不花。","今作吴兴游，梅花共一舟。","舟行不数里，花气盎罗浮。","初见蕊如茧，再见破如剪。","层出胜蕉抽，盘旋殊蓬转。","舵尾笼鸣禽，睍睆度好音。","驿路泄春意，花鸟驱客心。","何为前度梅，芳信分迟速。","造化别无因，位置良难独。","仙骨终清奇，遭逢不可知。","荏苒当春华，名山證素期。","春色连吴越，灵气蕴同室。","我新乐聚欢，身不识离别。","花兮作解人，斯时特地亲。","孤屿林处士，招隐西湖滨。","主人何郑重，佐他酒两瓮。","花香杂酒香，苕霅水风送。","送我夜不眠，起坐觉衣单。","推篷际清晓，还看雪漫天。"]},{"t":"正月十二日由杭挈眷至湖与叔兄同居 其一","f":"七言律诗","c":["偶住杭州十载除，却难抛去是西湖。","泉惟名冷流能远，山得栽梅性不孤。","送我灵峰云叠锦，饶他春意雨初苏。","苕溪烟景天然画，一幅浮家泛宅图。"]},{"t":"正月十二日由杭挈眷至湖与叔兄同居 其二","f":"七言律诗","c":["谁是当年张志和，钓徒终老住烟波。","惭无健笔驱词客，剩有残篇发棹歌。","载酒不妨过北海，爱山仍得效东坡。","风尘纵有嘉宾主，三到吴兴感慨多。"]},{"t":"正月十二日由杭挈眷至湖与叔兄同居 其三","f":"七言律诗","c":["夜泊溪湾听雨声，终宵閒数短长更。","舟中人醒鱼先觉，林外灯残波尚明。","村妇归家藏小艇，邻翁话旧对寒檠。","光阴烈火原容易，又说来朝是我生。"]},{"t":"正月十二日由杭挈眷至湖与叔兄同居 其四","f":"七言律诗","c":["诘朝偏值石尤风，骇浪惊涛在眼中。","无福看山峰压背，有缘邀月色当空。","长途霜气催诗稿，满郭清光到泮宫。","儿女不知重聚首，也从侪辈乐融融。"]},{"t":"偕周君经甫登爱山台感赋 其一","f":"五言古诗","c":["吴兴佳山水，清远无古今。","高台共登眺，城市而山林。","道场一峰秀，相对豁尘襟。","诸毗势奔赴，峰灵妙莫寻。","捲帘纳苍霭，白日未西沈。","朱阑与翠竹，掩映春色深。","东坡追往迹，梅村续前吟。","既怀贤太守，怅触旧时心。"]},{"t":"偕周君经甫登爱山台感赋 其二","f":"楚辞体","c":["树木犹树人，爱山如爱士。","趋庭闻斯言，三十年于是。","沧海变桑田，人物杂悲喜。","相持一尊酒，远慰风尘子。","游子独停杯，四顾情难已。","巍巍苍卞峰，渺渺太湖水。","仿佛神兮来，不期俱集此。","举目谁与言，满林芳桃李。"]},{"t":"白牡丹次冯味吴韵","f":"七言律诗","c":["清白声名压众芳，何期富贵集华堂。","全身珠露初离浴，半面晴云乍洗妆。","月朗瑶台花国色，波凌玉佩水仙王。","唐宫已罢杨妃舞，薄晕罗衣冰雪香。"]},{"t":"初游云巢","f":"七言律诗","c":["群山抱处耸楼台，拔地长松夹路栽。","流水声中寻道去，乱云堆里听经来。","何年高隐留书阁，此日清游濯酒杯。","潭上莫愁龙梦醒，斜阳绕郭不须回。"]},{"t":"五月十二日悼同儿成绝句十首 其一","f":"七言绝句","c":["溯儿生与祖生同，欲以同名继祖风。","谁料不同又同处，偏逢忌日化尘红。"]},{"t":"五月十二日悼同儿成绝句十首 其二","f":"七言绝句","c":["相随阿姆住家乡，赢得聪明话短长。","无恙云山归梦里，当时岂竟弃爷娘。"]},{"t":"五月十二日悼同儿成绝句十首 其三","f":"七言绝句","c":["分离数月复杭州，浪打钱唐江上舟。","一见森森寒玉立，风霜原不为儿愁。"]},{"t":"五月十二日悼同儿成绝句十首 其四","f":"七言绝句","c":["学字还须学读书，旅窗消遣日之馀。","何期此意先窥透，朝晚课功不俟□。"]},{"t":"五月十二日悼同儿成绝句十首 其五","f":"七言绝句","c":["偶病谁知入肺肝，昏黄痰嗽梦难安。","饥驱我到苕溪去，待得归来岁已残。"]},{"t":"五月十二日悼同儿成绝句十首 其六","f":"七言绝句","c":["气虚水肿费猜疑，起伏连番半载时。","报道沈疴消去也，菰城何幸遇天医。"]},{"t":"五月十二日悼同儿成绝句十首 其七","f":"七言绝句","c":["嗟病能医命不能，经过重五病顿增。","四朝粒绝连宵坐，哀此焰残竟灭灯。"]},{"t":"五月十二日悼同儿成绝句十首 其八","f":"七言绝句","c":["教人那得不情痴，临去伤心事事知。","呼遍家人行不得，分明作别断肠时。"]},{"t":"五月十二日悼同儿成绝句十首 其九","f":"七言绝句","c":["平时嬉戏雅情多，抛别同侪没奈何。","晓起堪怜小阿弟，犹从帐里问哥哥。"]},{"t":"五月十二日悼同儿成绝句十首 其十","f":"七言绝句","c":["转轮落劫义虚无，别结因缘父子呼。","最是解人难解事，生于湖郡死于湖。"]},{"t":"钝斋主人赋诗见赠并弁言白云洞读书图作长句谢之","f":"七言古诗","c":["西河太守称汉室，贤知继踵问民疾。","公家兄弟特过之，竞蜚英声腾茂实。","仲氏视学使豫章，玉策持衡道大光。","群季宰治江南北，循吏儒林遥相当。","公也一麾来出守，立德功言务不朽。","初治括苍续金华，清白堂前讴歌久。","农桑自古勒成书，白苏于今式楷模。","经济匡时成卓识，文章致用乃真儒。","况夫早岁训髦士，秉铎胶庠率践履。","教养人材天下奇，诚意正心学如此。","鲰生新从东浙来，遗爱甘棠勿剪裁。","传说近年作吏隐，部民去思每低徊。","不图谒见苕溪上，风雪为介神为王。","阳春成集本词宗，大树论功徵宽量。","愧我生无太白才，何幸身登韩子阶。","常获纵谈陪文宴，非慕高致快含杯。","既荷题图辱奖评，复承赠句谬相与。","渊渊沧海矜尺波，浩浩雷门特步鼓。","当风披诵不自安，昭垂法戒理或然。","会须佩韦慎不害，相见端州使君贤。"]},{"t":"题许云江梅花仕女帐额 其一","f":"七言绝句","c":["何来疏影最怜侬，曾记罗浮梦里逢。","惆怅今宵林下月，美人隔得不惺忪。"]},{"t":"题许云江梅花仕女帐额 其二","f":"七言绝句","c":["银缸背处玉钗斜，多事当年解语花。","赢得溪山归枕席，何须仙眷艳林家。"]},{"t":"题许云江梅花仕女帐额 其三","f":"七言绝句","c":["纸帐玲珑画却如，几生修得到华胥。","诗成准待卿卿唤，酒熟茶香午梦初。"]},{"t":"题陈思召醉读东篱小影 其一","f":"七言绝句","c":["读书嗜酒话渊明，彭泽归来倍有情。","绝妙山光与松菊，谁从画里證三生。"]},{"t":"题陈思召醉读东篱小影 其二","f":"七言绝句","c":["此君醉后好风裁，背指黄华蓠外开。","还读我书寻我乐，何须送酒白衣来。"]},{"t":"代复薛观察即此其洗儿诗韵","f":"七言律诗","c":["藕花香里报新诗，最好麟儿初洗时。","作室有书欣读早，随园得子合名迟。","神驹头角骅骝种，老凤威仪廊庙知。","朱芾君王从此咏，承平雅欲惬心期。"]},{"t":"重九偕张棣笙施衡甫两学博叔兄子承登道场山至万象塔，北望太湖放歌纪事","f":"楚辞体","c":["我生少小客菰城，日对城南山之塔。","塔矗山顶不知名，但喜山塔天作合。","续来此邦已壮年，城郭人民历变迁。","不寻名胜徒惆怅，碌碌车马走烽烟。","何幸今岁又三到，山灵号咷转为笑。","九月九日天气清，漫集壶觞邀同调。","初入平陂蚁珠穿，旋跻危磴猾巢悬。","股栗神眩难休息，攀扶直欲穷崖巅。","忽起天风何浩浩，此身已在千岩表。","昂瞻天外阊阖开，俯瞰群山培塿小。","方见斯塔位置间，卓立苍茫我欢颜。","本有康庄达人境，绝无尘俗绾仙寰。","平时所见乃山背，欲登不登三十载。","端由恒蹊迷浅人，井观万物等盆戴。","崎岖阅尽履坦途，浮障销除證真吾。","到此如酬饥渴愿，装严非独宝浮屠。","浮屠北望渺无极，滚滚洪涛天一色。","吴越具区八百里，塔势空横影卧黑。","山川呼吸灵气通，方丈蓬壶在眼中。","况复奇峰罗七二，奔赴俨出偏师攻。","塔兮会心寂铃语，尽大乾坤理如许。","登临此地揽其全，学海学山齐得所。","山前落日不可留，一啸长空木落秋。","青林红树相应答，读书当有何楷俦。","噫吁嘻，未到山头不见湖，日对此山何为乎。","我今疑晢归去发长歌，欲问看山不足苏东坡。"]},{"t":"陈艺林世交持其尊甫补松世丈溪山无尽图索题，题卷中有先人七古诗，伏读数过，凄然有作","f":"楚辞体","c":["幼读高堂题图诗，诗中尽含无尽词。","我今披图瞻公像，图外殊系无尽思。","时阅四五十年久，劫历水火刀兵后。","城郭人民尽变迁，溪山犹得包诸有。","天生福地付福人，画本印證风味真。","山灵到处神呵护，不随俗氛委灰尘。","况复宗子孝行笃，宝泽胜比宝金玉。","护此图卷舟车偕，患难捧作蓼莪读。","十载流离海上归，适我菰城三度来。","相逢歧路增叹息，望云不见颜不开。","片片飞入溪山里，欲断复连情难已。","断时惆怅隔人间，连则风尘绾故里。","我后君生三十年，旧雨新雨感从前。","索题诗句辞未可，题不敢题思渺然。","相思何在渺难语，恍惚重桂堂前处。","父执父书两莫分，如闻所言吾语汝。","吁嗟乎，一卷中见雷陈交，画兮诗兮神不遥。","固知思泪同无尽，苕霅溪清弁山高。"]},{"t":"前诗题后谛观卷中先人印章为前时所未见者，再成七律写怀","f":"七言律诗","c":["重到吴兴八桂堂，词存七字认遗章。","搜穷沧海馀生晚，劫历红羊斯道伤。","要识石交崇世得，无愁云外落天香。","学吟一再羞貂续，手泽于今未敢忘。"]},{"t":"徐墨农见题菰城话雨图次卒章韵报之 其一","f":"七言绝句","c":["棘闱鏖战集名流，况复明湖烟景稠。","料峭西风偏扑我，不教同话六桥秋。"]},{"t":"徐墨农见题菰城话雨图次卒章韵报之 其二","f":"七言绝句","c":["共列门墙溯品流，惟君健笔粲花稠。","珠光长照苕溪月，不数人间桂子秋。"]},{"t":"沈稚斋见题话雨图次韵报之并酬春间招饮","f":"五言律诗","c":["桑田郊外绿，环堵乐陶然。","风雨良朋会，壶觞旧日缘。","图书资蕴酿，名利漫拘牵。","剪烛明窗小，池边石立拳。"]},{"t":"包子庄示其陈姬人花鸟画册索题 其一","f":"七言绝句","c":["蓝桥旧事记前因，花鸟图成笔底春。","惹得黄徐齐叹赏，偏教闺阁觅传人。"]},{"t":"包子庄示其陈姬人花鸟画册索题 其二","f":"七言绝句","c":["绝妙清才管仲姬，王孙书画并驱驰。","吴兴从此添佳话，墨竹当年不算奇。"]},{"t":"包子庄示其陈姬人花鸟画册索题 其三","f":"七言绝句","c":["写成宫韵李唐朝，曾说吴鸾降碧霄。","一样清贫资翰墨，何须仙眷羡文箫。"]},{"t":"包子庄示其陈姬人花鸟画册索题 其四","f":"七言绝句","c":["如此家居方是閒，小窗清课乐乡关。","朝云终古芳名在，遥指城南学士山。"]},{"t":"步岘山寻明霞墓址 其一","f":"七言绝句","c":["云山终古剩芳名，太守风流自有情。","遥指高楼新月上，最难樊榭近居城。"]},{"t":"步岘山寻明霞墓址 其二","f":"七言绝句","c":["曾记高斋话石蒲，残碑字迹认模糊。","沿山却种离离竹，一幅夫人临画图。"]},{"t":"寻吴烈女赛金墓","f":"七言律诗","c":["昔传弱女成名惨，今访孤茔春日曛。","一带湖山钟劲节，满林红紫散遗芬。","贞魂应傍明霞墓，奇气争飞金盖云。","华表森森双峙处，留题犹记鲤庭闻。"]},{"t":"冬至后偕衡甫至湖城北窑湾同儿殡地，口占哀之","f":"七言律诗","c":["独怜七岁儿生小，竟不归从何有乡。","魂魄原知无定处，形骸忍使落他方。","乱坟堆里情根淡，故里人逢地下长。","记取西泠来日路，碧湖南去自堂堂。"]},{"t":"咏草笠","f":"五言古诗","c":["早云燎太空，头戴笠子好。","惟笠质不同，农家费探讨。","葛藤编林泉，箨箬裁篁筱。","宜雨不宜晴，当夏用者少。","忆昔有黄冠，黄色服以草。","截去阶外蒲，诛就檐前茆。","每年三伏初，西畴有事早。","秧插荫随槐，畬锄香围稻。","倏忽透炎威，依旧苦乾燥。","曷若此笠成，迎凉经意造。","圆样月玲珑，遍覆云环绕。","薰风吹野田，珠露披清晓。","秀色映须眉，佳气明瞳瞭。","不愁红日红，耘耔忘杲杲。","隐见傍钓矶，高低逗池沼。","茅茨屋不除，莓苔榻无埽。","铺席芦苇参，裁扇蒲葵小。","天地一蓑翁，此物此时宝。","翩韆携屐来，伊谁是坡老。"]},{"t":"湖城重建三贤祠落成 其一","f":"七言律诗","c":["城西争说谢公塘，后有颜苏德泽长。","十卷诗吟留刺史，百年神定在桐乡。","云移镇霅楼头白，风送洼尊亭外凉。","旧日宫垣安可仰，斯民去思不能忘。"]},{"t":"湖城重建三贤祠落成 其二","f":"七言律诗","c":["重新祠宇祀三贤，鼎峙千秋香火缘。","广拓烟波江汇外，清留柤豆月湖边。","香升蘋藻神昭洁，乐奏承平礼告虔。","休息还欣楼近水，弁山苍霭扑窗前。"]},{"t":"拟郭璞游仙诗七首 其一","f":"五言古诗","c":["通都罗华阁，晓日照曈昽。","相与游侠儿，畋野跨青骢。","轮蹄交道路，车盖矫蛟龙。","一技未及展，暮景起天空。","弱质摧蒲柳，晚岁彫芙蓉。","此生多掩忽，孰能策始终。","还山采丹药，仙侣不时逢。"]},{"t":"拟郭璞游仙诗七首 其二","f":"五言古诗","c":["苍翠叠嶂开，澹营烟霞外。","飞瀑千丈馀，惊破银河挂。","有客悟此生，一举绝埃壒。","直上青云梯，隔断红尘界。","栋驾涧底松，竹鸣谷口籁。","伊谁效长生，逍遥慎不害。","道遇黄石公，相约瑶池会。"]},{"t":"拟郭璞游仙诗七首 其三","f":"五言古诗","c":["嘉荫成翠幄，幽兰含露滋。","草木喻至理，英华各及时。","晨光东南驾，流景西北驰。","达人解其微，安用长独悲。","鍊石开华顶，酌泉集清池。","同行王子乔，赠我九茎芝。","腾骧入云路，徘徊历四维。"]},{"t":"拟郭璞游仙诗七首 其四","f":"五言古诗","c":["有鹤冲霄去，不受樊笼束。","绛云自卷舒，争向岩阿逐。","自来登仙子，超心脱凡俗。","广成语执中，老子道不辱。","夕餐赤城霞，朝弄扶桑旭。","真气蓄满腔，何必效辟谷。"]},{"t":"拟郭璞游仙诗七首 其五","f":"五言古诗","c":["局促辕驹足，奔踶走且僵。","北风吹白云，忽与天路当。","明珠罗胸臆，珍错列上方。","远登太行山，近陟华子冈。","清音闻山水，仙露滴衣裳。"]},{"t":"拟郭璞游仙诗七首 其六","f":"五言古诗","c":["长城围万里，跂望何迢迢。","盘曲危鸟道，旷远顺鸿毛。","仰天向阊阖，风雨起崇朝。","烟霞合琉瓈，翡翠集兰苕。","添筹南极星，酌酒北斗杓。","秦娥奏新曲，麻姑引玉箫。","终古帝王家，簇拥列鸾轺。","愿从赤松子，长揖去市朝。"]},{"t":"拟郭璞游仙诗七首 其七","f":"五言古诗","c":["便娟侔朝日，颜华倏忽露。","岁月逝水流，羲和不能驻。","是非傥可明，得丧奚足顾。","天上森宝书，寸心托豪素。","相与拔俗人，云车誇远驭。","岛屿荣琪葩，无为叹迟暮。","寄语畋游者，我将从今去。"]},{"t":"棣笙以五十书怀诗索和次韵复之","f":"七言律诗","c":["笑他品格总平常，不向槐黄岁踏忙。","帜树词坛名早立，经横绛帐道难忘。","琴书十载儒官铎，泉石当年处士装。","前日知非今更进，敢将岁月老文场。"]},{"t":"春饮衡甫郡庠即席示杨宾于世丈","f":"七言律诗","c":["每过高斋俨若思，森森八桂错金枝。","最难孤子重游地，未隔髫龄趋对时。","门外桑田沧海易，室中诗酒故人知。","黉宫香火證缘会，僾见忾闻总不离。"]},{"t":"复偕杨施二广文饮程庠二雨堂柬主人孙子兰","f":"七言律诗","c":["相逢底是薄寒毡，醉倒鳣堂抱瓮眠。","一样知交今旧雨，卅年客梦去来缘。","无心新月窥书剑，有意春灯照管弦。","赢得连朝文字饮，同乡到此小游仙。"]},{"t":"至绍城留别宋白楼拔萃","f":"七言律诗","c":["十载名场任是非，塞翁得失早忘机。","何期蹇足驱驽驾，偶触新情学鹳飞。","搏虎恐贻冯妇笑，割鸡应惹武城讥。","浮家幸有苕溪在，为趁斜风细雨归。"]},{"t":"由杭放小舟至湖","f":"七言律诗","c":["武林山水过匆匆，春到苕溪一棹通。","村女桑前衫子绿，晴霞林外杏花红。","炉香成市人闻梵，渔网连波星落篷。","如此舟行浑不夜，布帆况有五更风。"]},{"t":"春暮宾于招饮安庙花园即席叠前归字韵","f":"七言律诗","c":["园林犹是昔人非，赖有知交补化机。","小会亲朋文字饮，偶联诗句水云飞。","登龙几辈推韩望，画虎连年合马讥。","屈指郎君新杏宴，群占吉兆折花归。"]},{"t":"题艺林少年松下听泉小影 其一","f":"七言绝句","c":["韶华容易水东流，赖有回澜枕石头。","同是溪山无尽意，苍苍松荫好贻谋。"]},{"t":"题艺林少年松下听泉小影 其二","f":"七言绝句","c":["图画于今卅六年，菰城重话隔桑田。","留题诸老风流在，一度披吟一惘然。"]},{"t":"夏四月重游云巢","f":"七言律诗","c":["一年已隔山居梦，万壑仍看云影归。","翠竹苍松围地脉，岩花涧水熟天机。","入林密处金承盖，当夏凉时风满衣。","悟彻神仙无滞境，傍舟白鹭逐波飞。"]},{"t":"汪苇塘教授以青州饥民歌见示用韵复之","f":"楚辞体","c":["青州土壤非饶沃，力田犹虞食不足。","连年灾歉报农夫，待哺哀鸿来满目。","工商士女散天涯，保抱提携日奔逐。","掬水茹草充客饥，雪邮风程争夜宿。","遣之不可留养难，愁杀流民图一幅。","所冀春回地脉和，延得残生饱饘粥。","何期今年年更荒，十亩麦田无一熟。","旱云飞火燎长空，水涸土乾严且酷。","遑论长夏插禾苗，膏雨连番滋百谷。","有时勉力乞食行，疲舌焦唇苦枵腹。","久饿不能出门户，坐望青天环而哭。","哭失声兮天不闻，惨此析骸与食肉。","非无拯穷一二家，斗米直许黄金斛。","前日救饥转自饥，道殣相望几往复。","吴兴教授恻中怀，发此哀情歌一曲。","劝拯斯民在富豪，率土普天谊相属。","我受读之怛然伤，旋溯时事额频蹙。","东南年岁虽不丰，螽飞犹未遍荼毒。","譬彼疮痍被四支，手足原不厚我独。","曷勿施济善躬行，指囷唱筹不囿俗。","且须剔除蠹吏奸，莫开囊橐逞私欲。","惠及生民非沽名，行仁有术望人牧。","君不见当年梁惠霸业羞，犹能自移老稚河内粟。"]},{"t":"薛心农鹾尹盛暑过访偕张西章、钮小琴与叔兄放棹碧浪湖纳凉","f":"七言古诗","c":["苕溪南绕城一曲，注为碧湖众流蓄。","许我重游两度春，爱泛此湖日不足。","何幸客自西湖来，品题名胜此邦熟。","杖履追随不自由，从游饱恣平生福。","兴高放棹湖之心，纳凉时节刚三伏。","酒尊开时湖面宽，十里镜平豁双目。","层峦滴翠快当窗，远塔临流涌浮玉。","南度薰风阵阵和，吹皱波纹净雾縠。","酒阑得句兴更豪，卧影空中漾众绿。","无何红日射西岩，金盖道场峰奇卓。","巢云争出俟归云，崖上无心自相逐。","相与眺望岘山头，世界清凉非我独。","有亭翼然洼尊洼，呼吸湖光神往复。","古来多少贤达才，饮者留名良不俗。","妙墨雅推颜鲁公，爱山艳说苏玉局。","不愁中热心镇瓜，恍入广寒尘去斛。","高歌远答打鱼舟，唱破琉璃图一幅。"]},{"t":"七夕与宾于诸君联吟分得玉字","f":"七言古诗","c":["今年小暑雷惊屋，阴曀天时连三伏。","乍夜西风已报秋，湿云犹作黄梅熟。","吾来浮家苕霅间，七夕重逢私心祝。","祝他节序调暑寒，不愁困苦餐蔬菽。","比邻瓜果列几筵，道是乞巧求所欲。","偶喜庭结蛛网丝，复讶针度月钩曲。","得意家家拍手欢，吉兆胜比灯花卜。","吾侪自古拙谋生，不学儿女斗红绿。","岂甘愚戆事罔闻，省识昊苍厚我独。","嗟哉人间多巧矣，名缰利薮逞驰逐。","戕伐性灵公输羞，雕镂肺腑成风斲。","非无宽厚钟斯人，丑类鲜不笑讪腹。","何如赚此智巧心，无碍波流走尘俗。","讷无语言钳齿唇，顿从柔媚更面目。","客曰此心非外求，求得舍失议精卓。","我望银河四悄然，当檐清浅露华沐。","牛女双星岁一逢，乘运转移无穷朔。","初无妙巧寓太空，怎惹离合閒情触。","悟尽此理漏未残，窗虚涵翠鸣筱竹。","独倚阑干风拂裳，何处声声笛横玉。"]},{"t":"次韵送冯太守由湖之杭 其一","f":"七言律诗","c":["九贤祠外驻车铃，话别洼尊旧有亭。","谢老功名总墅屐，苏公诗酒著笙瓶。","泽周苕霅歌黎庶，目极樯帆接紫冥。","三度攀辕无计住，好山一路送篷青。"]},{"t":"次韵送冯太守由湖之杭 其二","f":"七言律诗","c":["群居广厦说鸣铃，问字迟来墨妙亭。","滥列吹竽筹借箸，特惭汲绠井羸瓶。","依韩已慰诗书愿，怀李无愁云树冥。","最是离情图不尽，西湖杨柳六桥青。"]},{"t":"再次前韵寄冯太守 其一","f":"七言律诗","c":["莫问系铃人解铃，清刚直上自亭亭。","何虞谤毁销金鼎，不藉文章翻水瓶。","潮落钱江帆影净，云归鹫岭柳烟冥。","遥知悟彻閒中趣，门外吴山别样青。"]},{"t":"再次前韵寄冯太守 其二","f":"七言律诗","c":["生憎掩耳盗金铃，磊落乾坤立草亭。","习苦此时勤运甓，浇愁有酒屡倾瓶。","淘沙逐浪鸥波阔，残月鸣蛩秋色冥。","无计蕉窗人夜读，秋凉如水一灯青。"]},{"t":"饮城南会馆即事口占 其一","f":"七言绝句","c":["亭对洼尊醉一尊，隔湖山色绿侵门。","閒来莫作寻常饮，桑梓与斯大道存。"]},{"t":"饮城南会馆即事口占 其二","f":"七言绝句","c":["盂兰盆散露华秋，魂梦归来不可求。","何幸生离忘死别，满江芦荻护扁舟。"]},{"t":"饮城南会馆即事口占 其三","f":"七言绝句","c":["城北窑湾多墓田，凄风馁鬼哭年年。","最愁野外人踪少，荒冢昏黄狐兔穿。"]},{"t":"饮城南会馆即事口占 其四","f":"七言绝句","c":["旅衬如何策万全，墙卑室浅过凄然。","愿今拓地添梁屋，风雨无愁破一椽。"]},{"t":"棣笙学博赋五言五十韵见赠次韵成七言答之","f":"七言古诗","c":["频年学钓烟波里，苕霅交流清顾视。","浮家何幸遇志和，必恭敬之桑与梓。","梓乡人乐聚他乡，十载光阴铎秉此。","高才陋封管城侯，棘闱抛却毛锥子。","风拂词曹皋座春，人从雪夜程门侍。","讲道常欣堂开鳣，寄书时得河烹鲤。","雅怀乍发志为舒，硕德自崇义日徙。","有时下笔思涌泉，卓识自然成信史。","有时酌酒朋盍簪，倾瓶快不占羸耻。","桃李花开年复年，种下门前无数士。","况有哲嗣继家声，过庭趋对惜分晷。","积学得悟言屡中，循分安居心无悝。","冢君筮仕江之南，喜闻几折谢屐齿。","良吏行当眼转青，儒生不惯官佩紫。","何以昊天不永龄，泰运方长忽遭否。","君当归棹西子湖，死别生离悲论理。","四方吊者靡不嗟，渴决此疑圣人俟。","明珠岂随燕石遗，衰草竟与瑶芝委。","客言彭殇本不齐，继而起者在群季。","鸾旗鲁宫奏少年，骏足长坂期千里。","端由大椿茂本根，散为金枝与玉蕊。","不然蔗境怡老颜，克树阴德长鸣耳。","君之孝友早知名，垂白思慕赤子比。","痛定风木泪不乾，要识源头思饮水。","天性还同金石贞，藏碑竞拓硬黄纸。","辨别真赝理析毫，指画同异刀异剞。","不才稍得识鱼虫，望洋叹惭效臂使。","读钳口舌石鼓文，书测山渊古周脾。","博物考时力之馀，本末轻重类堪纪。","二铭堂前心独铭，行文忠信四具美。","豹窥一斑踪未精，较诸肉食尚非鄙。","吴兴我已三度来，漫道从游今晚矣。","慨陈谠论沙披金，宝卫微言米扬秕。","时乱难藏射雕弓，年荒欲展屠龙技。","策杖峰头秋气高，载月湖心乐事记。","能以吾学辅此游，知白守黑不中止。","曷为许我大器成，不患身世隐朝市。","又尝期我蓬山登，奋发韶华励壮思。","燕赵悲歌非吾曹，谁呼屠狗出而仕。","殷勤慰诲五百言，此道此情不逾咫。","勉诵佳章浣露薇，配以澧兰并沅芷。","会须心性拨泥灰，古井秋风波竞起。","戴笠观天敝大空，披荆陟壑险攀跂。","恍若暗室明一灯，悄然危惧翻然喜。","明朝当卸钓鱼蓑，钓尽名誉破波靡。","崎岖总得达康庄，大道原来平如砥。","热肠仍须问冷官，外此知者有谁是。","姚江老友施与杨，世交公子赋麟趾。"]},{"t":"宾于以诗寄赠用韵复之","f":"古风","c":["孟春之月快衔杯，孟秋之月期不来。","春秋佳日难兼擅，忝联诗社末座陪。","巧乞七夕不可得，为君送巧语奇哉。","新旧閒情齐发泄，从头那厌诵百回。","矫俗本非吾辈志，岂为愤激滋群猜。","天君泰然心无著，大智如愚日不违。","我于弱冠钦道貌，家承世好交陈雷。","五十年前西园集，画本诗情大道该。","不图纵迹寻后人，苕溪诗酒又追随。","天许此缘结此际，儒生至此复何为。","抒写性情荡邪秽，登临山水廓衷怀。","饥来赖有撑肠字，世世生涯清莫阶。","得失功名无宠辱，何须拔剑歌我哀。","谢君法巽言兼至，心颜开后沁诗脾。","蓬山捷径碍芳躅，曲木道傍合散材。","逢伯乐，说郭隗。","老马不知身在枥，几多慰诲费溯洄。","秋来老圃容色澹，不妨羯鼓效诗催。","馀不溪头好夜月，得句欲与凉露飞。"]},{"t":"八月二十二日偕汪苇丈、宾于、衡甫、子兰、西章、少帆诸学博游法华山","f":"七言古诗","c":["石斗山头弁山麓，年年香市誇吴俗。","春日融和车马喧，甘露杨枝人乞福。","传说齐女道绩贤，持诵法华二十年。","青山埋骨著灵秀，于清净龛涌青莲。","莲开不比昙花见，世界大千驻宫殿。","绣佛名场次第开，相登觉路驾彼岸。","故逞诡奇不坏身，巾帼须眉自有人。","金粉六朝销寂尽，剩有贞魂励俗尘。","尘世韶华日以远，腾语支离愈虚诞。","不信名山坚道心，空佞左道息残喘。","我游偏在秋末老，白蘋红蓼诗大好。","风鸣翠竹阴亭亭，目接洪涛惊浩浩。","摄衣悬崖瞰太湖，七十二峰相招呼。","洞庭半规隐林表，当有人家住菰蒲。","须臾雁落岸帻后，回望城烟大如斗。","涧流且莫分浊清，觞咏犹欣集良友。","友说班荆故旧欢，尽飞逸兴度烟鬟。","洞伏黄龙迷云雾，经听白鹊神往还。","为题姓氏苔扫石，转恐山灵耻缘饰。","载酒道场似客秋，南山之南北山北。"]},{"t":"宗太守招饮爱山台出图卷索题久未报也，是秋八月移守宁波为次东坡道场山诗韵成三首 其一","f":"七言古诗","c":["东坡去矣空林麓，终古声名留厓谷。","不逢汪丞说爱山，谁向高台策蹇足。","且历兵乱日漫漫，鬼火昏黄蛇蝎盘。","蒙棘丛生牵萝薜，龙鳞老化问松湍。","天爱苍生斯人出，治周期月登衽席。","湖边万顷桑绿地，浓接棠阴齐栽植。","无何黛色压千鬟，笑对城南有无间。","台成不日民通政，八百年后重看山。","山灵爽气迎平旦，下雨崇朝黑天半。","赋就长歌挥兔毫，惊披珠玉临风叹。"]},{"t":"宗太守招饮爱山台出图卷索题久未报也，是秋八月移守宁波为次东坡道场山诗韵成三首 其二","f":"七言古诗","c":["六载重来步层麓，怀人春雨苦空谷。","歧途日暮将安之，踯躅危磴碍进足。","何期严濑水淼漫，忽聚萍梗路曲盘。","喜约儿童迎竹马，快沾膏泽聆鸣湍。","坐看云岫无心出，当夏凉风铺琴席。","红亭白塔开旧颜，翠竹苍松表净植。","尽多风景付云鬟，罗列明窗大几间。","犹幸良朋结良会，爱山过客同说山。","爱山爱士评月旦，勤学岂废修途半。","经济无非道德腴，我熟闻之望洋叹。"]},{"t":"宗太守招饮爱山台出图卷索题久未报也，是秋八月移守宁波为次东坡道场山诗韵成三首 其三","f":"七言古诗","c":["霎时轻散云飞麓，蓼红蘋白明涧谷。","无计攀留天际船，门外征尘起马足。","碧湖此去烟窅漫，去思直偕鸟道盘。","前后循声报最来，归市民心壑奔湍。","况复四明山奇出，东渡大江稳帆席。","海滨蜑户饶鱼盐，潮落农田勤耕植。","回头应不忘仙鬟，诗思清于苕霅间。","林鲍再官箸金石，颜苏自古寿湖山。","骊歌唱彻鸡声旦，容易西风秋刚半。","馀泽当流贺鉴湖，鼓舞来朝归与叹。"]},{"t":"饮湖郡庠即旧时重桂堂也即席赠汪教授","f":"七言律诗","c":["韶华廿载逝如斯，杯酒兴怀今昔时。","堂取君家丛桂义，编留先集校官诗。","依然文字朋僚饮，难得丹铅几席随。","开到白莲人未倦，当年茂叔不吾欺。"]},{"t":"宾于以游法华诗索和复次原韵纪游","f":"五言古诗","c":["佳日当春秋，酒兵逞潜伏。","来自馀不溪，劝我双瑞竹。","摩空尽廓廖，树地誇敏速。","下笔涌泉思，寻胜追风足。","高会下菰城，良朋快遐瞩。","遥指法华山，秀色朗心目。","太湖吞万顷，渺泛太仓粟。","乍系蓼岸舟，齐跻石斗谷。","门前柳荫深，涧底刍薪束。","琼宫木犀香，天半飘馀馥。","拾级兴愈浓，枕石云时簇。","何人诵贝经，万卷齐梁录。","欲结清净缘，岁月流不复。","泉下不坏身，人拜道旁肃。","吐莲随处春，逐利此身促。","相与陟山头，山在弁山麓。","湖近植菰蒲，沙平搏雁鹜。","苍翠浮洞庭，半面神接续。","傍水几人家，安居知聚族。","伟哉东坡游，言语妙歌曲。","全湖易酩酊，设想超凡俗。","翩翩于思君，追步苏玉局。","故乡好湖山，不必渴思蜀。","同游载酒归，此理胸烂熟。"]},{"t":"题孟嘉落帽图","f":"七言古诗","c":["彼何人哉图之右，缓带轻装昂其首。","首著乌纱不可寻，飘空风捲空诸有。","传说晋代孟参军，龙山游眺际重九。","登高作赋大夫能，脱略公卿恕僚友。","山高不道秋飙高，蓦地吹来尘扑斗。","发稀自笑不胜簪，帽落峰头蓬飘帚。","卒临若不集欢嗔，科头兀立独良久。","须知此老腹有诗，未惯侯门供奔走。","濡首何妨墨沈毫，洒巾任尔愁浇酒。","层峦环列猿鹤窥，万木声清鼍龙吼。","放眼青山红树间，固无纤俗掣其肘。","薄宦危机何地无，褫冠弹冠数某某。","天以落帽全我真，画图千百十年后。","偶将豪气说登临，桓大司马其知否。"]},{"t":"借书柬衡甫","f":"五言古诗","c":["针线压女红，斧锥资匠斲。","器利善事先，至理通乎学。","讲学在群书，梯航与辘轴。","舍此旧迹寻，歧途迷踯躅。","嗟我少失学，父书未能读。","缥缃飘劫灰，湖海走尘俗。","几处拥书城，心羡涎流角。","饷贫慨以慷，驱饥常缚束。","堪叹楮叶成，已尽易饘粥。","异书识纤微，天花眩眼目。","牛充梁栋高，蠡测山渊伏。","一知半解时，岁月逾匆促。","三来苕霅间，游忆髫龄熟。","桂堂许重登，天香犹馥郁。","施子真儒官，今雨旧雨续。","得钱便买书，插架签盈屋。","问难并析疑，取求快所欲。","帘燕静不嗔，河鼠饮满腹。","回首二十年，趋庭训闻独。","阶砌每徘徊，梦魂应来复。","袖卷晚归来，少年补未足。","荒草辟山蹊，暗室明椽烛。","故地逢故交，天与孤儿福。"]},{"t":"宾于复题话雨图有“朝糊口、夕埋头”之句，效体谢之","f":"楚辞体","c":["忆昔董生之慈孝兮，昌黎作歌而欷歔。","昼出耕兮夜读书。","嗟我生之玩愒兮，常虚掷乎居诸。","历少壮而无建白兮，值世路其崎岖。","愿游处以木石兮，乃饥寒之我驱。","岂磷缁失其坚白兮，非前日之真吾。","走四方而抱质兮，遇合悉听诸当途。","得馀暇于漏夜兮，藉笔墨以自娱。","扑俗尘之斗斛兮，完本性于须臾。","非课功而继晷兮，聊晤对于吾徒。","萱室愁夫衰白兮，寂寞对夫妻孥。","何瑶章之叠下兮，忘名实之相须。","敢执灯而裁答兮，谢故人之虚誉。"]},{"t":"拟禽言 其一","f":"七言律诗","c":["麦熟麦熟麦未熟，老农已无隔年谷。","何堪赤日如火烧，十日不雨环而哭。","哭如雨点雨不飞，官赋来朝复催促。","刈麦输赋犹未足，谁能取得心头肉。"]},{"t":"拟禽言 其二","f":"古风","c":["割麦插禾，间日无多。","乃旱魃之为虐，雨未见其滂沱。","一旬不雨老农哭，兼旬不雨泪如波。","昨夜月离毕，明朝雨不过。","明日复明日，日对枯田奈若何。"]},{"t":"拟禽言 其一","f":"古风","c":["泥滑滑，泥滑滑。","昨朝得雨今未歇，洒遍东郊与西陌。","儿童拍手呼，父老双脚赤。","高田水满不用车，低田水浅才下尺。","既插禾，先割麦。"]},{"t":"拟禽言 其二","f":"古风","c":["郭公郭公，天雨濛濛。","忽倾盆而作势，芳田沾足慰老农。","农妇提馌饷，农夫饮一钟。","向来几费耕耘苦，不道甘霖及候逢。","割麦麦黄熟，插禾禾青葱。","归来负耜乐休息，尚有拍手欢歌牧牛童。"]},{"t":"孙君瘦梅为女芳祖述小螺盦病榻忆语题词 其一","f":"五言律诗","c":["惆怅昙花见，尘寰十九春。","青莲惊旧梦，紫玉悟前身。","绝笔秦娥曲，招魂洛浦神。","绿杨灯影外，閒煞白头人。"]},{"t":"孙君瘦梅为女芳祖述小螺盦病榻忆语题词 其二","f":"五言律诗","c":["小螺庵寂寞，犹作返生香。","麝墨遗盈箧，□书压满床。","楼头空彩凤，天上召寒簧。","收拾高堂泪，缠绵语忆长。"]},{"t":"书晋豫饥状寄当事者","f":"五言古诗","c":["频年岁大饥，朔北民缭乱。","山东复山西，旱魃赤焦遍。","三年天不雨，禾麦枯高岸。","升斗比琼珠，饥饿无贵贱。","枵腹走东西，鹄形黝色面。","勉登太行山，底柱王屋间。","汴梁古帝都，同兴哀鸿叹。","僵卧不可行，道旁苦相见。","岂无王孙怜，谁储漂母饭。","惨闻人相食，未毙忍吞咽。","一脔易一钱，直竟逊刍豢。","甚矣此际情，不啻析骸爨。","长官廉得之，章奏通名殿。","诏书振困穷，仓粟诘朝散。","已输万帑金，未获餐饱顿。","四海恻然伤，豪富为激劝。","醵金未及千，道殣死逾半。","纵有延喘息，畴克策昼旦。","客从东南来，微理姑擘判。","移粟与移民，大道原兼擅。","曷不送灾黎，分留列郡县。","十家养一人，一郡四百万。","数却合流民，力不劳神算。","且谋挟纩棉，世界和冰炭。","冬至喜阳生，生机在顾盼。","熟聆道路言，愿作刍荛献。","舍斯不亟图，衰草恐滋蔓。","霜雪正满天，慈云望一片。"]},{"t":"重九偕衡甫少帆三游云巢","f":"七言律诗","c":["满郭霜林唤野舲，芦花深处偶然停。","无边木叶随时落，不断山光为我青。","佳节何妨人淡菊，仙寰长许鸟听经。","遨游三度忘知止，愿老前溪止止亭。"]},{"t":"霜螯用欧阳子咏车螯诗韵","f":"七言古诗","c":["西风乍起香稻熟，临流蟹簖好生涯。","霜凝连朝双螯足，佐酒立办付咄嗟。","草泥郭索占鸿爪，筐筥剖擘比寒瓜。","厥物表里澄黑白，经秋豪甲饱精华。","凛凛寒威真味入，霏霏玉屑琼浆加。","姜桂有时除辣性，和调饪谱理无差。","妒杀枫江老渔户，烹鲜炉火饫家家。","匕箸搔爬夺专席，肌肤细腻胜瓠巴。","我闻江淮产佳种，欧阳螯食别名车。","依然清脆适口腹，未必肃杀厉齿牙。","天生公子秉秋气，拳丁披甲食鱼虾。","如仗大钺戮鳞介，俨拥神剑捐莫邪。","乌啼月落队行出，潮迎江头风景誇。","不困篱菊影形瘦，绝胜岭梅冻欲花。","纵有八跪清斫雪，谁作波势起吧呀。","盾甲自卫终须解，荻芦夜战静不哗。","右手持来发豪兴，当年吏部举止遐。","会友高歌醉夜半，冷图茅屋聚团沙。"]},{"t":"雪霁偕邬梅仙登奎光阁柬棣笙","f":"五言古诗","c":["乾坤妙炉橐，霏雪满林壑。","城居人欲僵，冻蟹行郭索。","十日忽快晴，忙煞登临屩。","远眺集同心，拾级奎光阁。","奎光与雪光，初望色交错。","久倚危栏肱，□住转蓬脚。","窗罗列乱峰，峰峰成玉削。","对我峙道场，塔势出若跃。","高手尽白描，文章卓南郭。","北临苍卞苍，遥接气宏绰。","青眼纵不逢，白首俨相约。","朔风刺面来，语语答檐铎。","山灵前致词，色相归无著。","惜不携素琴，松风和穆若。","同游知音者，襟期共澹泊。","太古本无弦，耻作閒寄托。","呵毫质主人，官冷未寂寞。","烹茶雪一瓯，棋声当窗落。"]},{"t":"雪后次韵答棣笙","f":"七言律诗","c":["融雪朝朝讶雨晴，看山著屐快閒行。","登高偶效邯郸步，掷句重逢金石声。","愧我散材深谷老，多君雅望顺鸿轻。","袖中诗本新携去，琼玉盈庭月又横。"]},{"t":"棣笙以叠韵来报以二首 其一","f":"七言律诗","c":["茅檐也是慰新晴，暴背赢他衣锦行。","作字烘窗腾墨气，砺寒唾地集冰声。","庭蕉雪折心抽尽，砌竹风敲竿立轻。","何幸知心佳句续，晚来酌酒看参横。"]},{"t":"棣笙以叠韵来报以二首 其二","f":"七言律诗","c":["昨宵既雪午重晴，造化无心云自行。","忙到诗人分险韵，时来舟子打冰声。","身如野鹤烟林瘦，意逐沙鸥天地轻。","最是奇穷得奇句，万山尽处大河横。"]},{"t":"上元前夕叠韵复棣笙 其一","f":"七言律诗","c":["梓里棠封溯昔贤，披寻卷牍写联翩。","时形梦入羹墙里，不觉春回梅柳边。","天道循环寒代暑，他乡羁旅日穷年。","岁除懒把新诗祭，客到犹欣醉欲眠。"]},{"t":"上元前夕叠韵复棣笙 其二","f":"七言律诗","c":["茅庐赏雪集群贤，小住神仙气运翩。","乐事偏饶荒径外，春游待约太湖边。","酸咸世味周寒士，灯火街头学少年。","惆怅连朝风雨紧，宵深清冷不成眠。"]},{"t":"次韵复宾于元日却寄诗","f":"七言律诗","c":["西园雅集溯当年，得半庄谈月上弦。","金石至交文字契，神仙高会主宾贤。","不期易世雷陈结，好把新情苕霅传。","科弟循良欣所愿，谁嫌閒散郑君虔。"]},{"t":"二月六日偕薛子白、胡馨甫、高共甫乘兴泛西湖，谒蒋公祠，饮湖畔，夜饮子白家，纪事柬心农丈","f":"七言古诗","c":["人与西湖两别离，经年不见思蕴结。","忽来湖滨晤故人，杭州胡高通州薛。","放棹湖心薄暮天，湖光人影杂明灭。","陡起湖风湖水高，吹皱波纹漾细密。","涌出云峰无数青，千朵叠成石凹凸。","指是新祠祀蒋公，孤山如幕天然设。","图画战功摩峭厓，四壁英姿动毫发。","白苏政绩寄烟鬟，韩岳精神摇岩穴。","纵使湖泉冷若斯，难抹烈士热心血。","我爱古人不薄今，柏堂竹阁齐峻洁。","煮茗一瓯酒一樽，徜徉其间情怡悦。","隔岸南屏报晚钟，声声烟际何清越。","酒阑犹欣酒未阑，饮寻文字迎纤月。","薛家老凤主风骚，夜话高斋席珍列。","入林出山心澄源，说经讲艺指绕铁。","相与印證湖上游，人去人来妙出没。","偶然小聚亦神仙，快偿此愿深饥渴。"]},{"t":"千金墟怀古","f":"古风","c":["吴兴城南四十里，故墟一片迷指视。","道旁樵牧识旧名，库置千金良有以。","我闻濞也生汉家，从破鲸军功昭史。","特王之邦崇藩封，五十三城俨赐履。","章郡铜山天下奇，产成金石美无此。","罗致亡命盗得之，镕铸泉布中心喜。","点金何待仗神功，鍊金遽能收众技。","铜岘山前铜臭升，薰心利欲实骄侈。","称老不朝年复年，故薄赋敛众臂使。","但有财富甲东南，不识长安有天子。","偶触小忿七国谋，朝错有头难雪耻。","汉使旋以利绐吴，此身竟至东越死。","嗟哉沛公拊背言，后五十年岂忘耳。","空馀渡口郁金波，来去苕霅二流水。","天地爱宝自呈材，贵宝善者实终始。","黄金白璧何地无，赤水蓝田未足恃。","再过成墟狐兔眠，遑论府库尽富美。","君不见吴王夫差姑苏台，金碧当时先已矣。"]},{"t":"顾渚采茶歌 其一","f":"七言绝句","c":["阿侬生小住田家，不惯采花惯采茶。","犹喜名山邻顾渚，归来半里路嫌赊。"]},{"t":"顾渚采茶歌 其二","f":"七言绝句","c":["同侪约出古鄣城，趁此春和雨乍晴。","过尽山头全不管，茶歌一路听分明。"]},{"t":"顾渚采茶歌 其三","f":"七言绝句","c":["胜他齿白色鲜妍，却值良辰谷雨前。","生怕清香输越宿，忙行馀不一溪烟。"]},{"t":"顾渚采茶歌 其四","f":"七言绝句","c":["当年人说石蒲斋，一卷茶笺风味佳。","新斗旗枪誇境内，白岩罗嶰早安排。"]},{"t":"清明客祭口占 其一","f":"七言律诗","c":["失怙于今十八年，故乡回首泪凄然。","全家衣食驱毛颖，六度清明迷柳烟。","卜宅偏为霜雪难，连床空结雨风缘。","新成高阁崇乡祀，苕霅之间僾忾传。"]},{"t":"清明客祭口占 其二","f":"七言律诗","c":["兼痛埙吹化却尘，黄粱小梦十逢春。","已多宿草埋新冢，孰继苏门话旧人。","遗恨尽多随处有，旅怀敢向屈时伸。","但期灵爽长呵护，次第贻谋后此身。"]},{"t":"宾于仿香山劝酒诗体，以“何处吟诗好”，“还是吟诗好”发端各成七首见示，效之 其一","f":"五言律诗","c":["何处吟诗好，诗吟春水船。","一篙新涨碧，满眼野花然。","不藉推移力，长游自在天。","此时无所咏，孤负是青年。"]},{"t":"宾于仿香山劝酒诗体，以“何处吟诗好”，“还是吟诗好”发端各成七首见示，效之 其二","f":"五言律诗","c":["何处吟诗好，诗吟万木山。","雷声送雨过，云气逐人还。","松老游踪健，泉清俗虑删。","此时无所咏，褦襶笑尘寰。"]},{"t":"宾于仿香山劝酒诗体，以“何处吟诗好”，“还是吟诗好”发端各成七首见示，效之 其三","f":"五言律诗","c":["何处吟诗好，诗吟黄叶村。","停车留晚景，题句艳朝暾。","鸡犬闻邻舍，桑麻话小园。","此时无所咏，奔走苦侯门。"]},{"t":"宾于仿香山劝酒诗体，以“何处吟诗好”，“还是吟诗好”发端各成七首见示，效之 其四","f":"五言律诗","c":["何处吟诗好，诗吟在灞桥。","探梅驴背稳，踏雪客思遥。","画意留空际，閒情总白描。","此时无所咏，中热几时消。"]},{"t":"宾于仿香山劝酒诗体，以“何处吟诗好”，“还是吟诗好”发端各成七首见示，效之 其五","f":"五言律诗","c":["何处吟诗好，诗吟红旭楼。","潮迎东海阔，山涌大江流。","百尺雄心上，千家晓梦稠。","此时无所咏，迟暮复何求。"]},{"t":"宾于仿香山劝酒诗体，以“何处吟诗好”，“还是吟诗好”发端各成七首见示，效之 其六","f":"五言律诗","c":["何处吟诗好，诗吟皓月窗。","半阶花影弄，三里寺钟撞。","红袖香添乍，青灯味少双。","此时无所咏，蟾魄冷空江。"]},{"t":"宾于仿香山劝酒诗体，以“何处吟诗好”，“还是吟诗好”发端各成七首见示，效之 其七","f":"五言律诗","c":["何处吟诗好，诗吟卖酒家。","齐来浇礧磈，独醒惜芳华。","珍重驱愁帚，殷勤解语花。","此时无所咏，白日又西斜。"]},{"t":"宾于仿香山劝酒诗体，以“何处吟诗好”，“还是吟诗好”发端各成七首见示，效之 其八","f":"五言律诗","c":["还是吟诗好，吟诗可破愁。","别离千里客，患难一扁舟。","点染江淹赋，登临庾信楼。","何如歌咏乐，岁月独优游。"]},{"t":"宾于仿香山劝酒诗体，以“何处吟诗好”，“还是吟诗好”发端各成七首见示，效之 其九","f":"五言律诗","c":["还是吟诗好，吟诗可养真。","颐情鱼戏藻，适性鸟鸣春。","心气和平候，山林蕴藉人。","何如歌咏乐，妙理尽陶钧。"]},{"t":"宾于仿香山劝酒诗体，以“何处吟诗好”，“还是吟诗好”发端各成七首见示，效之 其十","f":"五言律诗","c":["还是吟诗好，吟诗可遣怀。","美人怜绝代，壮士慰天涯。","花木栽深院，琴书伴小斋。","何如歌咏乐，笔砚早安排。"]},{"t":"宾于仿香山劝酒诗体，以“何处吟诗好”，“还是吟诗好”发端各成七首见示，效之 其十一","f":"五言律诗","c":["还是吟诗好，吟诗可尽欢。","游仙天路近，醉酒玉杯宽。","不数旗亭唱，常赢古调弹。","何如歌咏乐，花月正团栾。"]},{"t":"宾于仿香山劝酒诗体，以“何处吟诗好”，“还是吟诗好”发端各成七首见示，效之 其十二","f":"五言律诗","c":["还是吟诗好，吟诗可禦烦。","芝兰閒著意，桃李妙无言。","心洗观群动，神清息众喧。","何如歌咏乐，悟彻散泉源。"]},{"t":"宾于仿香山劝酒诗体，以“何处吟诗好”，“还是吟诗好”发端各成七首见示，效之 其十三","f":"五言律诗","c":["还是吟诗好，吟诗可送穷。","磨砻存骨傲，研鍊琢词工。","稽阮歧途哭，箪瓢陋巷通。","何如歌咏乐，贫食乐融融。"]},{"t":"宾于仿香山劝酒诗体，以“何处吟诗好”，“还是吟诗好”发端各成七首见示，效之 其十四","f":"五言律诗","c":["还是吟诗好，吟诗可解嘲。","倒绷儿学养，破屋鸟呼巢。","鼠璞羞真品，林泉结旧交。","何如歌咏乐，谢客费推敲。"]},{"t":"春分日艺林招饮鱼计亭，即席书怀并柬其从子幼幸","f":"七言古诗","c":["菰城西北有高亭，名贤觞咏入丹青。","郑氏园林属陈氏，当年轶事闻趋庭。","何期劫后来苕上，图随亭宇归秘藏。","求古舍前求古人，败瓦断碑不可访。","能读父书成一家，扶花居士惯栽花。","偶访亭址补花石，缭以曲槛尽幽遐。","况有季父宝先泽，珍袭遗编胜拱璧。","时来载酒话竹林，旧交大半白头客。","我居座末最少年，花开复值春分天。","平分春色不分愁，满院风光扑眼前。","吴兴山水称清远，卷石堆成愈委宛。","尺幅千里幻烟霞，啸傲无端春昼短。","红杏枝头红日西，帘檐花影落杯底。","摩挲文字黯金石，苔纹钗股望不齐。","席多儒官敦儒素，把酒不谈当世务。","鱼计鱼计计在鱼，濠濮同观好风度。","我欲从之酒再斟，此饮此亭无古今。","竹垞铁桥嘉湖著，后此谁知醉后心。","清清一鉴方塘水，照见酡颜清莫比。","明波曾识古须眉，问彼无言芳桃李。"]},{"t":"宾于将返武康以所携笋蔬麦餈见赠赋此送之 其一","f":"七言绝句","c":["最难细雨杏花天，酿笋人来春水船。","道是儒官真耐冷，袖笼馀不一溪烟。"]},{"t":"宾于将返武康以所携笋蔬麦餈见赠赋此送之 其二","f":"七言绝句","c":["佐他肴馔总清华，麦黍搏成饼饵誇。","温语殷勤滋我愧，循陔孝养到寒家。"]},{"t":"宾于将返武康以所携笋蔬麦餈见赠赋此送之 其三","f":"七言绝句","c":["底是匆匆买棹回，鳣堂桃李可齐开。","阶前尤喜芝兰茁，毕竟心田培植来。"]},{"t":"宾于将返武康以所携笋蔬麦餈见赠赋此送之 其四","f":"七言绝句","c":["十日平原醉若泥，新添佳话到前溪。","云巢山色乌程酒，准待来年再品题。"]},{"t":"师竹由东阳携石洞贻芳卷过访，偕饮酒楼，转至戴海门笠青家，夜归书赠师竹 其一","f":"五言古诗","c":["春雨暝连朝，客来忽心喜。","问客来何方，云从云洞里。","为我说白云，年来妙无比。"]},{"t":"师竹由东阳携石洞贻芳卷过访，偕饮酒楼，转至戴海门笠青家，夜归书赠师竹 其二","f":"五言古诗","c":["聚散皆天机，归出任行止。","旧日洞中仙，今日风尘子。","无术洗此心，沽酒不能已。"]},{"t":"师竹由东阳携石洞贻芳卷过访，偕饮酒楼，转至戴海门笠青家，夜归书赠师竹 其三","f":"五言古诗","c":["再酌乌程酿，偕来卖酒家。","薄暮忘宾主，雨丝风片加。","携屐访故交，大戴小戴誇。","盘杯已狼藉，鸡犬息喧哗。","官冷肠偏热，红烛灿生花。"]},{"t":"师竹由东阳携石洞贻芳卷过访，偕饮酒楼，转至戴海门笠青家，夜归书赠师竹 其四","f":"楚辞体","c":["灯灺懒不归，归来人睡足。","悄然见卷书，清气扑眉目。","展读消酡颜，郭洞逢石屋。","贻芳终古芳，紫阳花不独。","我本林泉癖，五载梦魂熟。","客兮明日行，尔音无金玉。"]},{"t":"子方宰邢台为兖豫通衢，近又奇荒，诗以代柬 其一","f":"五言律诗","c":["不极宰官苦，谁知书味真。","五年兴水利，四野活饥民。","清白閒中操，光明鍊后身。","鸣琴春雨足，气象得翻新。"]},{"t":"子方宰邢台为兖豫通衢，近又奇荒，诗以代柬 其二","f":"五言律诗","c":["君才非百里，百里可成功。","人命黔黎托，康衢兖豫通。","纲常真血性，儒素旧家风。","远道循声报，衡门听倚蓬。"]},{"t":"咏新萍四首 其一","f":"七言律诗","c":["年年飞絮化浮萍，绾起閒愁人未经。","省识风光重入梦，那堪聚散已忘形。","轻随暖涨篙添晕，酿逐春江草逊青。","依样欣欣新绿逗，东皇底是付飘零。"]},{"t":"咏新萍四首 其二","f":"七言律诗","c":["飘蓬生性未曾知，敢说来朝绿满池。","槛外柔姿增绰约，波心弱态认参差。","描成春色三分候，点破诗魂一半时。","转恐离亭留不住，须臾轻散到天涯。"]},{"t":"咏新萍四首 其三","f":"七言律诗","c":["津涯相忆近如何，芳信斜阳望不多。","文采亦思翻碧藻，匀圆初未让新荷。","晴烟乍往情难觅，画舫微黏淡欲拖。","犹幸生机常活泼，无劳催唱采萍歌。"]},{"t":"咏新萍四首 其四","f":"七言律诗","c":["水调新歌听处真，一番意绪惜芳辰。","剧怜点点临风碎，生怕纤纤贴镜频。","泛沚有痕才著色，衬花无力漫成茵。","最难年少江湖客，未见前朝送别人。"]},{"t":"四月十日偕叔兄四到云巢","f":"七言律诗","c":["四度看山到上方，天教南北任徜徉。","相逢斑白人忘杖，得饱烟霞酒谢觞。","宿雾团成郊树绿，和风吹满野花香。","莫嫌此后题诗懒，倚竹当空刻树行。"]},{"t":"归安俞烈妇吟为艺林作","f":"五言古诗","c":["延陵有淑女，少小住双溪。","嫁为俞氏妇，生年才及笄。","奉亲尽色养，相夫道无违。","乡党称闺范，德曜本齐眉。","前年涉海上，中馈事优为。","次年返故里，井臼独操持。","何天丧所天，病骨常不支。","参茸投罔效，鸾凤忽分飞。","虚占熊蛇梦，三索复不齐。","留此未忘身，罂罂将焉依。","归家别阿父，有孙弄含饴。","堂上拜阿翁，犹子养可资。","安用长独活，忍不去生埋。","含泪不能语，愿以生死辞。","一勺鸩羽毒，甘之如渴饥。","八月十二日，从容就义时。","同梦九年速，殉身三宿迟。","泉台当有路，夫妇唱与随。","我闻阿母贤，捐躯行无亏。","又闻其姑沈，赴难视如归。","渊源推所自，根本茁非歧。","精诚达地下，默鉴共在兹。","辉煌增绰禊，题表重纶丝。","为歌烈妇烈，遍闻浙水西。"]},{"t":"咏松花 其一","f":"七言律诗","c":["不独浓阴当夏凉，枝头蕊发几多长。","原知未入时花样，却好翻成古色香。","筛月粉移桐乳白，含霜晴散木棉黄。","坚心宥把诗脾洗，和露餐馀齿颊芳。"]},{"t":"咏松花 其二","f":"七言律诗","c":["满听鸣涛历乱栽，非红亦似雨飘来。","偶飞僧舍拈藤壁，閒与仙人埽石台。","翠傍金浮龙甲动，声随子落鹤粮猜。","佐他竹叶新醅熟，林外无风洒酒杯。"]},{"t":"宾于寄诗谢送秋花数种次韵复之","f":"七言律诗","c":["催钱县吏不须猜，夜半送花何处来。","几曲苕溪萦旧梦，一笼秋色报新栽。","草泥多露情都淡，风月迎人颜乍开。","何幸钝根植灵境，诗篇换得佐香醅。"]},{"t":"苔衣","f":"七言律诗","c":["青青色染认苔痕，衣上庭阶迹自存。","花气未曾因热客，春风独不谢蓬门。","争誇绣锦留新样，共说铺茵有宿根。","添得浅纹随屐印，芰荷香制可齐论。"]},{"t":"松钗","f":"七言律诗","c":["历乱苍髯集翠攒，荆钗虽异可齐观。","融成云外簪花格，压尽人间士女冠。","高挹枝头应接凤，斜穿股影讶飞鸾。","无多林下针芒露，相与同心到岁寒。"]},{"t":"秧针","f":"七言律诗","c":["好把天工巧与人，田禾初茁簇生新。","雨沾颖滑芸方润，露滴芒寒插乍匀。","柳脚添丝閒组织，鱼苗出水浑陶甄。","无边绣壤齐分刺，谁使饥躯西北民。"]},{"t":"竹粉","f":"七言律诗","c":["几丛解箨认斑斑，左右新抽未宥删。","不藉铅华归素质，要留清白在名山。","敷成薄腻开诗本，著处轻匀谢醉颜。","一笑相逢梅雪际，征衣香扑有无间。"]},{"t":"次韵送吴苍石归芜园 其一","f":"五言律诗","c":["蕉绿一窗开，期人何处来。","湖舟吟碧浪，仙梦送天台。","世事挥长剑，宏文识古罍。","閒愁偏扰我，西北泽鸿哀。"]},{"t":"次韵送吴苍石归芜园 其二","f":"五言律诗","c":["乍说银河渡，今看苕水流。","江郎工赋别，庾子惯悲秋。","野鹤情都淡，雕虫技并羞。","嗟余输半亩，无计事归求。"]},{"t":"悼亡百绝句 其一","f":"七言绝句","c":["忍到今番永诀时，卅年内助那堪思。","慕园久废吟哦事，只说悼亡不说诗。"]},{"t":"悼亡百绝句 其二","f":"七言绝句","c":["痴望齐眉别有缘，同行伉俪数无全。","不图五十吾赢二，合算人间住百年。"]},{"t":"悼亡百绝句 其三","f":"七言绝句","c":["七龄相识在黉宫，三到菰城造化工。","愿祝再生缘不绝，夫夫妇妇乐融融。"]},{"t":"悼亡百绝句 其四","f":"七言绝句","c":["东越归来十二龄，干戈满地苦伶俜。","惟知小弱存孤弟，冒险登楼血不腥。"]},{"t":"悼亡百绝句 其五","f":"七言绝句","c":["于归柔弱不胜冠，次弟堂前请晚安。","私语惟闻能孝敬，已知大义博亲欢。"]},{"t":"悼亡百绝句 其六","f":"七言绝句","c":["女伴隆冬刀尺谋，灯前衣履制从头。","羞催郎罢三更读，缓下床边两帐钩。"]},{"t":"悼亡百绝句 其七","f":"七言绝句","c":["扁舟同度越西关，遥指迁居镜水湾。","早识郎君生性冷，为邀母弟伴游山。"]},{"t":"悼亡百绝句 其八","f":"七言绝句","c":["姑如吾母最称慈，二十三年逮养迟。","负米小儿轻远别，亲承色笑赖卿知。"]},{"t":"悼亡百绝句 其九","f":"七言绝句","c":["果然饰性女箴该，小字从同早体裁。","待到有家实践归，非关教妇在初来。"]},{"t":"悼亡百绝句 其十","f":"七言绝句","c":["春秋佳景费评量，犹喜门庭爱日长。","不是登山还放棹，常添乐事纪姑嫜。"]},{"t":"悼亡百绝句 其十一","f":"七言绝句","c":["菰城生灭悼同儿，课字三千未谒师。","到底不分虚实肿，半年淡食莫能离。"]},{"t":"悼亡百绝句 其十二","f":"七言绝句","c":["尤怜荪女代劬劳，十四髫龄事事操。","忍此背亲抛弟妹，窑湾坏土北风号。"]},{"t":"悼亡百绝句 其十三","f":"七言绝句","c":["何来发剪纸人妨，谣惑城乡夕未遑。","独尔随亲苕水上，安居略不涉慌张。"]},{"t":"悼亡百绝句 其十四","f":"七言绝句","c":["一岁何堪五女殇，半生心血付苍茫。","时时收泪开颜笑，恐有悲怀触北堂。"]},{"t":"悼亡百绝句 其十五","f":"七言绝句","c":["月逢十课不知忙，风雨难联兄弟床。","心恻愚夫卖文字，寒天残漏作羹汤。"]},{"t":"悼亡百绝句 其十六","f":"七言绝句","c":["牛衣从不泣王章，世味无如道味长。","大好家声书画舫，惟携端砚寿儿郎。"]},{"t":"悼亡百绝句 其十七","f":"七言绝句","c":["母病当年独惯扶，宵来衣带解全无。","果然天性生成厚，移孝双亲孝阿姑。"]},{"t":"悼亡百绝句 其十八","f":"七言绝句","c":["亲心钟爱不矜张，裙布荆钗非俭装。","纵使豪家间往复，酬金末见入私囊。"]},{"t":"悼亡百绝句 其十九","f":"七言绝句","c":["见说家书抵万金，平安二字及佳音。","怀经十稔封如古，留取当时两地心。"]},{"t":"悼亡百绝句 其二十","f":"七言绝句","c":["针线裁缝日日须，非徒裘葛衣其夫。","偶馀尺布同零绢，犹到身边补旧无。"]},{"t":"悼亡百绝句 其二十一","f":"七言绝句","c":["相逢无不道人贤，斗起乡邻处泰然。","只为是非明不得，谗言到耳化云烟。"]},{"t":"悼亡百绝句 其二十二","f":"七言绝句","c":["累病东城薄暖天，多卿汤药上楼煎。","背人含泪申祈祷，几见愁容到我前。"]},{"t":"悼亡百绝句 其二十三","f":"七言绝句","c":["衢湖历尽转苏州，哭望慈云在上头。","赢得昆山仙眷属，结邻閒话六春秋。"]},{"t":"悼亡百绝句 其二十四","f":"七言绝句","c":["治园新筑竹篱斜，不看桃花看菜花。","岁暮归来贫亦乐，玉峰云里读书家。"]},{"t":"悼亡百绝句 其二十五","f":"七言绝句","c":["客来斗酒不须谋，剪韭治蔬尽适喉。","雅喜金鳞烹宋嫂，家家艳说是鱼球。"]},{"t":"悼亡百绝句 其二十六","f":"七言绝句","c":["每逢周急恻衷怀，终被人欺百事乖。","学到吃亏常不计，非徒宴客质金钗。"]},{"t":"悼亡百绝句 其二十七","f":"七言绝句","c":["间关远道省亲身，八十年华纪大椿。","一束蒸豚一瓶水，归宁不道婿家贫。"]},{"t":"悼亡百绝句 其二十八","f":"七言绝句","c":["十二胎生自哺劬，艰辛每岁听呱呱。","最难穷巷分无乳，走乞炎天舌本枯。"]},{"t":"悼亡百绝句 其二十九","f":"七言绝句","c":["清明荐席撤昆园，中馈劳伤不自言。","廿五月胎成半产，讳他僵病寄桑根。"]},{"t":"悼亡百绝句 其三十","f":"七言绝句","c":["苏台屡过辄迷津，拙政园迎夏景新。","彷佛西湖游侍母，荷花香里话前因。"]},{"t":"悼亡百绝句 其三十一","f":"七言绝句","c":["惠麓烹茶践约无，弇山灯事又模糊。","明知老去须行乐，偏值年年多病躯。"]},{"t":"悼亡百绝句 其三十二","f":"七言绝句","c":["告诫篷窗知不知，双双儿女未童时。","偶闻一语伤心处，爣病将成爷力衰。"]},{"t":"悼亡百绝句 其三十三","f":"七言绝句","c":["予生九战浙秋闱，供应烦卿想入非。","前度忽萌偕隐愿，慰情无复到慈帏。"]},{"t":"悼亡百绝句 其三十四","f":"七言绝句","c":["长夏奔丧暑压船，况当背疽发才痊。","咸疑亏损根犹伏，索解无从此一年。"]},{"t":"悼亡百绝句 其三十五","f":"七言绝句","c":["重阳同放海昌船，新涨初通郭店前。","劳尽心神方息足，望归游子眼犹穿。"]},{"t":"悼亡百绝句 其三十六","f":"七言绝句","c":["椿庭痛不侍弥留，送窆归从色相求。","袖出前年西法照，为摅孺慕瞩题头。"]},{"t":"悼亡百绝句 其三十七","f":"七言绝句","c":["不喜绮罗时世装，春来偏学看蚕忙。","天然好事难如愿，墙外竞多植女桑。"]},{"t":"悼亡百绝句 其三十八","f":"七言绝句","c":["要结今生不解缘，相寻踪迹若盘旋。","谁知到海仍须别，莫繫明朝对渡船。"]},{"t":"悼亡百绝句 其三十九","f":"七言绝句","c":["朝朝千里望予归，枕上应多泪暗挥。","江海卸帆馀八日，从无身后说依稀。"]},{"t":"悼亡百绝句 其四十","f":"七言绝句","c":["果知说到伤心事，远客初归伤尽心。","除去脾虚兼腹热，堪期早晚免呻吟。"]},{"t":"悼亡百绝句 其四十一","f":"七言绝句","c":["仙露连番惠罄瓶，常从长史谢零星。","终颁百合同山药，苦乏和中伴茯苓。"]},{"t":"悼亡百绝句 其四十二","f":"七言绝句","c":["深体儿曹夜勿陪，扶床强起几多回。","灯前慰我分栖稳，犹觅饧糖手送来。"]},{"t":"悼亡百绝句 其四十三","f":"七言绝句","c":["平时药裹失量裁，恨晚难将元气培。","浸晓勉为开口问，舌尖新起雪花胎。"]},{"t":"悼亡百绝句 其四十四","f":"七言绝句","c":["顾覆深情莫可描，怜他少子护长宵。","不言身热言儿热。","分宿谁知无别朝。"]},{"t":"悼亡百绝句 其四十五","f":"七言绝句","c":["苦尽常思回蔗甘，此时此理不须谈。","隔帏呼我声无力，犹讶无闻至再三。"]},{"t":"悼亡百绝句 其四十六","f":"七言绝句","c":["不讳怎知深讳难，终朝自汗叹无端。","低声但说钱刀匮，此意分明托和盘。"]},{"t":"悼亡百绝句 其四十七","f":"七言绝句","c":["习俗难移邻里家，畴凭正气压群邪。","何图词祝方宣后，唤不回头两眼斜。"]},{"t":"悼亡百绝句 其四十八","f":"七言绝句","c":["环床恸哭九人齐，老仆情真亦夜啼。","哭过五更仍不起，浑疑一睡入沈迷。"]},{"t":"悼亡百绝句 其四十九","f":"七言绝句","c":["来朝商略荐盘新，七度哀逢母忌辰。","奚不相随供馔饭？","岂真地下独依亲？"]},{"t":"悼亡百绝句 其五十","f":"七言绝句","c":["暝目未能复口开，视含苍玉莫心灰。","支肩尚有衰年婿，为抹眉头日几回。"]},{"t":"悼亡百绝句 其五十一","f":"七言绝句","c":["久谢铅华世俗装，洁身有物却初偿。","今朝薰沐朝天去。","应带江南皂荚香。"]},{"t":"悼亡百绝句 其五十二","f":"七言绝句","c":["苏绢装成侍女工，携归争欲闹儿童。","讵知从葬齐称俑，玉立双双儿席中。"]},{"t":"悼亡百绝句 其五十三","f":"七言绝句","c":["两鬓休言对未皤，柔丝争比泪丝多。","可怜儿媳分梳后，床下怎教著地拖。"]},{"t":"悼亡百绝句 其五十四","f":"七言绝句","c":["吾母怜儿汝敬夫，丝棉制被入冬铺。","要留遗泽温泉壤，权作衣衾别样呼。"]},{"t":"悼亡百绝句 其五十五","f":"七言绝句","c":["竟到阴阳各一天，草心堆里独长眠。","凭棺称谓声声咽，再与儿孙半面缘。"]},{"t":"悼亡百绝句 其五十六","f":"七言绝句","c":["帆送桐棺一夕中，武林幸得涨流通。","阿兄购取姊随至，聊慰弥留无尽衷。"]},{"t":"悼亡百绝句 其五十七","f":"七言绝句","c":["邻居女伴哭哀哀，交浅情深亦异哉。","莫解此生缘会在，人言无间溯由来。"]},{"t":"悼亡百绝句 其五十八","f":"七言绝句","c":["耳熟高堂属望殷，后来福量驾诸兄。","何图日坐长生命？","赚得贤声长久名。"]},{"t":"悼亡百绝句 其五十九","f":"七言绝句","c":["院落沈沈花影新，犹馀丹桂忆前陈。","窗中一样玲珑月，不照当时并坐人。"]},{"t":"悼亡百绝句 其六十","f":"七言绝句","c":["底是匆忙梦里逢，漫云死别去无踪。","暗流香汗关行倦，消瘦浑忘病后容。"]},{"t":"悼亡百绝句 其六十一","f":"七言绝句","c":["疏慵非坐亦非眠，絮语明明在耳边。","怕说向平家室愿，依然慰藉似生前。"]},{"t":"悼亡百绝句 其六十二","f":"七言绝句","c":["难得归来归即留，妆台无恙傍床头。","我今夜夜将名唤，不碍灵魂飞上楼。"]},{"t":"悼亡百绝句 其六十三","f":"七言绝句","c":["惊醒幻境费疑猜，罗帐低垂寂不开。","又恐常常枯老泪，期卿五夜一归来。"]},{"t":"悼亡百绝句 其六十四","f":"七言绝句","c":["非独关心死后期，结缡岁序也无疑。","朝来亥月刚逢四，三十年前花烛时。"]},{"t":"悼亡百绝句 其六十五","f":"七言绝句","c":["城外潮惊同梦醒，东来西去数曾经。","今时若不分生死，依旧联床夜夜听。"]},{"t":"悼亡百绝句 其六十六","f":"七言绝句","c":["浣濯衣衫初不知，从今检点要亲持。","纵令一领兼旬著，无复帘前说换迟。"]},{"t":"悼亡百绝句 其六十七","f":"七言绝句","c":["连宵窗破朔风寒，谁把棉衣制就看？","堪笑阿爷兼阿母，孝围影里护儿单。"]},{"t":"悼亡百绝句 其六十八","f":"七言绝句","c":["望断床前香稻汤，晓来无计润枯肠。","盘匜特遣群儿奠，聊报生平举按庄。"]},{"t":"悼亡百绝句 其六十九","f":"七言绝句","c":["偶向江塘豁远瞳，谁家眷属出花丛？","疑卿两度看潮后，识否家山遥指中。"]},{"t":"悼亡百绝句 其七十","f":"七言绝句","c":["是真是假认前身，描就遗容不染尘。","归到头来都是假，何妨假者奉为真。"]},{"t":"悼亡百绝句 其七十一","f":"七言绝句","c":["有亭有石有池塘，到此如归子女狂。","谁料含杯朋满座，岁周齐为尔治丧。"]},{"t":"悼亡百绝句 其七十二","f":"七言绝句","c":["从俗营斋是也非，无多焚楮作钱飞。","冥官若问夫何吝，道是虞江老布衣。"]},{"t":"悼亡百绝句 其七十三","f":"七言绝句","c":["启灵发纼告从容，宏毅斋前烛泪浓。","默默非真无验兆，如卿到底是温恭。"]},{"t":"悼亡百绝句 其七十四","f":"七言绝句","c":["何物儒生动众知，盛筵祖饯北门时。","犹虞越礼干阴谴，功布铭旌分别持。"]},{"t":"悼亡百绝句 其七十五","f":"七言绝句","c":["船窗人静鼾声稠，莫见桥过呼舵头。","卓立身边新木主，同听夜雨到杭州。"]},{"t":"悼亡百绝句 其七十六","f":"七言绝句","c":["忆艮山门夜泊船，客秋凉透校书天。","今朝枯对无聊赖，为遣儿童剪纸钱。"]},{"t":"悼亡百绝句 其七十七","f":"七言绝句","c":["湖山西望暮云封，雁序孤沈六越冬。","相约明朝东渡去，晓烟定破两高峰。"]},{"t":"悼亡百绝句 其七十八","f":"七言绝句","c":["低声时唤好随馀，魂帛灵幡共一舆。","莫讶大江飞渡否，乌蓬到越梦非虚。"]},{"t":"悼亡百绝句 其七十九","f":"七言绝句","c":["船头船尾两灵牌，先后拈香理亦谐。","枕里不堪回首处，此身同梦与同怀。"]},{"t":"悼亡百绝句 其八十","f":"七言绝句","c":["回望钱清故里赊，梅山东去夕阳斜。","为谈蛏浦避兵事，不见当时仲姊家。"]},{"t":"悼亡百绝句 其八十一","f":"七言绝句","c":["称山晓渡浪翻银，风雨随潮危更频。","莫挽灵舆帆尽侧，惊心生死满船人。"]},{"t":"悼亡百绝句 其八十二","f":"七言绝句","c":["羽士招魂返故乡，素帏分列费裁量。","酸心片语宣邻媪，竟把新房作孝堂。"]},{"t":"悼亡百绝句 其八十三","f":"七言绝句","c":["望母遗阡岭隔低，灵光来去路无迷。","泉台团聚惟迟我，寄语诸兄护弟妻。"]},{"t":"悼亡百绝句 其八十四","f":"七言绝句","c":["栗主重携怀袖堪，犹虞复道与层岚。","休嫌寂寞留宗佑，待我他年共一龛。"]},{"t":"悼亡百绝句 其八十五","f":"七言绝句","c":["生前离散最销魂，今日依然别墓门。","江上晓风分送处，不知北辙或南辕。"]},{"t":"悼亡百绝句 其八十六","f":"七言绝句","c":["此行也算是生离，转讶缄书无复时。","痴愿一端今胜昔，果能梦里远相随。"]},{"t":"悼亡百绝句 其八十七","f":"七言绝句","c":["偶闻虞俗捣年糕，冬至阳生屈指遭。","犹忆前时谆瞩付，饷宾荐祖为谁劳？"]},{"t":"悼亡百绝句 其八十八","f":"七言绝句","c":["无形奇火起回廊，孤仆龙钟伴女郎。","不是魂归先呵护，奚能阻得北风狂？"]},{"t":"悼亡百绝句 其八十九","f":"七言绝句","c":["漫愁雨雪湿衣襟，兄墓新成穴乍临。","道左为卿通慰藉，携锄添掘水沟深。"]},{"t":"悼亡百绝句 其九十","f":"七言绝句","c":["忽忽离尘百日间，姚江幸我近勾留。","诸儿遥荐东塘里，可有飞魂北渡不？"]},{"t":"悼亡百绝句 其九十一","f":"七言绝句","c":["长安西棹即盐官，偕往偕来行不难。","讵料入宫真莫见，无非梦裹说团栾。"]},{"t":"悼亡百绝句 其九十二","f":"七言绝句","c":["且课儿曹夜作书，机声不复冷催馀。","何堪月上黄昏后，独向池边听跃鱼。"]},{"t":"悼亡百绝句 其九十三","f":"七言绝句","c":["人亡犹得说琴存，人断琴弦莫与论。","地白林空残月夜，凄风旧调孰新翻。"]},{"t":"悼亡百绝句 其九十四","f":"七言绝句","c":["珍重添衣禦雪风，天公白遍浙西东。","不图寒恋同衾者，偏在郊原衰草中。"]},{"t":"悼亡百绝句 其九十五","f":"七言绝句","c":["每逢佳节拜团圆，今夕年除形影单。","依样筵前双画烛，无端催烬一条残。"]},{"t":"悼亡百绝句 其九十六","f":"七言绝句","c":["岸南归殡北归魂，漫道幽明隔者番。","遥指山头迎夏盖，缟衣盍认自家门。"]},{"t":"悼亡百绝句 其九十七","f":"七言绝句","c":["烂醉归来说贺年，灯灺人散和衣眠。","而今冷醒藤床后，未见肩头覆薄棉。"]},{"t":"悼亡百绝句 其九十八","f":"七言绝句","c":["家祭原从生者禄，休将官诰此时疑。","辉煌补服描鸡鸠，权把匡宗后嗣期。"]},{"t":"悼亡百绝句 其九十九","f":"七言绝句","c":["镇日端居苦索思，遗容相对寂无辞。","算来汝亦多情甚，我在尘红那得知？"]},{"t":"悼亡百绝句 其一○○","f":"七言绝句","c":["时贤题赞尽留名，逊我清言道实情。","吟罢巳盈诗百首，要知字字泪珠成？"]}]};